import subprocess, collections

B = "target/x86_64-unknown-linux-musl/release/lypning"
out = subprocess.run(["nm", "--size-sort", "-S", "--demangle", B], capture_output=True, text=True).stdout
buckets = collections.Counter()
total = 0
for line in out.splitlines():
    p = line.split(None, 3)
    if len(p) < 4:
        continue
    try:
        sz = int(p[1], 16)
    except ValueError:
        continue
    n = p[3]
    total += sz
    if n.startswith("lypning::"):
        buckets["lypning::" + n.split("::")[1]] += sz
    elif "core::fmt" in n:
        buckets["core::fmt (float/int formatting)"] += sz
    elif "panic" in n or "unwind" in n or "backtrace" in n:
        buckets["panic / unwind"] += sz
    elif n.startswith(("core::", "<core::")):
        buckets["core:: rest"] += sz
    elif n.startswith(("alloc::", "<alloc::")):
        buckets["alloc::"] += sz
    elif n.startswith(("std::", "<std::")):
        buckets["std::"] += sz
    else:
        buckets["musl libc + other"] += sz

print("attributed %d bytes across %d symbols\n" % (total, len(out.splitlines())))
for k, v in buckets.most_common(16):
    print("  %-34s %8d  (%4.1f%%)" % (k, v, 100 * v / total))

