def _type_name(obj):
    try:
        tn = type(obj)
    except Exception:
        return None
    if hasattr(tn, "__name__"):
        name = tn.__name__
        module = getattr(tn, "__module__", "") or ""
        if not module or module == "builtins" or module == "__builtin__":
            return name
        return module + "." + name
    return None

