import json, os, re, sys

def walk(root):
    out = []
    if not os.path.exists(root):
        return out
    stack = [root]
    while stack:
        cur = stack.pop()
        entries = sorted(os.listdir(cur))
        for name in reversed(entries):
            p = os.path.join(cur, name)
            if os.path.isdir(p):
                stack.append(p)
            elif os.path.isfile(p) and name.endswith(".jsonl"):
                out.append(p)
    out.sort()
    return out


