import re, os, sys

def glob_md(dirname):
    try:
        names = os.listdir(dirname)
    except OSError:
        return []
    out = []
    for n in names:
        if not n.endswith('.md'):
            continue
        p = dirname + '/' + n
        if os.path.isfile(p):
            out.append(p)
    return sorted(out)

