import re, os

def glob_md(dir_path):
    """Return sorted list of full paths to *.md files in dir_path (non-recursive), mimicking Path.glob('*.md')"""
    try:
        entries = os.listdir(dir_path)
    except OSError:
        return []
    result = []
    for e in sorted(entries):
        if e.endswith('.md'):
            full = os.path.join(dir_path, e)
            if os.path.isfile(full):
                result.append(full)
    return result

