                                    m += 1
                                    wsm += 1
                                if wsm > 0:
                                    if s.startswith('as', m):
                                        mm = m + 2
                                        prev2 = s[mm - 1] if mm > 0 else ''
                                        rightc2 = s[mm] if mm < n else ''
                                        if not (word_chars(prev2) or rightc2.isalnum() or rightc2 == '_' or word_chars(rightc2)):
                                            ww = mm
                                            wsw = 0
                                            while ww < n and (s[ww] == ' ' or s[ww] == '\t'):
                                                ww += 1
                                                wsw += 1
                                            if wsw > 0:
                                                if ww < n and (s[ww].isalnum() or s[ww] == '_' or word_chars(s[ww])):
                                                    return True
