def match_start_or_after_space(s, token, before_ok=None):
    # Find every occurrence of `token` in s whose preceding char (if any) is:
    #   - start of string/line  -> always allowed (start / \n)
    #   - whitespace            -> allowed
    #   - otherwise             -> only if before_ok(prev_char) is True
    # This covers r'(?<![.\w])seed\s*\(' when called with token='seed'.
    results = []
    i = 0
    L = len(s)
    while True:
        j = s.find(token, i)
        if j < 0:
            break
        prev_ok = True
        if j > 0:
            c = s[j-1]
            if c == '\n':
                prev_ok = True
            elif c.isspace():
                prev_ok = True
            else:
                if before_ok is not None:
                    prev_ok = bool(before_ok(c))
                else:
                    # default: disallow dot and word chars (matches [.\w])
                    if c == '.' or c.isalnum() or c == '_':
                        prev_ok = False
                    else:
                        prev_ok = True
        if prev_ok:
            results.append(j)
        i = j + 1
    return results

