import json

def dumps_str(s):
    result = ['"']
    for ch in s:
        if ch == '"':
            result.append('\\"')
        elif ch == '\\':
            result.append('\\\\')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\r':
            result.append('\\r')
        elif ch == '\t':
            result.append('\\t')
        elif ord(ch) < 0x20:
            code = ord(ch)
            if code > 0xFFFF:
                # surrogate pair
                code -= 0x10000
                high = 0xD800 + (code >> 10)
                low = 0xDC00 + (code & 0x3FF)
                result.append('\\u%04x\\u%04x' % (high, low))
            else:
                result.append('\\u%04x' % code)
        else:
            result.append(ch)
    result.append('"')
    return ''.join(result)


