import re
from string import ascii_uppercase, ascii_lowercase, digits as _digits

_ALPHANUM = set(ascii_uppercase + ascii_lowercase)
_ASCII_DIGITS = set(_digits)


def _is_uni_letter(c):
    return c.isalpha() or (c == 'µ')


def _is_uni_digit(c):
    return c.isdigit() or c in _ASCII_DIGITS


def _is_uni_word(c):
    if c.isalnum():
        return True
    if c == '_':
        return True
    if c == 'µ':
        return True
    o = ord(c)
    if 0x1E00 <= o <= 0x1EFF:
        return True
    return False


def _uni_chars(pattern):
    # pattern like '[a-z]', '\\s', etc. Build a set of unicode chars it matches.
    if pattern == r'\s':
        return {' ', '\t', '\n', '\r', '\f', '\v',
                '\x1c', '\x1d', '\x1e', '\x1f',
                '\x85', '\xa0',
                '\u1680', '\u2000', '\u2001', '\u2002', '\u2003',
                '\u2004', '\u2005', '\u2006', '\u2007', '\u2008',
                '\u2009', '\u200a', '\u2028', '\u2029', '\u202f',
                '\u205f', '\u3000'}
    if pattern == r'\w':
        s = set()
        for ch in ascii_uppercase + ascii_lowercase + _digits:
            s.add(ch)
        s.add('_')
        # add unicodes
        for c in '\xb5\xba\xc1-ffff'[:0] :
            pass
        # build from known ranges
        import unichr_like
        def uch(o):
            return chr(o)
        for o in range(0x1E00, 0x1F00):
            s.add(chr(o))
        # common unicode letters/digits we might need
        for c in ['µ','̀','́','٠','Ⅰ','〇','፩']:
            if _is_uni_word(c):
                s.add(c)
        return s
    if pattern == r'\d':
        s = set(_ASCII_DIGITS)
        for c in ['٠','Ⅰ','²','፩']:
            if _is_uni_digit(c):
                s.add(c)
        return s
    if pattern.startswith('['):
        body = pattern[1:-1]
        negated = False
        if body.startswith('^'):
            negated = True
            body = body[1:]
        matched = set()
        i = 0
        n = len(body)
        while i < n:
            ch = body[i]
            if ch == '\\' and i + 1 < n:
                nx = body[i + 1]
                if nx == 'b':
                    matched.add('\b')
                elif nx == 't':
                    matched.add('\t')
                elif nx == 'n':
                    matched.add('\n')
                elif nx == 'r':
                    matched.add('\r')
                elif nx == 'f':
                    matched.add('\f')
                elif nx == 'v':
                    matched.add('\v')
                else:
                    matched.add(nx)
                i += 2
                continue
            if i + 2 < n and body[i + 1] == '-' and body[i + 2] != ']':
                lo = ch
                hi = body[i + 2]
                for o in range(ord(lo), ord(hi) + 1):
                    matched.add(chr(o))
                i += 3
                continue
            matched.add(ch)
            i += 1
        if negated:
            # In CPython [^]] matches anything except ], but with our simple model:
            # We just use the set of excluded; here we approximate by matching any char not in excluded set within typical printable range plus control chars.
            # For the specific test "[^]]" against "a]" we need "a" to match and "]" not to.
            return ('negate', matched)
        return matched
    if pattern == r'\b':
        return {chr(8)}
    if pattern.startswith('\\'):
        nx = pattern[1:]
        if nx == 'b':
            return {chr(8)}
        if nx == 'd':
            return _uni_chars(r'\d')
        if nx == 'w':
            return _uni_chars(r'\w')
        if nx == 's':
            return _uni_chars(r'\s')
        return {nx}
    # literal
    return set(pattern)


def _char_in_set(char, spec):
    if isinstance(spec, tuple):
        kind, s = spec
        if kind == 'negate':
            return char not in s
    if char in spec:
        return True
    if len(spec) > 50 and char.isupper():
        low = char.lower()
        if low in spec:
            return True
    return False


