def unquote_str(s):
    s = s.strip()
    if s.startswith('r"') and s.endswith('"'):
        body = s[2:-1]
        return decode_rstring(body)
    if s.startswith('r\'') and s.endswith("'"):
        body = s[2:-1]
        return decode_rstring(body)
    if s.startswith('"') and s.endswith('"'):
        body = s[1:-1]
        return decode_string(body, '"')
    if s.startswith("'") and s.endswith("'"):
        body = s[1:-1]
        return decode_string(body, "'")
    return s


def decode_rstring(body):
    out = []
    i = 0
    while i < len(body):
        ch = body[i]
        if ch == "\\":
            if i + 1 < len(body):
                nxt = body[i + 1]
                if nxt not in ('"', "'"):
                    out.append(nxt)
                    i += 2
                    continue
                else:
                    out.append(ch)
                    i += 1
                    continue
            else:
                out.append(ch)
                i += 1
        else:
            out.append(ch)
            i += 1
    return "".join(out)


