def fmt(spec, val):
    sign = 0
    alt = False
    zero_fill = False
    pad = ''
    prec = None
    conv = '?'
    i = 1
    while i < len(spec):
        c = spec[i]
        if c == '#':
            alt = True
            i += 1
        elif c == '0' and not zero_fill and (i+1 < len(spec) and (spec[i+1].isdigit() or spec[i+1] in '+- ')):
            zero_fill = True
            i += 1
        elif c in ' +-':
            pad = c
            i += 1
        elif c.isdigit():
            start = i
            while i < len(spec) and spec[i].isdigit():
                i += 1
            w = int(spec[start:i])
            if zero_fill:
                if w > 0:
                    pad = str(w)
                else:
                    pad = ''
            else:
                pad = str(w)
        elif c == '.':
            i += 1
            pstart = i
            while i < len(spec) and spec[i].isdigit():
                i += 1
            if pstart < i:
                prec = int(spec[pstart:i])
            else:
                prec = 0
        elif c.isalpha() and i == len(spec)-1 or (c.isalpha() and i+1 == len(spec)):
            conv = c
            i += 1
            break
        else:
            i += 1
    # parse done
    s = None
    try:
        if conv == 'd':
            n = int(val)
            digits = repr(abs(n))
            sg = '-' if n < 0 else ('+' if pad=='' else '')
            if pad=='+' and n>=0: sg='+'
            elif pad=='-' : sg=''
            elif n<0: sg='-'
            else: sg=''
            out = sg + digits.ljust(prec) if prec is not None and prec>len(digits) else (sg+digits)
            if prec is not None and len(digits) > prec:
                raise Exception("not enough precision")
            width = len(out)
            need = len(pad) - width if len(pad)>width else 0
            if zero_fill:
                out = sg + '0'*need + digits
            else:
                fillc = pad[0] if pad else ' '
                if pad=='+' or pad=='-':
                    out = sg + digits
                    total = len(pad)-len(sg+len(digits)) if False else 0
                out = out.rjust(len(pad), fillc) if len(pad)>0 else out
            s = out
        elif conv == 'x' or conv == 'X':
            n = int(val)
            if n < 0:
                hex_d = hex(n)[3:]
                sg = '-'
            else:
                hex_d = hex(n)[2:]
                sg = '+' if pad=='+' else ''
            if conv == 'X':
                hex_d = hex_d.upper()
            out = sg + hex_d.ljust(prec) if prec is not None and prec>len(hex_d) else (sg+hex_d)
            if prec is not None and len(hex_d)>prec:
                raise Exception("not enough precision")
            total_len = len(out)
            need = len(pad) - total_len
            if need > 0:
                if zero_fill:
                    out = sg + '0'*need + hex_d
                else:
                    fillc = pad[0]
                    out = out.rjust(len(pad), fillc)
            s = out
        elif conv == 'o':
            n = int(val)
            if n < 0:
                o_d = oct(n)[4:]
                sg = '-'
            else:
                o_d = oct(n)[2:]
                sg = '+' if pad=='+' else ''
            out = sg + o_d.ljust(prec) if prec is not None and prec>len(o_d) else (sg+o_d)
            if prec is not None and len(o_d)>prec:
                raise Exception("not enough precision")
            need = len(pad)-len(out)
            if need>0:
                if zero_fill:
                    out = sg + '0'*need + o_d
                else:
                    fillc = pad[0]
                    out = out.rjust(len(pad), fillc)
            s = out
        elif conv == 's':
            txt = str(val)
            cut = prec if prec is not None else len(txt)
            cut = min(cut, len(txt))
            out = txt[:cut]
            need = len(pad)-len(out)
            if need>0:
                fillc = pad[0]
                if pad=='+' or pad=='-' or pad==' ':
                    pass
                if len(pad)>=1:
                    fc = pad[0]
                else:
                    fc=' '
                if pad and pad[0]=='-' :
                    out = out.ljust(len(pad), ' ')
                else:
                    out = out.rjust(len(pad), fc)
            s = out
        elif conv == 'c':
            if prec is not None and prec == 0:
                ch = chr(int(val)%256) if isinstance(val,(int,bool)) else ''
            else:
                ch = chr(int(val)%256)
            out = ch
            need = len(pad)-len(out)
            if need>0:
                fillc = pad[0] if pad else ' '
                out = out.rjust(len(pad), fillc)
            s = out
        else:
            s = '?'
    except Exception as e:
        return "ValueError: %s" % e
    return s

