import sys

def percent_format(fmt, v):
    # Simple parser for the limited set of conversions needed.
    i = 0
    out = []
    while i < len(fmt):
        ch = fmt[i]
        if ch != '%':
            out.append(ch)
            i += 1
            continue
        # found %
        start = i
        i += 1
        # flags
        flags = ''
        while i < len(fmt) and fmt[i] in '-+ #0':
            flags += fmt[i]
            i += 1
        # width (optional digits or *)
        width = None
        if i < len(fmt) and (fmt[i].isdigit() or fmt[i] == '*'):
            w = ''
            while i < len(fmt) and (fmt[i].isdigit() or fmt[i] == '*'):
                w += fmt[i]
                i += 1
            if '*' in w:
                raise ValueError('* not supported')
            else:
                width = int(w)
        # precision
        prec = None
        if i < len(fmt) and fmt[i] == '.':
            i += 1
            p = ''
            if i < len(fmt) and fmt[i].isdigit():
                while i < len(fmt) and fmt[i].isdigit():
                    p += fmt[i]
                    i += 1
                prec = int(p)
            else:
                prec = 0
                # consume? no, next char is conversion
        if i >= len(fmt):
            raise ValueError('incomplete format')
        conv = fmt[i]
        i += 1
        spec = fmt[start:i]

        try:
            # emulate Python's old-style formatting
            if conv == 'd':
                val = v
                if isinstance(val, bool):
                    val = int(val)
                if not isinstance(val, int):
                    raise TypeError("not an integer")
                s = str(val)
                if s.startswith('-'):
                    neg = True
                    body = s[1:]
                else:
                    neg = False
                    body = s
                if prec is not None:
                    if prec > 0 and len(body) < prec:
                        body = '0' * (prec - len(body)) + body
                if neg:
                    res = '-' + body
                else:
                    res = body
                if width is not None:
                    if '#' in flags:
                        pass
                    fill = '0' if ('0' in flags and '-' not in flags) else ' '
                    pad = max(0, width - len(res))
                    if '-' in flags:
                        res = res + ' ' * pad
                    else:
                        res = fill * pad + res
                elif '#' in flags:
                    pass
                out.append(res)
            elif conv in ('x', 'X', 'o', 'b'):
                val = v
                if isinstance(val, bool):
                    val = int(val)
                if not isinstance(val, int):
                    raise TypeError("not an integer")
                if val < 0:
                    if conv == 'x':
                        s = hex(val)[2:]
                        prefix = '0x'
                        alt_prefix = '0x'
                    elif conv == 'X':
                        s = hex(val)[2:].upper()
                        prefix = '0X'
                        alt_prefix = '0X'
                    elif conv == 'o':
                        s = oct(val)[2:]
                        prefix = '0o'
                        alt_prefix = '0o'
                    elif conv == 'b':
                        s = bin(val)[2:]
                        prefix = '0b'
                        alt_prefix = '0b'
                    neg = True
                    body = s
                else:
                    neg = False
                    if conv == 'x':
                        s = format(val, 'x')
                        prefix = '0x'
                    elif conv == 'X':
                        s = format(val, 'X')
                        prefix = '0X'
                    elif conv == 'o':
                        s = format(val, 'o')
                        prefix = '0o'
                    elif conv == 'b':
                        s = format(val, 'b')
                        prefix = '0b'
                    body = s
                if prec is not None and prec > 0 and len(body) < prec:
                    body = '0' * (prec - len(body)) + body
                if '#' in flags:
                    body = prefix + body
                if neg:
                    res = '-' + body
                else:
                    res = body
                if width is not None:
                    fill = '0' if ('0' in flags and '-' not in flags) else ' '
                    pad = max(0, width - len(res))
                    if '-' in flags:
                        res = res + ' ' * pad
                    else:
                        res = fill * pad + res
                out.append(res)
            elif conv == 'c':
                if isinstance(v, int):
                    c = chr(v)
                elif isinstance(v, bytes):
                    c = bytes([v]).decode('latin1')
                else:
                    raise TypeError('argument must be int')
                if prec is not None:
                    if prec < len(c):
                        c = c[:prec]
                if width is not None:
                    if '-' in flags:
                        c = c.ljust(width)
                    else:
                        c = c.rjust(width)
                out.append(c)
            elif conv == 's':
                if isinstance(v, str):
                    s = v
                elif isinstance(v, bytes):
                    s = v.decode('latin1')
                else:
                    s = str(v)
                if prec is not None:
                    if prec < len(s):
                        s = s[:prec]
                if width is not None:
                    if '-' in flags:
                        s = s.ljust(width)
                    else:
                        s = s.rjust(width)
                out.append(s)
            elif conv == '%':
                out.append('%')
            else:
                # fallback to actual CPython behavior by simulating via __mod__
                # but we can't; just raise so caller catches
                raise ValueError('unsupported conversion')
        except Exception as e:
            out.append("%s: %s" % (type(e).__name__, e))
        continue
    return ''.join(out)


