        flags.append(s[i])
        i += 1
    width = ''
    while i < len(s) and s[i].isdigit():
        width += s[i]
        i += 1
    precision = ''
    if i < len(s) and s[i] == '.':
        i += 1
        while i < len(s) and s[i].isdigit():
            precision += s[i]
            i += 1
    # Length modifier (h, l, L) - ignore for now
    if i < len(s) and s[i] in 'hlL':
        i += 1
    conv = s[i] if i < len(s) else ''

    has_flag = lambda f: f in flags
    width_int = int(width) if width else None
    prec_int = int(precision) if precision != '' else None

    try:
        if conv == 'd':
            iv = int(v)
            sign = '-' if iv < 0 else ''
            if has_flag('+') and iv >= 0:
                sign = '+'
            abs_iv = abs(iv)
            if prec_int is not None:
                digits = str(abs_iv).zfill(prec_int)
            else:
                digits = str(abs_iv)
            if has_flag('#'):
                pass  # no alt form for d
            result = sign + digits
            if width_int is not None:
                total_w = len(result)
                if total_w < width_int:
                    pad = width_int - total_w
                    if '-' in flags:
                        result = result.ljust(width_int)
                    elif '0' in flags:
                        if sign:
                            result = sign + ('0' * pad) + digits
                        else:
                            result = result.rjust(width_int, '0')
                    else:
                        result = result.rjust(width_int, ' ')
