                             '0X' if (conv == 'X' and has_flag('#') and abs_iv != 0) else ''
                    hex_digits = prefix + base_part.rjust(prec_int, '0')
            result = sign + hex_digits
            if width_int is not None:
                total_w = len(result)
                if total_w < width_int:
                    pad = width_int - total_w
                    if '-' in flags:
                        result = result.ljust(width_int)
                    elif '0' in flags:
                        if sign:
                            rest = hex_digits
                            if len(rest) < pad:
