        try: raise TypeError("an integer is required")
        except TypeError as e:
            return "TypeError: %s" % (e,)

    if precision is not None:
        # Binary representation
        if value == 0:
            result = '0' * precision if precision > 0 else '0'
        elif value > 0:
            binary = bin(value)[2:]
            if len(binary) < precision:
                result = '0' * (precision - len(binary)) + binary
            else:
                result = binary
        else:
            # Negative: sign followed by absolute value binary
            abs_binary = bin(abs(value))[2:]
            if len(abs_binary) < precision:
                abs_part = '0' * (precision - len(abs_binary)) + abs_binary
            else:
                abs_part = abs_binary
            result = '-' + abs_part
    else:
        if value == 0:
            result = '0'
        elif value > 0:
            result = bin(value)[2:]
        else:
            result = '-' + bin(abs(value))[2:]

