import sys

def is_nondeterministic(obj):
    if isinstance(obj, dict):
        prog = obj.get('program', '')
    else:
        prog = getattr(obj, 'program', '')
    if 'random' in prog or 'time' in prog:
        return True
    return False

def make_obj(prog):
    class C:
        pass
    c = C()
    c.program = prog
    c.extra = {}
    return c

d = {'program': 'import random\nprint(random.random())'}
print('dict  ->', is_nondeterministic(d))

e = make_obj('import random\nprint(random.random())')
print('object->', is_nondeterministic(e))

t_dict = {'program': 'import time;print(time.time())'}
print('time dict ->', is_nondeterministic(t_dict))

t_obj = make_obj('import time;print(time.time())')
print('time obj  ->', is_nondeterministic(t_obj))

