    d['/'] = 63
    return d

def strict_decode(data):
    # Mirrors base64.b64decode(validate=True) which calls binascii.a2b_base64(strict_mode=True)
    d = b64alphabet()
    if len(data) % 4 == 1:
        raise ValueError("Invalid base-64-encoded string passed; length must be a multiple of 4.")
    ngroups = len(data) // 4
    result = bytearray()
    group_index = 0
    for gi in range(ngroups):
        group = data[group_index * 4: (group_index + 1) * 4]
        pad_pos = -1
        if group[0] == ord('='):
            # If the first char is '=', we expect the whole group to be '='
            for i in range(1, 4):
                if group[i] != ord('='):
                    raise ValueError("'=' found after non-'=' character.")
            continue
        elif group[1] == ord('='):
            pad_pos = 1
            for i in range(2, 4):
                if group[i] != ord('='):
                    raise ValueError("'=' found after non-'=' character.")
        elif group[2] == ord('='):
            pad_pos = 2
            if group[3] != ord('='):
                raise ValueError("'=' found after non-'=' character.")

        vals = []
        for ch in group[:pad_pos]:
            c = chr(ch)
            if c not in d:
                raise ValueError("'%s' is not a valid base-64 encoded byte." % c)
            vals.append(d[c])

        num_bits = 6 * len(vals)
        val_int = 0
        for v in vals:
            val_int = (val_int << 6) | v

        total_bytes = num_bits // 8
        if total_bytes > 3:
            total_bytes = 3
        for bi in range(total_bytes):
            shift = (total_bytes - 1 - bi) * 8
            byte_val = (val_int >> shift) & 0xFF
            result.append(byte_val)

    return bytes(result)

