import sys

def _bytes_hex(data, sep=None, bytes_per_sep=1):
    # Validate arguments exactly as CPython 3.8+ does for bytes.hex()
    if not isinstance(sep, (type(None), str, bytes)):
        raise TypeError("sep must be None, a string, or bytes")
    if isinstance(sep, bytes) and len(sep) != 1:
        raise ValueError("separator must be 0 or 1 character long")
    if not isinstance(bytes_per_sep, int):
        raise TypeError("an integer is required")
    if bytes_per_sep < 1:
        raise ValueError("must be at least one byte per separator")

    n = len(data)
    out = bytearray()
    i = 0
    while i < n:
        chunk = data[i:i + bytes_per_sep]
        if isinstance(sep, type(None)):
            out += chunk.hex().encode('ascii')
        else:
            sep_bytes = sep.encode('utf-8') if isinstance(sep, str) else sep
            hex_part = chunk.hex()
            out += hex_part.encode('ascii')
            if i + bytes_per_sep < n:
                out += sep_bytes
        i += bytes_per_sep
    return bytes(out)


