def _parse_value(s):
    s = s.strip()
    if s == 'None':
        return None
    if s == 'True':
        return True
    if s == 'False':
        return False
    if s.startswith('"') and s.endswith('"') and len(s) >= 2:
        inner = s[1:-1]
        return inner
    if s.startswith("'") and s.endswith("'") and len(s) >= 2:
        inner = s[1:-1]
        return inner
    if s.startswith('b"') and s.endswith('"') and len(s) >= 3:
        inner = s[2:-1]
        return inner.encode('latin-1')
    if s.startswith("b'") and s.endswith("'") and len(s) >= 3:
        inner = s[2:-1]
        return inner.encode('latin-1')
    try:
        return int(s)
    except ValueError:
        pass
    try:
        return float(s)
    except ValueError:
        pass
    raise ValueError("cannot parse value: %r" % s)


