import ast, builtins

def safe_eval(expr_str):
    tree = ast.parse(expr_str, mode='eval')

    allowed = {'bytes', 'bytearray'}
    for name in dir(builtins):
        obj = getattr(builtins, name)
        if callable(obj):
            allowed.add(name)

    def _eval(node, names):
        if isinstance(node, ast.Expression):
            return _eval(node.body, names)
        elif isinstance(node, ast.Call):
            func = _eval(node.func, names)
            args = [_eval(a, names) for a in node.args]
            kwds = {}
            for kw in node.keywords:
                key = _eval(kw.arg, names) if kw.arg is None else kw.arg
                kwds[key] = _eval(kw.value, names)
            return func(*args, **kwds)
        elif isinstance(node, ast.Name):
            if node.id not in names and node.id not in allowed:
                raise NameError("name '%s' is not defined" % node.id)
            if node.id in names:
                return names[node.id]
            return getattr(builtins, node.id)
        elif isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Bytes):
            return node.s
        elif isinstance(node, ast.Attribute):
            obj = _eval(node.value, names)
            return getattr(obj, node.attr)
        else:
            raise TypeError("unsupported expression type: %s" % type(node).__name__)

    return _eval(tree, {})

