def _bytes_hex(b, sep, bytes_per_sep):
    if sep is None:
        if not isinstance(bytes_per_sep, int) or isinstance(bytes_per_sep, bool) or bytes_per_sep < 1:
            raise TypeError("hex(): 'bytes_per_sep' must be greater than or equal to 1")
        return b.hex()
    # type checks matching CPython
    if not isinstance(sep, (str, bytes)):
        raise TypeError("sep must be str or bytes object")
    if len(sep) != 1:
        raise TypeError("sep must have length of one")
    if not isinstance(bytes_per_sep, int) or isinstance(bytes_per_sep, bool) or bytes_per_sep < 1:
        raise TypeError("hex(): 'bytes_per_sep' must be greater than or equal to 1")

    if isinstance(b, bytearray):
        data = bytes(b)
    else:
        data = b

    hex_str = bytes(data).hex()

    n = len(data)
    chunks = []
    for i in range(0, n, bytes_per_sep):
        end = i + bytes_per_sep
        piece = hex_str[2 * i : 2 * end]
        chunks.append(piece)
        if end < n:
            if isinstance(sep, str):
                chunks.append(sep)
            else:
                chunks.append(sep.decode('latin-1'))

    return ''.join(chunks)


def _call_hex(obj, args, kwargs):
    # signature: bytes.hex(sep=None, *, bytes_per_sep=1)
    if len(args) > 1:
        raise TypeError("hex() takes at most 1 argument (%d given)" % len(args))
    # process positional
    sep = None
    bps = 1
    if len(args) == 1:
        sep = args[0]
    # keyword overrides
    if 'sep' in kwargs:
        sep = kwargs['sep']
    if 'bytes_per_sep' in kwargs:
        bps = kwargs['bytes_per_sep']
    # remaining unexpected keywords
    expected_keys = {'sep', 'bytes_per_sep'}
    for k in kwargs:
        if k not in expected_keys:
            raise TypeError("hex() got an unexpected keyword argument '%s'" % k)

    # duplicate check: if positional given and 'sep' keyword also given -> error
    if len(args) == 1 and 'sep' in kwargs:
        raise TypeError("hex() got multiple values for argument 'sep'")

    return _bytes_hex(obj, sep, bps)


