def hex_method(self, *args, **kwargs):
    sep = None
    bytes_per_sep = 1
    if len(args) == 1:
        sep = args[0]
    elif len(args) == 2:
        sep = args[0]
        bytes_per_sep = args[1]
    if 'sep' in kwargs:
        sep = kwargs['sep']
    if 'bytes_per_sep' in kwargs:
        bytes_per_sep = kwargs['bytes_per_sep']

    # Check for unexpected keyword arguments
    for key in kwargs:
        if key not in ('sep', 'bytes_per_sep'):
            raise TypeError("hex() got an unexpected keyword argument '%s'" % key)

    # Validate sep
    if sep is not None:
        if not isinstance(sep, str) and not isinstance(sep, bytes):
            raise TypeError("sep must be str or bytes, not %s" % type(sep).__name__)
        if isinstance(sep, str):
            if len(sep) != 1:
                raise ValueError("separator must be a single character")
        else:
            if len(sep) != 1:
                raise ValueError("separator must be a single byte")

    # Validate bytes_per_sep
    if not isinstance(bytes_per_sep, int) or isinstance(bytes_per_sep, bool):
        raise TypeError("bytes_per_sep must be an integer, not %s" % type(bytes_per_sep).__name__)
    if bytes_per_sep < 1:
        raise ValueError("bytes_per_sep must be >= 1")

    # Perform the hex encoding
    data = self
    result_parts = []
    for i in range(0, len(data), bytes_per_sep):
        chunk = data[i:i+bytes_per_sep]
        if isinstance(sep, bytes):
            hex_chunk = bytes([c | 0x30 if (c >> 4) <= 9 else c << 1 + 87 for c in [chunk[j] >> 4] for j in range(len(chunk))]) + \
                        bytes([c | 0x30 if c <= 9 else c << 1 + 87 for c in [chunk[j] & 0xf] for j in range(len(chunk))])
            result_parts.append(hex_chunk)
        else:
            hex_str = ''.join('%02x' % b for b in chunk)
            result_parts.append(hex_str.encode('ascii'))
        if i + bytes_per_sep < len(data):
            if isinstance(sep, bytes):
                result_parts.append(sep)
            else:
                result_parts.append(sep.encode('ascii'))

    if isinstance(sep, bytes):
        return b''.join(result_parts).decode('ascii')
    else:
        return b''.join(result_parts).decode('ascii')


