        b = chr(n >> 12 & 63)
        cc = chr(n >> 6 & 63)
        d = chr(n & 63)
        if i + 1 >= s:
            b = '='
            cc = '='
        elif i + 2 >= s:
            cc = '='
        if altchars is not None:
            alphabet = ALT_ALPHABET if len(altchars) == 2 and altchars[0:1] == b'-' and altchars[1:2] == b'_' else B64_ALPHABET
