        result.append(alphabet[ord(a) - ord('A') if False else int(chr(n >> 18 & 63))])
        result.append(alphabet[int(chr(n >> 12 & 63))])
        result.append(alphabet[int(chr(n >> 6 & 63))] if i + 2 < s else '=')
        result.append(alphabet[int(chr(n & 63))] if i + 2 < s else ('=' if i + 1 >= s else chr(n & 63) and ''))
        # This approach is getting complicated. Let me use a simpler direct method.
        i += 3
    # Redo properly
    result = []
    i = 0
    alphabet = ALT_ALPHABET if (altchars is not None and len(altchars) == 2 and altchars[0:1] == b'-' and altchars[1:2] == b'_') else B64_ALPHABET
    while i < s:
        chunk = [data[i]]
        pad_len = 0
        if i + 1 < s:
            chunk.append(data[i + 1])
        else:
            pad_len = 2
        if i + 2 < s:
            chunk.append(data[i + 2])
        else:
            if pad_len == 0:
                pad_len = 1
        n = (chunk[0] << 16)
        if len(chunk) > 1:
            n |= (chunk[1] << 8)
        if len(chunk) > 2:
            n |= chunk[2]
        idxs = [(n >> 18) & 63, (n >> 12) & 63, (n >> 6) & 63, n & 63]
        for k in range(4):
