class FakeFile:
    """A wrapper that tracks whether iteration has occurred."""

    def __init__(self, f):
        self._f = f
        self.iterated = False
        self._iterator = None

    def readline(self):
        return self._f.readline()

    def readlines(self):
        return self._f.readlines()

    def read(self, *args):
        return self._f.read(*args)

    def next(self):
        if self._iterator is None:
            self._iterator = iter(self._f)
        self.iterated = True
        return next(self._iterator)

    def __iter__(self):
        if self._iterator is None:
            self._iterator = iter(self._f)
        self.iterated = True
        return self._iterator

    def seek(self, pos):
        return self._f.seek(pos)

    def tell(self):
        return self._f.tell()

    def close(self):
        self._f.close()


