class SimFile:
    def __init__(self, data):
        self.data = data
        self.pos = 0
        self.iterated = False
        self.closed = False

    def tell(self):
        # CPython behavior: if stream has been iterated and not seeked since, raise OSError
        # Actually, CPython raises OSError when you call tell() after iteration via __next__
        # unless you've called seek() afterwards.
        if self.iterated and hasattr(self, '_need_seek') and self._need_seek:
            raise OSError(36, "tell(): current position unknown")
        return self.pos

    def readline(self):
        idx = self.data.find('\n', self.pos)
        if idx == -1:
            result = self.data[self.pos:]
            self.pos = len(self.data)
        else:
            result = self.data[self.pos:idx+1]
            self.pos = idx + 1
        return result

    def readlines(self):
        lines = []
        while True:
            line = self.readline()
            if not line:
                break
            lines.append(line)
        return lines

    def read(self, size=None):
        if size is None:
            result = self.data[self.pos:]
            self.pos = len(self.data)
        else:
            result = self.data[self.pos:self.pos+size]
            self.pos += size
        return result

    def __iter__(self):
        return self

    def __next__(self):
        self.iterated = True
        self._need_seek = True
        # Read a line
        line = self.readline()
        if not line:
            self._need_seek = False
            raise StopIteration
        return line

    def seek(self, pos, whence=0):
        if whence == 0:
            self.pos = pos
        elif whence == 1:
            self.pos += pos
        elif whence == 2:
            self.pos = len(self.data) + pos
        self._need_seek = False


