class _CsvReader:
    def __init__(self, f):
        self._buf = ''
        self._pos = 0
        self._eof = False
        self.f = f

    def __iter__(self):
        return self

    def next(self):
        if self._eof and not self._buf.strip():
            raise StopIteration()
        line = None
        while True:
            if self._buf:
                idx = self._buf.find('\n')
                if idx != -1:
                    line = self._buf[:idx]
                    self._buf = self._buf[idx + 1:]
                    break
                # No newline in buffer; check eof
                if self._eof:
                    line = self._buf
                    self._buf = ''
                    break
            # Need more data
            ch = self.f.read(1)
            if not ch:
                if self._buf:
                    line = self._buf
                    self._buf = ''
                    break
                else:
                    self._eof = True
                    raise StopIteration()
            self._buf += ch
        # Parse CSV for a single row
        result = []
        field = ''
        in_quotes = False
        i = 0
        while i < len(line):
            c = line[i]
            if in_quotes:
                if c == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field += '"'
                        i += 1
                    else:
                        in_quotes = False
                else:
                    field += c
            else:
                if c == '"':
                    in_quotes = True
                elif c == ',':
                    result.append(field)
                    field = ''
                else:
                    field += c
            i += 1
        result.append(field)
        return result

    def close(self):
        pass


