import sys

def _u8(s):
    if hasattr(s, 'encode'):
        return s.encode('utf-8')
    return bytes(s)

def _repr_char(c):
    b = _u8(c)
    n = len(b)
    if c.isprintable():
        try:
            q = "'%s'" % c
            r = q
        except Exception:
            r = None
        if r is None or (r and ('"' in r)):
            pass
        if not r:
            r = "'%s'" % c
        return r
    else:
        if n == 1:
            code = b[0]
            if code < 128:
                name = ['null', 'soh', 'stx', 'etx', 'eot', 'enq', 'ack', 'bel', 'bs', 'tab', 'lf',
                         'vt', 'ff', 'cr', 'so', 'si', 'dle', 'dc1', 'dc2', 'dc3', 'dc4', 'nak',
                         'syn', 'etb', 'can', 'em', 'sub', 'esc', 'fs', 'gs', 'rs', 'us', 'sp']
                if code < len(name):
                    return '\\' + name[code]
                if code == 0x7f:
                    return '\\x7f'
                return "'%s'" % chr(code)
            return '\\x%02x' % code
        elif n == 2:
            return '\\u%04x' % ord(c)
        else:
            # surrogate pair representation for astral chars (won't happen here)
            hi = (ord(c) >> 10) + 0xd800
            lo = (ord(c) & 0x3ff) + 0xdc00
            return "\\U%08x" % ord(c)

