def urepr(c):
    if c == '':
        return "''"
    # Check if all characters are printable ASCII (or common safe ones)
    # For a single character:
    cp = ord(c)
    # If it's a regular printable char and not a quote, show as-is
    if cp >= 0x20 and cp <= 0x7e and c != '\'' and c != '"':
        return "'%s'" % c
    # Special escapes
    if cp == 0x09:
        return "'\\t'"
    if cp == 0x0a:
        return "'\\n'"
    if cp == 0x0d:
        return "'\\r'"
    # Otherwise use \uXXXX or \xXX format
    if cp < 0x100:
        return "'\\x%02x'" % cp
    else:
        return "'\\u%04x'" % cp

