def unicode_str(value, char_count):
    """Return the repr string for a given unicode value (0x20..0x10ffff)."""
    if 0x20 <= value <= 0x7e:
        # Printable ASCII; check backslash and double quote
        if value == ord('\\'):
            return "'\\\\'"
        if value == ord("'"):
            return '"' + chr(value) + '"'
        return "'" + chr(value) + "'"
    elif value == 9:
        return "'\\t'"
    elif value == 10:
        return "'\\n'"
    elif value == 13:
        return "'\\r'"
    else:
        hex_digits = '0123456789abcdef'
        s = 'U+'
        for i in range(char_count):
            d = (value >> (4*i)) & 0xf
            s += hex_digits[d]
        return "'\\u%s'" % s

