def _r(s):
    # mimic repr() of a string containing only ASCII (incl. control chars) or printable non-ASCII as-is
    out = []
    for ch in s:
        o = ord(ch)
        if ch == '\\':
            out.append('\\\\')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\t':
            out.append('\\t')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\x0b':
            out.append('\\x0b')
        elif ch == '\x0c':
            out.append('\\x0c')
        elif o < 32 or o > 126:
            out.append('\\x%02x' % o)
        else:
            out.append(ch)
    return "'" + ''.join(out) + "'"

