import os, sys

root = os.path.expanduser("~/.claude/projects")


def parse_json(s):
    s = s.strip()
    if not s:
        return None
    try:
        return _parse_value(s)[0]
    except Exception:
        return None


def _skip_ws(s, i):
    n = len(s)
    while i < n and s[i] in ' \t\r\n':
        i += 1
    return i


def _parse_value(s, i=0):
    i = _skip_ws(s, i)
    c = s[i]
    if c == '{':
        obj = {}
        i += 1
        i = _skip_ws(s, i)
        if s[i] == '}':
            return obj, i + 1
        while True:
            i = _skip_ws(s, i)
            k, i = _parse_string_raw(s, i)
            i = _skip_ws(s, i)
            if s[i] != ':':
                raise ValueError('expected :')
            v, i = _parse_value(s, i + 1)
            obj[k] = v
            i = _skip_ws(s, i)
            if s[i] == ',':
                i += 1
                continue
            elif s[i] == '}':
                return obj, i + 1
            else:
                raise ValueError('unexpected char after value: %r' % s[i])
    if c == '[':
        arr = []
        i += 1
        i = _skip_ws(s, i)
        if s[i] == ']':
            return arr, i + 1
        while True:
            v, i = _parse_value(s, i)
            arr.append(v)
            i = _skip_ws(s, i)
            if s[i] == ',':
                i += 1
                continue
            elif s[i] == ']':
                return arr, i + 1
            else:
                raise ValueError('unexpected char after array value: %r' % s[i])
    if c == '"':
        val, i = _parse_string_raw(s, i)
        return val, i
    if c == 't':
        if s.startswith('true', i):
            return True, i + 4
        raise ValueError('bad literal at %d' % i)
    if c == 'f':
        if s.startswith('false', i):
            return False, i + 5
        raise ValueError('bad literal at %d' % i)
    if c == 'n':
        if s.startswith('null', i):
            return None, i + 4
        raise ValueError('bad literal at %d' % i)
    # number
    j = i
    n = len(s)
    if j < n and s[j] in '+-':
        j += 1
    while j < n and (s[j].isdigit() or s[j] in '.eE+-'):
        j += 1
    if j == i:
        raise ValueError('cannot parse value at %d' % i)
    tok = s[i:j]
    try:
        if '.' in tok or 'e' in tok or 'E' in tok:
            return float(tok), j
        return int(tok), j
    except Exception:
        return tok, j


def _parse_string_raw(s, i):
    assert s[i] == '"'
    i += 1
    out = []
    n = len(s)
    while i < n:
        c = s[i]
        if c == '\\':
            i += 1
            e = s[i]
            if e == '"':
                out.append('"'); i += 1
            elif e == '\\':
                out.append('\\'); i += 1
            elif e == '/':
                out.append('/'); i += 1
            elif e == 'b':
                out.append('\b'); i += 1
            elif e == 'f':
                out.append('\f'); i += 1
            elif e == 'n':
                out.append('\n'); i += 1
            elif e == 'r':
                out.append('\r'); i += 1
            elif e == 't':
                out.append('\t'); i += 1
            elif e == 'u':
                code = s[i+1:i+5]
                codept = int(code, 16)
                out.append(chr(codept))
                i += 5
            else:
                out.append(e); i += 1
        elif c == '"':
            return ''.join(out), i + 1
        else:
            out.append(c); i += 1
    raise ValueError('unterminated string')


