            c3_val = c3
        else:
            raise binascii_Error('Invalid base64-encoded string: number of data characters (2) cannot be 1 more than a multiple of 4')

        i3_val = None
        if i < s_len:
            c4 = s[i]
            if c4 != '=' and c4 not in (10, 13, 9, 32):
