import binascii

def _a2b(s, strict=False):
    # Mirror binascii.a2b_base64 default: ignores characters outside the alphabet.
    alphabet = (b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
    out = bytearray()
    buf = 0
    bits = 0
    for c in s:
        if isinstance(c, int):
            ch = bytes((c,))
        else:
            ch = c
        if ch not in alphabet:
            continue
        idx = alphabet.index(ch)
        buf = (buf << 6) | idx
        bits += 6
        if bits >= 8:
            bits -= 8
            out.append((buf >> bits) & 0xFF)
    return bytes(out)

