import sys

def parse_json(s):
    i = 0
    n = len(s)
    def skip_ws():
        nonlocal i
        while i < n and s[i] in ' \t\n\r':
            i += 1
    def peek():
        if i >= n:
            return ''
        return s[i]
    def read_char():
        nonlocal i
        c = s[i]
        i += 1
        return c
    def parse_string():
        # assumes current char is "
        c = read_char()
        assert c == '"'
        result = []
        while True:
            c = read_char()
            if c == '"':
                break
            elif c == '\\':
                nc = read_char()
                if nc == 'n':
                    result.append('\n')
                elif nc == 't':
                    result.append('\t')
                elif nc == 'r':
                    result.append('\r')
                elif nc == '"':
                    result.append('"')
                elif nc == '\\':
                    result.append('\\')
                elif nc == '/':
                    result.append('/')
                elif nc == 'b':
                    result.append('\b')
                elif nc == 'f':
                    result.append('\f')
                elif nc == 'u':
                    hexcode = read_char() + read_char() + read_char() + read_char()
                    codepoint = int(hexcode, 16)
                    result.append(chr(codepoint))
            else:
                result.append(c)
        return ''.join(result)
    def parse_number():
        start = i
        if peek() == '-':
            i += 1
        while i < n and (s[i].isdigit() or s[i] == '.'):
            i += 1
        token = s[start:i]
        if '.' in token or 'e' in token or 'E' in token:
            return float(token)
        else:
            return int(token)
    def parse_value(hook_dict=None):
        skip_ws()
        c = peek()
        if c == '{':
            i += 1  # consume {
            skip_ws()
            items = []
            if peek() == '}':
                i += 1
                result = {}
                for k, v in items:
                    result[k] = v
                if hook_dict:
                    hook_dict(result)
                return result
            while True:
                key = parse_string()
                skip_ws()
                expect_colon = read_char()
                assert expect_colon == ':'
                value = parse_value()
                items.append((key, value))
                skip_ws()
                if peek() == ',':
                    i += 1
                    skip_ws()
                elif peek() == '}':
                    i += 1
                    break
            result = {}
            for k, v in items:
                result[k] = v
            if hook_dict:
                hook_dict(result)
            return result
        elif c == '[':
            i += 1  # consume [
            skip_ws()
            values = []
            if peek() == ']':
                i += 1
                return values
            while True:
                value = parse_value()
                values.append(value)
                skip_ws()
                if peek() == ',':
                    i += 1
                    skip_ws()
                elif peek() == ']':
                    i += 1
                    break
            return values
        elif c == '"':
            return parse_string()
        elif c == '-' or c.isdigit():
            return parse_number()
        elif s.startswith('true', i):
            i += 4
            return True
        elif s.startswith('false', i):
            i += 5
            return False
        elif s.startswith('null', i):
            i += 4
            return None
        else:
            raise ValueError("Unexpected character: " + c)
    return parse_value()

