def _json_parse_string(s, i):
    # s[i] must be '"'
    i += 1
    out = []
    n = len(s)
    while i < n:
        c = s[i]
        if c == '\\':
            i += 1
            e = s[i]
            if e == '"':
                out.append('"')
            elif e == '\\':
                out.append('\\')
            elif e == '/':
                out.append('/')
            elif e == 'b':
                out.append('\b')
            elif e == 'f':
                out.append('\f')
            elif e == 'n':
                out.append('\n')
            elif e == 'r':
                out.append('\r')
            elif e == 't':
                out.append('\t')
            elif e == 'u':
                hexs = s[i+1:i+5]
                cp = int(hexs, 16)
                out.append(chr(cp))
                i += 4
            i += 1
        elif c == '"':
            i += 1
            break
        else:
            out.append(c)
            i += 1
    return ''.join(out), i

def _skip_ws(s, i):
    n = len(s)
    while i < n and s[i] in ' \t\n\r':
        i += 1
    return i

def _parse_json(s, i):
    """Parse JSON value at position i. Returns (value, new_i)."""
    i = _skip_ws(s, i)
    c = s[i]
    if c == '{':
        i += 1
        items = []
        i = _skip_ws(s, i)
        if s[i] == '}':
            return {}, i + 1
        while True:
            k, i = _json_parse_string(s, i)
            i = _skip_ws(s, i)
            assert s[i] == ':'
            i += 1
            v, i = _parse_json(s, i)
            items.append((k, v))
            i = _skip_ws(s, i)
            if s[i] == ',':
                i += 1
                i = _skip_ws(s, i)
                continue
            elif s[i] == '}':
                i += 1
                break
            else:
                raise ValueError("unexpected")
        return items, i  # list of pairs
    elif c == '[':
        i += 1
        arr = []
        i = _skip_ws(s, i)
        if s[i] == ']':
            return [], i + 1
        while True:
            v, i = _parse_json(s, i)
            arr.append(v)
            i = _skip_ws(s, i)
            if s[i] == ',':
                i += 1
                i = _skip_ws(s, i)
                continue
            elif s[i] == ']':
                i += 1
                break
            else:
                raise ValueError("unexpected")
        return arr, i
    elif c == '"':
        val, i = _json_parse_string(s, i)
        return val, i
    elif c == 't':
        # true
        assert s[i:i+4] == 'true'
        return True, i + 4
    elif c == 'f':
        assert s[i:i+5] == 'false'
        return False, i + 5
    elif c == 'n':
