                    args = []
                    a = f.args
                    # posonlyargs
                    for i, arg in enumerate(a.posonlyargs):
                        s = arg.arg
                        if arg.annotation is not None:
                            ann = ast.unparse(arg.annotation)
                            s += ": " + ann
                        if i < len(a.defaults):
                            d = a.defaults[i - len(a.posonlyargs)] if i >= len(a.posonlyargs) else None
                            pass
                        args.append(s)

                    # Handle defaults for positional args (excluding posonlyargs)
                    posonly_count = len(a.posonlyargs)
                    posargs = a.args
                    total_pos = posonly_count + len(posargs)
                    default_count = len(a.defaults)
                    non_default_count = total_pos - default_count

                    # posonlyargs defaults come first in a.defaults
                    for i, arg in enumerate(a.posonlyargs):
                        s = arg.arg
                        if arg.annotation is not None:
                            ann = ast.unparse(arg.annotation)
                            s += ": " + ann
                        # posonlyargs use defaults starting from index 0
                        if i >= non_default_count - posonly_count:
                            idx = i - (non_default_count - posonly_count)
                            if idx < default_count:
                                d_str = ast.unparse(a.defaults[idx])
                                s += " = " + d_str
                        args.append(s)

                    # regular args
                    for i, arg in enumerate(a.args):
                        s = arg.arg
                        if arg.annotation is not None:
                            ann = ast.unparse(arg.annotation)
                            s += ": " + ann
                        # Determine if this arg has a default
                        # args start at posonly_count
                        global_idx = posonly_count + i
                        if global_idx >= non_default_count:
                            default_idx = global_idx - non_default_count
                            if default_idx < default_count:
                                d_str = ast.unparse(a.defaults[default_idx])
                                s += " = " + d_str
                        args.append(s)

                    # vararg
                    if a.vararg is not None:
                        s = "*" + a.vararg.arg
                        if a.vararg.annotation is not None:
                            ann = ast.unparse(a.vararg.annotation)
                            s += ": " + ann
                        args.append(s)

                    # kwonlyargs
                    for i, arg in enumerate(a.kwonlyargs):
                        s = arg.arg
                        if arg.annotation is not None:
                            ann = ast.unparse(arg.annotation)
                            s += ": " + ann
                        if a.kw_defaults[i] is not None:
                            d_str = ast.unparse(a.kw_defaults[i])
                            s += " = " + d_str
                        args.append(s)

                    # kwarg
                    if a.kwarg is not None:
                        s = "**" + a.kwarg.arg
                        if a.kwarg.annotation is not None:
                            ann = ast.unparse(a.kwarg.annotation)
                            s += ": " + ann
                        args.append(s)

                    result = ", ".join(args)
