import csv

# We need to replicate io.StringIO behavior for the given use cases.
# The key insight: csv.writer writes strings, and we need to capture them.
# Let's use a simple list-based buffer approach.

class _Buf:
    def __init__(self):
        self._chunks = []
    def write(self, s):
        if s:
            self._chunks.append(s)
        return len(s) if isinstance(s, str) else 0
    def getvalue(self):
        return ''.join(self._chunks)
    def read(self, n=-1):
        v = self.getvalue()
        if n == -1 or n >= len(v):
            return v
        return v[:n]
    # DictReader needs a file-like object that can be iterated and has readline/next
    def __iter__(self):
        return self
    def __next__(self):
        # For iteration used by csv.DictReader / csv.reader
        if not hasattr(self, '_iter_state'):
            self._iter_state = iter(self._data.splitlines(keepends=True)) if hasattr(self,'_data') else None
        raise StopIteration

class _StrFile:
    """Mimics io.StringIO for reading purposes (used by csv readers)."""
    def __init__(self, data, newline=None):
        self._data = data
        self._pos = 0
        self._newline = newline  # keep for compatibility
    def read(self, n=-1):
        if n == -1:
            result = self._data[self._pos:]
            self._pos = len(self._data)
        else:
            result = self._data[self._pos:self._pos+n]
            self._pos += len(result)
        return result
    def readline(self, limit=-1):
        # Find next newline in remaining data
        rest = self._data[self._pos:]
        idx = rest.find('\n')
        if idx == -1:
            line = rest
            self._pos = len(self._data)
        else:
            line = rest[:idx+1]
            self._pos += idx + 1
        if limit != -1 and len(line) > limit:
            line = line[:limit]
        return line
    def __iter__(self):
        return self
    def __next__(self):
        if self._pos >= len(self._data):
            raise StopIteration
        line = self.readline()
        if line == '':
            raise StopIteration
        return line


