import sys

class _StringIO:
    def __init__(self, value=""):
        self._buf = [value] if isinstance(value, str) else []
        self._pos = 0
    def write(self, s):
        # append to the last chunk and track length
        n = len(s)
        if not self._buf:
            self._buf.append("")
        self._buf[-1] += s
        return n
    def getvalue(self):
        return "".join(self._buf)
    def seekable(self):
        return True
    def tell(self):
        return self._pos
    def seek(self, offset, whence=0):
        total = sum(len(b) for b in self._buf)
        if whence == 0:
            pos = offset
        elif whence == 1:
            pos = self._pos + offset
        else:
            pos = total + offset
        if pos < 0: pos = 0
        self._pos = pos
        return self._pos
    def read(self, size=-1):
        full = "".join(self._buf)
        if size is None or size < 0:
            r = full[self._pos:]
            self._pos = len(full)
            return r
        r = full[self._pos:self._pos+size]
        self._pos += len(r)
        return r
    def readline(self, limit=None):
        full = "".join(self._buf)
        nl = full.find("\n", self._pos)
        if nl == -1:
            r = full[self._pos:]
            self._pos = len(full)
            return r
        else:
            end = nl + 1
            if limit is not None and (end - self._pos) > limit:
                end = self._pos + limit
            r = full[self._pos:end]
            self._pos = end
            return r
    def __iter__(self):
        lines = "".join(self._buf).splitlines(True)
        i = 0
        while i < len(lines):
            yield lines[i]
            i += 1
    def close(self):
        pass
    def closed(self):
        return False
    @property
    def encoding(self):
        return "utf-8"


def _csv_parse_line(line, delimiter=","):
    # Parse a single logical line of CSV into fields.
    # This handles quoting as per Python's csv module default dialect.
    result = []
    field = ""
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if in_quotes:
            if c == '"':
                if i + 1 < n and line[i+1] == '"':
                    field += '"'
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                field += c
                i += 1
        else:
            if c == '"':
                in_quotes = True
                i += 1
            elif c == delimiter:
                result.append(field)
                field = ""
                i += 1
            else:
                field += c
                i += 1
    result.append(field)
    return result


def W(row, **kw):
    lineterminator = kw.get("lineterminator", "\r\n")
    delimiter = kw.get("delimiter", ",")
    quotechar = kw.get("quotechar", '"')
    quoting = kw.get("quoting", 0)  # QUOTE_MINIMAL

    parts = []
    for field in row:
        fs = str(field)
        if quoting != 0 and all(c not in fs for c in [delimiter, quotechar, "\r", "\n"]):
            parts.append(fs)
        else:
            escaped = fs.replace(quotechar, quotechar*2)
            parts.append(quotechar + escaped + quotechar)
    return (delimiter.join(parts) + lineterminator, None)


