import csv

class FakeStringIO:
    def __init__(self, data=None):
        if data is None:
            self._buf = ''
        else:
            self._buf = data

    def write(self, s):
        self._buf += s
        return len(s)

    def getvalue(self):
        return self._buf

    def read(self, size=-1):
        if size == -1 or size >= len(self._buf):
            result = self._buf
            self._buf = ''
            return result
        else:
            result = self._buf[:size]
            self._buf = self._buf[size:]
            return result

    def readline(self, size=-1):
        idx = self._buf.find('\n')
        if idx == -1:
            result = self._buf
            self._buf = ''
            return result
        else:
            end = idx + 1
            if size != -1 and end > size:
                end = size
            result = self._buf[:end]
            self._buf = self._buf[end:]
            return result

    def close(self):
        pass

    def seek(self, pos, whence=0):
        if whence == 0:
            self._pos = pos
        elif whence == 1:
            self._pos = getattr(self, '_pos', 0) + pos
        elif whence == 2:
            self._pos = len(self._buf) + pos
        return self._pos

    def tell(self):
        return getattr(self, '_pos', 0)


