import sys, csv

class BS(object):
    __slots__=('b',)
    def __init__(self,s=''):
        if isinstance(s,str): self.b=bytes(s,'utf-8')
        else: self.b=s
    def write(self,s):
        b = s.encode('utf-8') if isinstance(s,str) else bytes(s)
        self.b=self.b+b
    def tell(self): return len(self.b)
    def truncate(self,n=None):
        if n is None: n=len(self.b)
        self.b=self.b[:n]
    def seek(self,off,whence=0):
        if whence==0: p=off
        elif whence==1: p=len(self.b)+off
        else: p=-len(self.b)+off
        if 0<=p<=len(self.b): self._p=p; return p
    def readline(self,length=-1):
        i=self.b.find(b'\n',self._p)
        end = i+1 if i>=0 else len(self.b)
        if length>=0: end=min(end,self._p+length)
        c=self.b[self._p:end]; self._p=end; return c
    def read(self,n=-1):
        c=self.b[self._p:self._p+n if n>=0 else len(self.b)]
        self._p+=len(c); return c
    def peek(self): return self.b[self._p:]
    def iter(self): return self
    def __iter__(self):
        while True:
            l=self.readline()
            if not l: break
            yield l

