def DR(data, **kw):
    if not data or '\n' not in data and ',' not in data:
        return []
    lines = [l for l in data.split('\n') if l != '']
    if not lines:
        return []
    header = lines[0]
    # Parse header - handle quoted fields with commas
    def parse_line(s):
        fields = []
        i = 0
        while i < len(s):
            if s[i] == '"':
                i += 1
                val = ''
                while i < len(s):
                    if s[i] == '"':
                        if i+1 < len(s) and s[i+1] == '"':
                            val += '"'
                            i += 2
                        else:
                            i += 1
                            break
                    else:
                        val += s[i]
                        i += 1
                # skip to comma or end
                while i < len(s) and s[i] != ',':
                    i += 1
                fields.append(val)
                if i < len(s) and s[i] == ',':
                    i += 1
            else:
                j = i
                while j < len(s) and s[j] != ',':
                    j += 1
                fields.append(s[i:j])
                if j < len(s):
                    j += 1
                i = j
        return fields

    hfields = parse_line(header)

    if len(lines) < 2:
        return []

    rows = []
    for line in lines[1:]:
        fvals = parse_line(line)
        d = {}
        for i, h in enumerate(hfields):
            if i < len(fvals):
                d[h] = fvals[i]
            else:
                d[h] = ''
        # Handle duplicates
        for i, h in enumerate(hfields):
            if h in d:
                pass  # last wins, already handled above since we overwrite
            else:
                if i < len(fvals):
                    d[h] = fvals[i]
        rows.append(d)
    return rows

