import sys

def b64decode(s):
    """Replicate base64.b64decode default (validate=True, discard=False) exactly.

    - reject non-alphabet chars outside trailing padding
    - if an interior quad is padded with 1 or more '=' but followed by further
      characters, raise "Invalid base64-encoded string: number of data characters (n) cannot be 1 more than a multiple of 4"
    - otherwise decode and validate the resulting length
    """
    ALPHA = set(
        b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/='
    )
    VAL = {}
    i = 0
    for ch in b'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
        VAL[chr(ch)] = i; i += 1
    for ch in b'abcdefghijklmnopqrstuvwxyz':
        VAL[chr(ch)] = i; i += 1
    for ch in b'0123456789':
        VAL[chr(ch)] = i; i += 1
    VAL['+'] = 62
    VAL['/'] = 63

    data_chars = 0   # actual data (non-'=') chars
    pad_count = 0
    first_pad_index = None

    n = len(s)
    out = bytearray()

    # find position where first pad appears (if any)
    for j, c in enumerate(s):
        if c == ord('='):
            first_pad_index = j
            break

    if first_pad_index is not None:
        # count remaining after that index — they must all be '='? No, in base64 standard only trailing.
        # We treat s[first_pad_index:] — verify no alphabet after it.
        tail = s[first_pad_index:]
        for k, c in enumerate(tail):
            if c != ord('='):
                raise ValueError("Invalid base64-encoded string: bad base64-encoding character at position %d: %r" % (first_pad_index + k, bytes([c])))
        pad_count = len(tail)
    else:
        pad_count = 0

    # Now scan to validate every char is valid alphabet OR '=', and count data chars
    vals = []
    for idx, c in enumerate(s):
        if c == ord('='):
            continue
        # check membership in ALPHA via direct byte compare against our table
        b = chr(c)
        if b not in VAL:
            raise ValueError("Invalid base64-encoded string: bad base64-encoding character at position %d: %r" % (idx, bytes([c])))
        vals.append((idx, VAL[b]))
    data_chars = len(vals)

    # If there is any interior data after first pad => error per rule
    if first_pad_index is not None:
        # any value whose position >= first_pad_index would already have been caught above (since we skipped '='); if any exists it means alphabet after padding
        for pos, v in vals:
            if pos >= first_pad_index:
                # mimic CPython's generic message used for this class of case
                if data_chars % 4 == 1:
                    raise ValueError("Invalid base64-encoded string: number of data characters (%d) cannot be 1 more than a multiple of 4" % data_chars)
                else:
                    raise ValueError("Invalid base64-encoded string: number of data characters (%d) cannot be 1 more than a multiple of 4" % data_chars)
        # also enforce total-length validity:
        if data_chars % 4 == 1:
            raise ValueError("Invalid base64-encoded string: number of data characters (%d) cannot be 1 more than a multiple of 4" % data_chars)

    # Final length check
    if data_chars % 4 == 1:
        raise ValueError("Invalid base64-encoded string: number of data characters (%d) cannot be 1 more than a multiple of 4" % data_chars)

    # Decode quads
    vlist = [v for _, v in vals]
    L = len(vlist)
    for q in range(L // 4):
        w = q * 4
        a = vlist[w]; b = vlist[w+1]; c = vlist[w+2]; d = vlist[w+3]
        buf = (a << 18) | (b << 12) | (c << 6) | d
        out.append((buf >> 16) & 0xff)
        out.append((buf >> 8) & 0xff)
        out.append(buf & 0xff)
    rem = L % 4
    if rem == 2:
        a = vlist[-2]; b = vlist[-1]
        buf = (a << 18) | (b << 12)
        out.append((buf >> 16) & 0xff)
    elif rem == 3:
        a = vlist[-3]; b = vlist[-2]; c = vlist[-1]
        buf = (a << 18) | (b << 12) | (c << 6)
        out.append((buf >> 16) & 0xff)
        out.append((buf >> 8) & 0xff)

    return bytes(out)


def py_b64decode_default(s):
    return b64decode(s)


