_B = {c: i for i, c in enumerate(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')}
_TRANS = bytes.maketrans(bytes(range(128)), None)


def _translate(buf):
    # equivalent to buf.translate(bytes.maketrans(...)) for ASCII-safe buffers
    out = bytearray()
    for ch in buf:
        v = _TRANS[ch]
        if v != 255:
            out.append(v)
    return bytes(out)


def _decode(clean):
    n = len(clean)
    rem = n % 4
    if rem == 1:
        raise ValueError('Invalid base64-encoded string: number of data characters (%d) cannot be 1 more than a multiple of 4' % n)
    out = bytearray()
    for i in range(0, n - (n % 4), 4):
        quad = clean[i:i + 4]
        bits = 0
        for ch in quad:
            if ch not in _B:
                raise ValueError('Non-base64 digit found')
            bits = (bits << 6) | _B[ch]
        out.append((bits >> 16) & 0xFF)
        if n - i > 2:
            out.append((bits >> 8) & 0xFF)
        if n - i > 3:
            out.append(bits & 0xFF)
    return bytes(out)


def _b64decode(buf):
    try:
        return _decode(_translate(buf))
    except Exception as e:
        raise type(e)(str(e))


