        n += 1
        if n == 4:
            out.append((acc >> 16) & 0xFF)
            out.append((acc >> 8) & 0xFF)
            out.append(acc & 0xFF)
            acc = 0
            n = 0
    pad_after = total_pad
    rem = len(c) - (len(c) - total_pad)  # chars seen in quad loop are before first '='
    quads = rem // 4
    left = rem % 4
    # leftover bits when not a multiple of 4
    if left:
        acc = 0
        n = 0
        for i in range(left):
            ch = c.decode('ascii')[i]
            v = m[ch]
