def custom_repr(s):
    """Replicate CPython's str.__repr__ behavior for printable ascii and common escapes."""
    if s == '':
        return "''"

    # Determine which quote to use
    has_single = "'" in s
    has_double = '"' in s

    result = []
    for c in s:
        cp = ord(c)
        if c == "'":
            result.append("'")
        elif c == '"':
            result.append('"')
        elif c == '\\':
            result.append('\\\\')
        elif cp < 32 or (cp >= 127 and cp <= 159):
            # Control characters and some del
            if c == '\0':
                result.append('\\0')
            elif c == '\a':
                result.append('\\a')
            elif c == '\b':
                result.append('\\b')
            elif c == '\t':
                result.append('\\t')
            elif c == '\n':
                result.append('\\n')
            elif c == '\v':
                result.append('\\v')
            elif c == '\f':
                result.append('\\f')
            elif c == '\r':
                result.append('\\r')
            else:
                result.append('\\x%02x' % cp)
        elif cp == 0x7f:
            result.append('\\x7f')
        else:
            result.append(c)

    body = ''.join(result)

    if has_single and not has_double:
        return '"' + body.replace('"', '\\"') + '"'
    else:
        return "'" + body.replace("'", "\\'") + "'"

