def my_repr(s):
    # Handle single-character special case like CPython does
    if len(s) == 1:
        c = s
        if c == "'":
            return '"' + c + '"'
        elif c == '"':
            return "'" + c + "'"
        elif c == "\\":
            return "'\\\\'"
        else:
            ch = ord(c)
            if ch < 32 or ch == 127:
                return "'" + _escape_char(c) + "'"
            else:
                return "'" + c + "'"
    # Multi-char string
    if "'" not in s and "\\" not in s:
        # Check if we can use single quotes
        has_non_printable = False
        for c in s:
            ch = ord(c)
            if ch < 32 or ch == 127 or ch == 0xa0:
                has_non_printable = True
                break
        if not has_non_printable:
            return "'" + s + "'"
    # Need escaping; prefer double quotes if no double quote inside
    if '"' not in s:
        result = '"'
        for c in s:
            ch = ord(c)
            if ch < 32 or ch == 127 or ch == 0xa0:
                result += _escape_char(c)
            else:
                result += c
        result += '"'
        return result
    else:
        result = "'"
        for c in s:
            ch = ord(c)
            if ch == "'":
                result += "\\'"
            elif ch == "\\":
                result += "\\\\"
            elif ch < 32 or ch == 127 or ch == 0xa0:
                result += _escape_char(c)
            else:
                result += c
        result += "'"
        return result

def _escape_char(c):
    ch = ord(c)
    if ch == 10:
        return "\\n"
    elif ch == 9:
        return "\\t"
    elif ch == 13:
        return "\\r"
    elif ch == 11:
        return "\\x0b"
    elif ch == 12:
        return "\\x0c"
    elif ch == 0xa0:
        return "\\xa0"
    else:
        return "\\x%02x" % ch

