def py_repr(s):
    # Build Python's repr for a str
    if not s:
        return "''"
    b = []
    need_quote = False
    use_double = False
    for c in s:
        o = ord(c)
        if c == "'":
            pass
        elif o < 32 or (o > 126 and o < 0x80):
            need_quote = True
        if c == "\n":
            b.append('\\n')
        elif c == "\r":
            b.append('\\r')
        elif c == "\t":
            b.append('\\t')
        elif c == "\x0b":
            b.append('\\x0b')
        elif c == "\x0c":
            b.append('\\x0c')
        else:
            o = ord(c)
            if o < 32:
                b.append('\\x%02x' % o)
            elif o == 92:
                b.append('\\\\')
            elif o == 34:
                b.append('\\"')
            elif o == 39:
                b.append("\\'")
            elif o == 10:
                b.append('\\n')
            elif o == 13:
                b.append('\\r')
            elif o == 9:
                b.append('\\t')
            elif o == 0xb:
                b.append('\\x0b')
            elif o == 0xc:
                b.append('\\x0c')
            elif o >= 127 and o < 256:
                b.append('\\x%02x' % o)
            elif o >= 0x80:
                b.append('\\u%04x' % o)
            else:
                b.append(c)
    out = ''.join(b)
    if "'" not in out and '"' in out:
        return '"' + out + '"'
    else:
        return "'" + out + "'"

