def ascii_repr(s):
    if not isinstance(s, str):
        return 'None'
    out = []
    has_nbsp = False
    out.append('"')
    for ch in s:
        cp = ord(ch)
        if cp == 10:
            out.append('\\n')
        elif cp == 9:
            out.append('\\t')
        elif cp == 13:
            out.append('\\r')
        elif cp == 34:
            out.append('\\"')
        elif cp == 92:
            out.append('\\\\')
        elif cp == 11:
            out.append('\\x0b')
        elif cp == 12:
            out.append('\\x0c')
        elif cp >= 32 and cp < 127:
            out.append(ch)
        else:
            # fallback: use \u format
            has_nbsp = True
            out.append('\\u%04x' % cp)
    out.append('"')
    return ''.join(out)

