def _repr_plain(s):
    out = []
    if s == '':
        return "''"
    has_quote = "'" in s
    has_dquote = '"' in s
    use_double = has_quote and not has_dquote
    q = '"' if use_double else "'"
    for ch in s:
        c = ord(ch)
        if ch == '\\':
            out.append('\\\\')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\t':
            out.append('\\t')
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\x0b':
            out.append('\\v')
        elif ch == '\x0c':
            out.append('\\f')
        elif ch == q:
            out.append(q)
        elif c < 0x20 or c == 0x7f:
            out.append('\\x%02x' % c)
        elif c >= 0x80:
            out.append('\\u%04x' % c)
        else:
            out.append(ch)
    return q + ''.join(out) + q

