# Map of special non-ASCII / control characters to their repr-style escape.
def _escape(ch):
    o = ord(ch)
    if ch == '\n':
        return "\\n"
    if ch == '\t':
        return "\\t"
    if ch == '\r':
        return "\\r"
    if ch == '\x0b':
        return "\\x0b"
    if ch == '\x0c':
        return "\\x0c"
    if ch == '\u00a0':
        return "\\xa0"
    # For any other character we can use \\xNN or \\uNNNN safely
    if o < 256:
        return "\\x%02x" % o
    else:
        return "\\u%04x" % o


# Compute the repr-like string for each input, without using built-in repr().
# We follow Python's rule for str literals in source: prefer single quotes;
# only escape backslashes and single quotes always; escape everything that is
# not printable ASCII (ord 32..126).
def manual_repr_str(s):
    out = ['\'']
    prev_was_quote = False
    for ch in s:
        if ch == '\\':
            out.append('\\\\')
        elif ch == "'":
            if prev_was_quote:
                # previous char was already a single quote; use double-quote
                # style? Actually simpler: keep single quotes, escape as \'
                out.append("\\'")
            else:
                out.append("\\'")
        else:
            o = ord(ch)
            if o >= 32 and o <= 126:
                out.append(ch)
            else:
                out.append(_escape(ch))
        prev_was_quote = (ch == "'")
    out.append('\'')
    return ''.join(out)


