        elif c < 32 or (c >= 127 and c <= 255):
            # For control chars (<32) we need escape sequences;
            # Actually the original print(repr(int(%r))) -- int() only accepts
            # ASCII digits and whitespace. The non-ASCII char is U+00A0 which
            # is NOT a valid input to int(), so it will raise ValueError.
            # But wait -- we need to produce byte-identical output.
            # Let me reconsider what the original program actually does.
