                h1 = hexdigits[(c >> 4) & 0xF]
                h2 = hexdigits[c & 0xF]
                out.append('\\x' + h1 + h2)
            else:
                out.append('\\u%04x' % c)
        elif c == 0x0B:
            out.append('\\v')
        elif c == 0x0C:
            out.append('\\f')
        else:
            out.append(ch)
    out.append('"')
    return ''.join(out)


