def repr_str(s):
    out = []
    if all(32 <= ord(c) <= 126 for c in s):
        escaped = ""
        for c in s:
            o = ord(c)
            if o == 39 or (o >= 34 and o <= 35):
                escaped += "\\" + c
            else:
                escaped += c
        out.append("'" + escaped + "'")
    else:
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            o = ord(c)
            if 32 <= o <= 126:
                if o == 39:
                    out.append("\\'")
                    i += 1
                elif o == 92:
                    out.append("\\\\")
                    i += 1
                else:
                    j = i
                    while j < n and 32 <= ord(s[j]) <= 126:
                        if ord(s[j]) == 39 or ord(s[j]) == 92:
                            break
                        j += 1
                    chunk = s[i:j]
                    out.append(chunk)
                    i = j
            else:
                if o <= 0xff:
                    out.append("\\x%02x" % o)
                else:
                    out.append("\\u%04x" % o)
                i += 1
        out.append("'")
        # prepend opening quote
        return "'" + "".join(out[0:len(out)-1]) + out[-1]
    return "".join(out)

