def safe_eval(expr):
    parts = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch in "'\"":
            quote = ch
            i += 1
            buf = []
            while i < n and expr[i] != quote:
                if expr[i] == '\\' and i + 1 < n:
                    nxt = expr[i+1]
                    esc_map = {'n': '\n', 't': '\t', '\\': '\\', "'": "'", '"': '"'}
                    buf.append(esc_map.get(nxt, '\\' + nxt))
                    i += 2
                else:
                    buf.append(expr[i])
                    i += 1
            i += 1  # skip closing quote
            parts.append(('LIT', ''.join(buf)))
        elif ch.isdigit() or (ch == '-' and i + 1 < n and expr[i+1].isdigit()):
            j = i
            if ch == '-':
                j += 1
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            tok = expr[i:j]
            if '.' in tok:
                parts.append(('LIT', float(tok)))
            else:
                parts.append(('LIT', int(tok)))
            i = j
        elif ch.isalpha() or ch == '_':
            j = i
            while j < n and (expr[j].isalnum() or expr[j] == '_'):
                j += 1
            name = expr[i:j]
            if name == 'float':
                k = j
                while k < n and expr[k] == ' ':
                    k += 1
                if k < n and expr[k] == '(':
                    l = k + 1
                    depth = 1
                    m = l
                    while m < n and depth > 0:
                        if expr[m] == '(':
                            depth += 1
                        elif expr[m] == ')':
                            depth -= 1
                        m += 1
                    inner = expr[l:m-1]
                    arg = safe_eval(inner.strip())
                    parts.append(('LIT', arg))
                    i = m
                else:
                    parts.append(('NAME', name))
                    i = j
            else:
                parts.append(('NAME', name))
                i = j
        elif ch in '<>!=':
            j = i
            while j < n and expr[j] in '<>=':
                j += 1
            op = expr[i:j]
            parts.append(('OP', op))
            i = j
        elif ch in '+-*/%^&|~':
            parts.append(('OP', ch))
            i += 1
        elif ch == '(':
            parts.append(('PUNCT', '('))
            i += 1
        elif ch == ')':
            parts.append(('PUNCT', ')'))
            i += 1
        elif ch == '[':
            parts.append(('PUNCT', '['))
            i += 1
        elif ch == ']':
            parts.append(('PUNCT', ']'))
            i += 1
        elif ch == '{':
            parts.append(('PUNCT', '{'))
            i += 1
        elif ch == '}':
            parts.append(('PUNCT', '}'))
            i += 1
        elif ch == ',':
            parts.append(('PUNCT', ','))
            i += 1
        elif ch == '.':
            parts.append(('PUNCT', '.'))
            i += 1
        elif ch == ':':
            parts.append(('PUNCT', ':'))
            i += 1
        elif ch == ';':
            parts.append(('PUNCT', ';'))
            i += 1
        else:
            i += 1
    return parts

def build_ast(tokens):
    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return None

    def advance():
        t = peek()
        pos[0] += 1
        return t

    def parse_primary():
        t = advance()
        kind, val = t
        if kind == 'LIT':
            return ('lit', val)
        elif kind == 'NAME':
            if val == 'True':
                return ('lit', True)
            elif val == 'False':
                return ('lit', False)
            elif val == 'None':
                return ('lit', None)
            elif val == 'sorted':
                advance()  # consume '('
                args = []
                if peek() is not None and peek() != ('PUNCT', ')'):
                    args.append(parse_expr())
                    while peek() is not None and peek() == ('PUNCT', ','):
                        advance()
                        args.append(parse_expr())
                advance()  # consume ')'
                return ('call_sorted', args)
            else:
                raise Exception("unknown name")
        elif kind == 'PUNCT' and val == '(':
            e = parse_expr()
            advance()  # consume ')'
            return e
        elif kind == 'PUNCT' and val == '[':
            elems = []
            if peek() is not None and peek() != ('PUNCT', ']'):
                elems.append(parse_expr())
                while peek() is not None and peek() == ('PUNCT', ','):
                    advance()
                    if peek() is not None and peek() != ('PUNCT', ']'):
                        elems.append(parse_expr())
            advance()  # consume ']'
            return ('list', elems)
        elif kind == 'PUNCT' and val == '{':
            elems = []
            if peek() is not None and peek() != ('PUNCT', '}'):
                elems.append(parse_expr())
                while peek() is not None and peek() == ('PUNCT', ','):
                    advance()
                    if peek() is not None and peek() != ('PUNCT', '}'):
                        elems.append(parse_expr())
            advance()  # consume '}'
            return ('set', elems)
        else:
            raise Exception("unexpected token")

    def parse_cmp():
        left = parse_primary()
        while True:
            if peek() is not None and peek()[0] == 'OP' and peek()[1] in ('<', '>', '<=', '>=', '==', '!='):
                op_tok = advance()
                right = parse_primary()
                left = ('cmp', op_tok[1], left, right)
            else:
                break
        return left

    def parse_expr():
        return parse_cmp()

    result = parse_expr()
    return result

