ALLOWED_NAMES = {"float", "abs", "len", "min", "max", "sum", "int", "str", "list", "tuple", "set", "dict", "bool", "bytes", "bytearray", "frozenset", "complex", "type", "repr", "format", "chr", "ord", "round", "range", "any", "all", "zip", "enumerate"}

class _EvalError(Exception):
    pass

def _exec_node(node, local_vars):
    if isinstance(node, ast.Expression):
        return _eval(node.body, local_vars)
    elif isinstance(node, ast.Name):
        name = node.id
        if name in local_vars:
            return local_vars[name]
        if name == "True":
            return True
        if name == "False":
            return False
        if name == "None":
            return None
        if name in ALLOWED_NAMES:
            return getattr(__builtins__, name)
        raise NameError("name '%s' is not defined" % name)
    elif isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.Num):
        return node.n
    elif isinstance(node, ast.Str):
        return node.s
    elif isinstance(node, ast.Bytes):
        return node.s
    elif isinstance(node, ast.NameConstant):
        return node.value
    elif isinstance(node, ast.List):
        return [_eval(e, local_vars) for e in node.elts]
    elif isinstance(node, ast.Tuple):
        t = tuple(_eval(e, local_vars) for e in node.elts)
        if len(t) == 1 and isinstance(t[0], tuple):
            return (t[0],)
        return t
    elif isinstance(node, ast.Set):
        return set(_eval(e, local_vars) for e in node.elts)
    elif isinstance(node, ast.Dict):
        d = {}
        for k, v in zip(node.keys, node.values):
            if k is None:
                continue
            key = _eval(k, local_vars)
            val = _eval(v, local_vars)
            d[key] = val
        return d
    elif isinstance(node, ast.Call):
        func = _eval(node.func, local_vars)
        args = [_eval(a, local_vars) for a in node.args]
        kwargs = {}
        for kw in node.keywords:
            key = kw.arg if kw.arg else ""
            val = _eval(kw.value, local_vars)
            kwargs[key] = val
        return func(*args, **kwargs)
    elif isinstance(node, ast.UnaryOp):
        operand = _eval(node.operand, local_vars)
        op = node.op
        if isinstance(op, ast.UAdd):
            return +operand
        elif isinstance(op, ast.USub):
            return -operand
        elif isinstance(op, ast.Not):
            return not operand
        elif isinstance(op, ast.Invert):
            return ~operand
        else:
            raise _EvalError("unsupported unary op")
    elif isinstance(node, ast.BinOp):
        left = _eval(node.left, local_vars)
        right = _eval(node.right, local_vars)
        op = node.op
        if isinstance(op, ast.Add):
            return left + right
        elif isinstance(op, ast.Sub):
            return left - right
        elif isinstance(op, ast.Mult):
            return left * right
        elif isinstance(op, ast.Div):
            return left / right
        elif isinstance(op, ast.FloorDiv):
            return left // right
        elif isinstance(op, ast.Mod):
            return left % right
        elif isinstance(op, ast.Pow):
            return left ** right
        elif isinstance(op, ast.LShift):
            return left << right
        elif isinstance(op, ast.RShift):
            return left >> right
        elif isinstance(op, ast.BitOr):
            return left | right
        elif isinstance(op, ast.BitAnd):
            return left & right
        elif isinstance(op, ast.BitXor):
            return left ^ right
        else:
            raise _EvalError("unsupported binary op")
    elif isinstance(node, ast.BoolOp):
        values = node.values
        op = node.op
        if isinstance(op, ast.And):
            result = True
            for v in values:
                r = _eval(v, local_vars)
                result = r
                if not r:
                    break
            return result
        elif isinstance(op, ast.Or):
            result = False
            for v in values:
                r = _eval(v, local_vars)
                result = r
                if r:
                    break
            return result
    elif isinstance(node, ast.Compare):
        left = _eval(node.left, local_vars)
        operators = node.ops
        comparators = node.comparators
        i = 0
        for op in operators:
            right = _eval(comparators[i], local_vars)
            ok = False
            if isinstance(op, ast.Eq):
                ok = left == right
            elif isinstance(op, ast.NotEq):
                ok = left != right
            elif isinstance(op, ast.Lt):
                ok = left < right
            elif isinstance(op, ast.LtE):
                ok = left <= right
            elif isinstance(op, ast.Gt):
                ok = left > right
            elif isinstance(op, ast.GtE):
                ok = left >= right
            elif isinstance(op, ast.Is):
                ok = left is right
            elif isinstance(op, ast.IsNot):
                ok = left is not right
            elif isinstance(op, ast.In):
                ok = left in right
            elif isinstance(op, ast.NotIn):
                ok = left not in right
            else:
                raise _EvalError("unsupported comparison")
            if not ok:
                return False
            left = right
            i += 1
        return True
    elif isinstance(node, ast.IfExp):
        test = _eval(node.test, local_vars)
        if test:
            return _eval(node.body, local_vars)
        else:
            return _eval(node.orelse, local_vars)
    elif isinstance(node, ast.Attribute):
        value = _eval(node.value, local_vars)
        return getattr(value, node.attr)
    elif isinstance(node, ast.Subscript):
        value = _eval(node.value, local_vars)
        slice_node = node.slice
        if hasattr(slice_node, 'value'):
            index = _eval(slice_node.value, local_vars)
        else:
            index = _eval(slice_node, local_vars)
        return value[index]
    elif isinstance(node, ast.Index):
        return _eval(node.value, local_vars)
    else:
        raise _EvalError("unsupported AST node: %s" % type(node).__name__)


def safe_eval(expr_str):
    tree = ast.parse(expr_str, mode='eval')
    local_vars = {}
    return _exec_node(tree, local_vars)


