import math


def _strip(s):
    return s.strip()


def _skip_ws(t, i):
    while i < len(t) and t[i] == ' ':
        i += 1
    return i


def _parse_string(t, i):
    q = t[i]; i += 1
    buf = []
    while i < len(t):
        c = t[i]
        if c == q:
            return ''.join(buf), i + 1
        elif c == '\\':
            if i + 1 >= len(t):
                raise SyntaxError("bad escape")
            e = t[i+1]
            buf.append({
                "n": "\n", "t": "\t", "\\": "\\", "'": "'", '"': '"'
            }.get(e, e))
            i += 2
        else:
            buf.append(c); i += 1
    raise SyntaxError("unterminated string")


def _parse_number_or_call(t, i, depth=0):
    # returns (value, next_i)
    if depth > 6:
        raise ValueError("too deep")
