        raise SyntaxError("not a number")
    # identifier -> treat as error for this subset (we do not use bare names besides float( handled above)
    raise SyntaxError("unsupported token: " + t[i:i+8])


def _parse_atom(t, i):
    i = _skip_ws(t, i)
    if i >= len(t):
        raise SyntaxError("unexpected end")
    c = t[i]
    if c == '(':
        # tuple/list or parenthesized expr. We need to disambiguate based on closing char and commas.
        open_idx = i
        depth = 0
        k = i
        while k < len(t):
            if t[k] == '(':
                depth += 1
            elif t[k] == ')':
                depth -= 1
                if depth == 0:
                    break
            k += 1
        close = k
        inner = t[i+1:close]
        # Determine if it's a tuple (ends with comma right before ) or has multiple top-level items separated by commas)
        # We'll parse as list/tuple of atoms. If single element without trailing comma inside parentheses -> value
        # But for our expressions "(1,)" vs "[1]" etc. Let's just collect via a simple splitter respecting nested brackets/braces/quotes.
        parts = _split_top(inner, ',')
        vals = [_parse_expr_str(p) for p in parts]
        if c == '(':
            is_tuple = (len(vals) == 1 and _end_with_comma(inner)) or len(vals) > 1
            if is_tuple:
                return tuple(vals), close + 1
            else:
                return vals[0], close + 1
        elif c == '[':
            return vals, close + 1
        elif c == '{':
            return set(vals), close + 1
        raise SyntaxError("unknown bracket")
    elif c == '[':
        k = i
        depth = 0
        while k < len(t):
            if t[k] == '[':
                depth += 1
            elif t[k] == ']':
                depth -= 1
                if depth == 0:
                    break
            k += 1
        close = k
        inner = t[i+1:close]
        parts = _split_top(inner, ',')
        vals = [_parse_expr_str(p) for p in parts]
        return vals, close + 1
    elif c == '{':
        k = i
        depth = 0
        while k < len(t):
            if t[k] == '{':
                depth += 1
            elif t[k] == '}':
                depth -= 1
                if depth == 0:
                    break
            k += 1
        close = k
        inner = t[i+1:close]
        parts = _split_top(inner, ',')
        vals = [_parse_expr_str(p) for p in parts]
        return set(vals), close + 1
    elif c == "'" or c == '"':
        v, ni = _parse_string(t, i)
        return v, ni
    else:
        return _parse_number_or_call(t, i)


def _end_with_comma(s):
    s = s.rstrip()
    return s.endswith(',')


def _split_top(s, sep):
    # split s on sep at top level, respecting quotes and brackets/parens/braces
    out = []
    depth = 0
    in_q = None
    esc = False
    cur = []
    for ch in s:
        if in_q:
            cur.append(ch)
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == in_q:
                in_q = None
            continue
        if ch in ('"', "'"):
            in_q = ch
            cur.append(ch)
        elif ch in '([{':
            depth += 1
            cur.append(ch)
        elif ch in ')]}':
            depth -= 1
            cur.append(ch)
        elif ch == sep and depth == 0:
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    tail = ''.join(cur).strip()
    if tail != '':
        out.append(tail)
    # filter empty entries that are purely from trailing separators
    res = []
    for e in out:
        if e.strip() == '':
            continue
        res.append(e)
    return res


def _parse_expr_str(s):
    # parse a single expression string (no comparison chaining) into value
    t = _strip(s)
    i = 0

    def parse_atom():
        nonlocal i
        return _parse_atom(t, i)[0], _parse_atom(t, i)[1]

    # atom
    val, i = _parse_atom(t, 0)
    return val


