import math

def _compare(a, b):
    ta = type(a)
    tb = type(b)
    if ta is not tb:
        raise TypeError("<" not supported between instances of '%s' and '%s'" % (ta.__name__, tb.__name__))
    if isinstance(a, float) and isinstance(b, float):
        return 0 if a == b or (math.isnan(a) and math.isnan(b)) else (1 if a > b else -1)
    try:
        eq = (a == b)
    except Exception as e:
        raise
    if eq:
        return 0
    lt = (a < b)
    if lt:
        return -1
    return 1

def _lt(a, b):
    return _compare(a, b) < 0

def _le(a, b):
    return _compare(a, b) <= 0

def _gt(a, b):
    return _compare(a, b) > 0

def _ge(a, b):
    return _compare(a, b) >= 0

def _sorted(x):
    arr = list(x)
    for i in range(len(arr)):
        for j in range(i+1, len(arr)):
            c = _compare(arr[i], arr[j])
            if c > 0:
                arr[i], arr[j] = arr[j], arr[i]
    return arr

