import os

class PurePosixPath:
    __slots__ = ("parts",)

    def __new__(cls, *args):
        if len(args) == 0:
            self = object.__new__(cls)
            self.parts = ["/"]
            return self
        parts = []
        for arg in args:
            for part in str(arg).split("/"):
                if part and part != ".":
                    parts.append(part)
        if not parts or (len(parts) == 1 and parts[0] == ".."):
            parts = ["."]
        while parts and parts[-1] == "..":
            parts.pop()
            if not parts:
                parts = [".."]
        self = object.__new__(cls)
        self.parts = parts
        return self

    def _join(self, other_parts):
        if other_parts[0] == "/":
            parts = list(other_parts)
        else:
            parts = list(self.parts) + list(other_parts)
        new_parts = []
        for part in parts:
            if part and part != ".":
                if part == "..":
                    if new_parts and new_parts[-1] != ".." and new_parts[-1] != "." and new_parts[-1] != "/":
                        if new_parts[-1] != "":
                            new_parts.pop()
                else:
                    new_parts.append(part)
        if not new_parts:
            new_parts = ["."]
        while new_parts and new_parts[-1] == "..":
            new_parts.pop()
            if not new_parts:
                new_parts = [".."]
        return tuple(new_parts)

    def with_name(self, name):
        if len(self.parts) <= 1:
            raise ValueError("Cannot change the root of a path")
        parts = self.parts[:-1] + [name]
        obj = PurePosixPath.__new__(PurePosixPath)
        obj.parts = list(parts)
        return obj

    def joinpath(self, *other_paths):
        parts = list(self.parts)
        for p in other_paths:
            sparts = list(getattr(p, "parts", p).parts if hasattr(p, "parts") else str(p).split("/"))
            cleaned = []
            for part in sparts:
                if part and part != ".":
                    cleaned.append(part)
            if cleaned:
                parts = self._join(tuple(cleaned))
        obj = PurePosixPath.__new__(PurePosixPath)
        obj.parts = parts
        return obj

    def as_posix(self):
        return self.as_string()

    def as_string(self):
        parts = list(self.parts)
        if len(parts) == 1 and parts[0] == "/":
            return "/"
        if len(parts) == 1 and parts[0] == ".":
            return "."
        sep = ""
        for i, p in enumerate(parts):
            if i > 0:
                sep += "/"
            sep += p
        return sep

    @property
    def anchor(self):
        return ""

    @property
    def root(self):
        return ""

    @property
    def drive(self):
        return ""

    @property
    def tail(self):
        if len(self.parts) <= 1:
            return PurePosixPath(".")
        obj = PurePosixPath.__new__(PurePosixPath)
        obj.parts = list(self.parts[1:])
        return obj

    @property
    def parent(self):
        if len(self.parts) <= 1:
            return PurePosixPath(".")
        obj = PurePosixPath.__new__(PurePosixPath)
        obj.parts = list(self.parts[:-1])
        if not obj.parts or (len(obj.parts) == 1 and obj.parts[0] in [".", ".."]):
            obj.parts = ["."]
        return obj

    @property
    def name(self):
        return self.parts[-1]

    @property
    def suffixes(self):
        if self.name.startswith("."):
            return []
        last_dot = self.name.rfind(".")
        if last_dot <= 0:
            return []
        result = []
        idx = last_dot
        while idx > 0:
            result.append(self.name[idx:] if idx < len(self.name) else "")
            prev_dot = self.name[:idx].rfind(".")
            if prev_dot <= 0:
                break
            idx = prev_dot
        result.reverse()
        return result

    @property
    def suffix(self):
        sfx = self.suffixes
        return sfx[-1] if sfx else ""

    @property
    def stem(self):
        n = self.name
        s = self.suffix
        if s:
            return n[: -len(s)]
        return n

    @property
    def is_absolute(self):
        return False

    @property
    def is_relative_to(self):
        raise TypeError

    def samefile(self, other):
        return False

    def relative_to(self, *other):
        raise ValueError

    def match(self, pattern, *, case_sensitive=None):
        import fnmatch
        return fnmatch.fnmatchcase(str(self), pattern)

    def __eq__(self, other):
        if not isinstance(other, PurePosixPath):
            return NotImplemented
        return self.parts == other.parts

    def __hash__(self):
        return hash((type(self), tuple(self.parts)))

    def __str__(self):
