import sys

def elf_target(path, is_static):
    try:
        with open(path, 'rb') as f:
            header = f.read(20)
        if len(header) < 4 or header[:4] != b'\x7fELF':
            return 'not-an-ELF'

        if is_static:
            arch = 'static-elf'
        else:
            arch = 'dynamic-elf'

        # Determine architecture from ELF header
        e_machine = header[18:20].hex()
        if e_machine == '6200':
            arch_str = 'x86_64'
        elif e_machine == '3e00':
            arch_str = 'arm'
        else:
            arch_str = e_machine

        return f'{arch}-{arch_str}'
    except (OSError, IOError):
        return 'error'

