    if s == "1": return 1
    if s == "97": return 97
    if s == "None": return None
    if s.startswith("'") and s.endswith("'") and len(s) >= 2:
        return s[1:-1]
    if s.startswith("[") and s.endswith("]"):
        inner = s[1:-1].strip()
        return [to_val(inner)]
    if s.startswith("(") and s.endswith(")"):
        inner = s[1:-1].strip()
        if inner == "": return ()
