        else:
            raise ValueError("unknown prefix %r" % prefix)

        if kind == 'str':
            try:
                result = (val in target)
            except TypeError as e:
                return ("error", ("TypeError", str(e)))
        elif kind == 'int':
            try:
                result = (val in target)
            except TypeError as e:
