import ast


def safe_eval(expr):
    tree = ast.parse(expr, mode='eval')
    for node in ast.walk(tree):
        if isinstance(node, ast.Attribute) and isinstance(node.value, (ast.Constant, ast.Name)):
            base_id = None
            if isinstance(node.value, ast.Constant):
                base_id = 'str'
            elif isinstance(node.value, ast.Name):
                base_id = node.value.id
            name = node.attr
            if base_id == 'b' or (isinstance(node.value, ast.Call) is False and base_id is None):
                pass
            # For byte literals like b'abc'.method(...)
            # Check if node.value is a Constant of bytes type OR if it's a Call to bytes
            target = node.value
            while isinstance(target, ast.Attribute):
                target = target.value
            if isinstance(target, ast.Constant) and isinstance(target.value, bytes):
                return getattr(target.value, name)
    code = compile(tree, '<expr>', 'eval')
    namespace = {}
    return eval(code, {'__builtins__': __builtins__}, namespace)


