def _literal_to_value(s):
    s2 = s.strip()
    if s2 == 'None':
        return None
    if len(s2) >= 2 and s2[0] in ('"', "'") and s2[-1] == s2[0]:
        inner = s2[1:-1]
        if s2[0] == "'" and not any(c == "\\" for c in inner):
            try:
                return inner.encode('utf-8')
            except UnicodeEncodeError:
                return None
        if '"' in inner or '\\' in inner:
            return None
        try:
            return bytes(inner, 'utf-8')
        except UnicodeDecodeError:
            return None
        except TypeError:
            return None
    # int?
    t = s2
    if t.startswith('-'):
        pass
    if t.isdigit() or (t.startswith('-') and t[1:].isdigit()):
        try:
            return int(t)
        except ValueError:
            return None
    # list of ints like [97]
    if s2.startswith('[') and s2.endswith(']'):
        inner = s2[1:-1].strip()
        if inner == '':
            return []
        parts = [p.strip() for p in inner.split(',')]
        vals = []
        for p in parts:
            if p.isdigit():
                vals.append(int(p))
            elif p.startswith('-') and p[1:].isdigit():
                vals.append(int(p))
            else:
                return None
        return vals
    # tuple like (97,)
    if s2.startswith('(') and s2.endswith(')'):
        inner = s2[1:-1].strip()
        if inner == '':
            return ()
        # strip trailing comma if present before closing paren
        if inner.endswith(','):
            body = inner[:-1].strip()
        else:
            body = inner
        if body == '':
            return ()
        parts = [p.strip() for p in body.split(',')]
        vals = []
        for p in parts:
            if p.isdigit():
                vals.append(int(p))
            elif p.startswith('-') and p[1:].isdigit():
                vals.append(int(p))
            else:
                return None
        return tuple(vals)
    # fallback: try bytes(...) with a single byte string
    if s2.startswith("b'") and s2.endswith("'"):
        inner = s2[2:-1]
        try:
            return bytes(inner, 'utf-8')
        except Exception:
            return None
    return None


