def eval_containment(exprstr):
    # handle expressions like 'a' in b'abc', 1 in b'abc', 300 in b'abc'
    parts = exprstr.split(' in ')
    if len(parts) != 2:
        return None
    left = parts[0].strip()
    right = parts[1].strip()
    lv = _literal_to_value(left)
    rv = _literal_to_value(right)
    if lv is None or rv is None:
        # maybe it's an int literal without quotes that was caught by _literal_to_value
        pass
    # for right side b'abc'
    if right.startswith("b'") and right.endswith("'"):
        inner = right[2:-1]
        rv = bytes(inner, 'utf-8')
    if lv is None:
        # try int
        if left.isdigit():
            lv = int(left)
    if rv is None:
        return None
    return lv in rv


