# The original program uses `frozenset`. To stay inside the allowed subset we
# emulate just enough of frozenset behaviour for this specific script.
class FS:
    def __init__(self, items=None):
        if items is None:
            self._t = tuple()
        else:
            self._t = tuple(items)
    def __repr__(self):
        return "FS:" + repr(self._t)
    def __eq__(self, other):
        if isinstance(other, FS):
            return self._t == other._t
        try:
            if not hasattr(other, "__iter__"):
                return False
            o = tuple(other)
        except TypeError:
            return False
        # For set/frozenset arguments convert their elements to tuples (for the
        # purpose of hashing equality). We rely on Python's own hash semantics.
        try:
            return self._t == tuple(tuple(x) for x in other) or self._t == tuple(other)
        except Exception:
            return False
    def __ne__(self, other):
        return not self.__eq__(other)
    def __hash__(self):
        # Use a hash that matches what python's set would use for a set of the same
        # contents, so {1} can match a container holding an FS built from [1].
        # Approximation: hash of the tuple of hashes of items.
        # But to actually work with Python sets containing real sets as keys/values,
        # we need to rely on normal hash rules. Since frozenset is being replaced by
        # a custom type, our hash only needs to be consistent within FS objects.
        return hash(self._t)

