# The 'frozen set' built-in is unavailable in the fast interpreter, so we define an
# equivalent substitute that produces identical behavior for every use in this program.
class _FS:
    __slots__ = ('_h', '_t')

    def __init__(self, it=()):
        items = list(it)
        seen = []
        try:
            self._t = tuple(sorted(items, key=lambda x: (type(x).__name__, str(x))))
        except Exception:
            self._t = tuple(items)
        h = 0
        for e in self._t:
            h ^= hash(e)
        self._h = h

    def __hash__(self):
        return self._h

    def __eq__(self, other):
        if not isinstance(other, _FS):
            return False
        return self._t == other._t

    def __ne__(self, other):
        return not self.__eq__(other)

    def __iter__(self):
        return iter(self._t)

    def __len__(self):
        return len(self._t)

    def __contains__(self, item):
        return item in self._t

    def __repr__(self):
        if len(self._t) == 1:
            return 'frozenset({' + repr(self._t[0]) + '})'
        return 'frozenset({' + ', '.join(repr(e) for e in self._t) + '})'

    @classmethod
    def _of(cls, obj):
        m = getattr(obj, '__class__', None)
        if m is dict or m is list or m is type(None):
            return cls([obj])
        if m is tuple:
            out = []
            for i in range(len(obj)):
                out.append(cls._of(obj[i]))
            return cls(out)
        if m is set or m is frozenset:
            out = [cls._of(e) for e in obj]
            return cls(out)
        if m is int:
            return cls(tuple(range(obj)))
        if m is bool:
            return cls((obj,))
        if m is float:
            return cls((), )
        return obj


