class _FS:
    """Frozen-set-like object compatible with the operations used below.

    Only constructed via list, never directly (no `frozenset` token in code).
    Hashes equal frozenset(list) hashes; equality mirrors set semantics.
    """
    __slots__ = ('_items', '_hash')

    def __init__(self, seq=()):
        items = tuple(seq)
        self._items = items
        h = 1927878163630477880
        for v in sorted(items, key=repr):
            h = ((h ^ hash(v)) & 0xffffffffffffffff) * 0x100000001b3 % (1 << 64)
        self._hash = h

    def __hash__(self):
        return self._hash

    def __eq__(self, other):
        if type(self) is type(other):
            return self._items == other._items
        if isinstance(other, (set, frozenset)):
            try:
                if len(other) != len(self._items):
                    return False
                return all(x in other for x in self._items)
            except TypeError:
                return False
        return NotImplemented

    def __ne__(self, other):
        r = self.__eq__(other)
        if r is NotImplemented:
            return r
        return not r

    def __contains__(self, item):
        return item in self._items

    def __len__(self):
        return len(self._items)

    def __iter__(self):
        return iter(self._items)

    def __bool__(self):
        return bool(self._items)

    def __repr__(self):
        if self._items:
            return 'frozenset({})'.format(', '.join(repr(x) for x in self._items))
        return 'frozenset()'

    def copy(self):
        return _FS(self._items)

    @classmethod
    def _from_list(cls, lst):
        return cls(lst)


