class FS:
    __slots__ = ('_data',)
    def __init__(self, iterable=()):
        self._data = tuple(iterable)
    def __hash__(self):
        return hash(self._data)
    def __eq__(self, other):
        if isinstance(other, FS):
            return self._data == other._data
        try:
            ot = tuple(other)
        except TypeError:
            return False
        return self._data == ot
    def __iter__(self):
        return iter(self._data)
    def __repr__(self):
        return 'fs(' + repr(list(self._data)) + ')'

