def _make_frozenset(items):
    class _F:
        __slots__ = ('_h', '_s')
        def __init__(self, it=None):
            if it is None:
                it = []
            lst = list(it)
            self._s = set(lst)
            try:
                self._h = sum(hash(x) for x in self._s)
            except TypeError:
                self._h = 0
            self._items_tuple = tuple(self._s)
        def __hash__(self):
            return self._h
        def __eq__(self, other):
            if isinstance(other, (set, frozenset)):
                s = other
            elif isinstance(other, _F):
                s = other._s
            else:
                return NotImplemented
            return self._s == s
        def __repr__(self):
            return 'frozenset(' + repr(list(self._s)) + ')'
        def __len__(self):
            return len(self._s)
    fs = _F.__new__(_F)
    # we need to set attributes properly
    import types
    obj = object.__new__(_F)
    lst = list(items)
    obj._s = set(lst)
    try:
        obj._h = sum(hash(x) for x in obj._s)
    except TypeError:
        obj._h = 0
    obj._items_tuple = tuple(obj._s)
    return obj

