def matches_segment(path_part, pattern_seg):
    # simple fnmatch-like for single segment with * only
    # convert to a check
    p = pattern_seg
    s = path_part
    # Handle simple wildcard matching (only * and ? assumed)
    def _wild(s, p):
        ls, lp = len(s), len(p)
        # dp
        import re as _re
        return bool(_re.fullmatch(p.replace('?','.'), s)) if False else True  # placeholder
    # Use a manual matcher for * and ?
    def match_all(s, p):
        m, n = len(s), len(p)
        # iterative backtracking for * and ?
        i = j = 0
        star_i = -1
        star_j = -1
        while i < m:
            if j < n and (p[j] == '?' or p[j] == s[i]):
                i += 1; j += 1
            elif j < n and p[j] == '*':
                star_i = i
                star_j = j
                j += 1
            elif star_j != -1:
                i = star_i + 1
                j = star_j + 1
            else:
                return False
        while j < n and p[j] == '*':
            j += 1
        return j == n
    return match_all(s, p)

def collect(dirpath, remaining):
    """remaining: list of pattern segments starting with '**'"""
    if not remaining:
        # dirpath matches
        return [dirpath]
    # remaining[0] should be '**'
    results = []
    if os.path.exists(dirpath):
        try:
            entries = sorted(os.listdir(dirpath))
        except OSError:
            entries = []
        if len(remaining) == 1:
            # '**' only - match everything recursively? glob ** matches zero or more dirs/files
            # files that end with ... actually ** alone matches any file/directory recursively
            # In pathlib glob, '**' matches all files and directories recursively.
            for name in entries:
                full = os.path.join(dirpath, name) if dirpath != '.' else name
                # include current level too (zero depth)
                results.append(full)
                if os.path.isdir(full):
                    results.extend(collect(full, remaining))
        else:
            next_seg = remaining[1]
            next_rest = remaining[2:]
            # zero depth: next_seg must match something in current dir
            for name in entries:
                full = os.path.join(dirpath, name) if dirpath != '.' else name
                if matches_segment(name, next_seg):
                    if not next_rest:
                        results.append(full)
                    else:
                        results.extend(collect(full, next_rest))
            # one or more depth: recurse into subdirectories
            for name in entries:
                full = os.path.join(dirpath, name) if dirpath != '.' else name
                if os.path.isdir(full):
                    results.extend(collect(full, remaining))
    return results

