import json

def surrogate_escape_decode(raw: bytes) -> str:
    parts = []
    i = 0
    n = len(raw)
    while i < n:
        b = raw[i]
        if b < 0x80:
            c = chr(b)
            parts.append(c)
            i += 1
        elif 0xC2 <= b <= 0xDF:
            if i + 1 >= n:
                parts.append('\udc' + format(b, '02x'))
                i += 1
                continue
            b2 = raw[i + 1]
            if 0x80 <= b2 <= 0xBF:
                cp = ((b - 0xC0) << 6) | (b2 - 0x80)
                parts.append(chr(cp))
                i += 2
            else:
                parts.append('\udc' + format(b, '02x'))
                i += 1
        elif 0xE0 <= b <= 0xEF:
            if i + 2 >= n:
                parts.append('\udc' + format(b, '02x'))
                i += 1
                continue
            b2 = raw[i + 1]
            b3 = raw[i + 2]
            if 0x80 <= b2 <= 0xBF and 0x80 <= b3 <= 0xBF:
                cp = ((b - 0xE0) << 12) | ((b2 - 0x80) << 6) | (b3 - 0x80)
                parts.append(chr(cp))
                i += 3
            else:
                parts.append('\udc' + format(b, '02x'))
                i += 1
        elif 0xF0 <= b <= 0xF4:
            if i + 3 >= n:
                parts.append('\udc' + format(b, '02x'))
                i += 1
                continue
            b2 = raw[i + 1]
            b3 = raw[i + 2]
            b4 = raw[i + 3]
            if 0x80 <= b2 <= 0xBF and 0x80 <= b3 <= 0xBF and 0x80 <= b4 <= 0xBF:
                cp = ((b - 0xF0) << 18) | ((b2 - 0x80) << 12) | ((b3 - 0x80) << 6) | (b4 - 0x80)
                if cp <= 0x10FFFF:
                    hi = cp - 0x10000
                    c1 = chr(0xD800 + (hi >> 10))
                    c2 = chr(0xDC00 + (hi & 0x3FF))
                    parts.append(c1 + c2)
                else:
                    parts.append('\udc' + format(b, '02x'))
                i += 4
            else:
                parts.append('\udc' + format(b, '02x'))
                i += 1
        else:
            # invalid byte
            parts.append('\udc' + format(b, '02x'))
            i += 1
    return ''.join(parts)


def surrogate_escape_encode(s: str) -> bytes:
    out = bytearray()
    for ch in s:
        code = ord(ch)
        if code < 0xD800 or code >= 0xE000:
            out.extend(ch.encode('utf-8'))
        else:
            # surrogate escape
            out.append(code - 0xDC00)
    return bytes(out)


