        elif 0xC0 <= byte <= 0xDF:
            # 2-byte sequence
            if i + 1 < n:
                b2 = raw[i + 1]
                cp = ((byte & 0x1F) << 6) | (b2 & 0x3F)
                t_parts.append(chr(cp))
                i += 2
            else:
                t_parts.append(chr(0xDC80 + byte))
                i += 1
        elif 0xE0 <= byte <= 0xEF:
            # 3-byte sequence
            if i + 2 < n:
                b2 = raw[i + 1]
                b3 = raw[i + 2]
                cp = ((byte & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F)
                t_parts.append(chr(cp))
                i += 3
            else:
                t_parts.append(chr(0xDC80 + byte))
                i += 1
        elif 0xF0 <= byte <= 0xF7:
            # 4-byte sequence
            if i + 3 < n:
                b2 = raw[i + 1]
                b3 = raw[i + 2]
                b4 = raw[i + 3]
                cp = ((byte & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F)
                t_parts.append(chr(cp))
                i += 4
            else:
                t_parts.append(chr(0xDC80 + byte))
