            result.append('\\n')
        elif c == '\r':
            result.append('\\r')
        elif c == '\t':
            result.append('\\t')
        else:
            o = ord(c)
            if o < 0x20:
                result.append('\\u%04x' % o)
            elif 0xD800 <= o <= 0xDFFF:
                # Surrogate characters in JSON strings
                result.append('\\u%04x' % o)
            else:
                result.append(c)
    result.append('"')
    return ''.join(result)

