# Simple parser for our known structure
def json_parse_simple(s):
    # Find "stdout" value
    idx = s.find('"stdout"')
    if idx == -1:
        return None
    idx += len('"stdout"')
    # Skip whitespace
    while idx < len(s) and s[idx] in ' \t\r\n':
        idx += 1
    # Expect ':'
    if idx < len(s) and s[idx] == ':':
        idx += 1
    # Skip whitespace
    while idx < len(s) and s[idx] in ' \t\r\n':
        idx += 1
    # Should be a string starting with '"'
    if idx < len(s) and s[idx] == '"':
        idx += 1
        chars = []
        while idx < len(s) and s[idx] != '"':
            if s[idx] == '\\':
                idx += 1
                if idx >= len(s):
                    break
                c = s[idx]
                if c == 'u':
                    hexstr = s[idx + 1:idx + 5]
                    codepoint = int(hexstr, 16)
                    chars.append(chr(codepoint))
                    idx += 5
                else:
                    mapping = {'n': '\n', 't': '\t', 'r': '\r', 'b': '\b', 'f': '\f', '"': '"', '\\': '\\', '/': '/'}
                    chars.append(mapping.get(c, c))
                    idx += 1
            else:
                chars.append(s[idx])
                idx += 1
        return ''.join(chars)
    return None

