def _match_byte(b):
    return b == 32 or (9 <= b <= 13)

def _findall_bytes_space(data):
    return [bytes([c]) for c in data if _match_byte(c)]

def _match_unicode_space(ch, ascii_only):
    if ascii_only:
        return ch in ' \t\n\r\f\v'
    else:
        o = ord(ch)
        if o == 32 or (9 <= o <= 13):
            return True
        if o == 0x85 or o == 0xa0:
            return True
        if ch.isspace():
            return True
        return False

def _findall_str_space(s, ascii_only=False):
    return [ch for ch in s if _match_unicode_space(ch, ascii_only)]

def _findall_dots(data):
    return list(data)

def _is_word_byte(b):
    if 48 <= b <= 57:
        return True
    if 65 <= b <= 90:
        return True
    if 97 <= b <= 122:
        return True
    if b == 95:
        return True
    return False

def _findall_words_bytes(data):
    words = []
    current = bytearray()
    for b in data:
        if _is_word_byte(b):
            current.append(b)
        else:
            if len(current) > 0:
                words.append(bytes(current))
                current = bytearray()
    if len(current) > 0:
        words.append(bytes(current))
    return words

