def fetch(pkg):
    url = "https://pypi.org/pypi/%s/json" % pkg
    with urllib.request.urlopen(url, timeout=60) as r:
        return r.read()

# Cache for the in-process interpreter; otherwise a temp file survives between processes.
CACHE = os.path.join(os.path.dirname(os.path.abspath(__file__)) or ".", ".pypi_cache")
try:
    _cache = None
except Exception:
    _cache = {}


def load_cache():
    global _cache
    if _cache is not None:
        return _cache
    try:
        with open(CACHE, "r") as f:
            _cache = json.load(f)
    except Exception:
        _cache = {}
    return _cache


def save_cache():
    try:
        with open(CACHE, "w") as f:
            json.dump(_cache, f)
    except Exception:
        pass


def get_data(pkg):
    c = load_cache()
    cached = c.get(pkg)
    if isinstance(cached, dict) and "data" in cached and "error" not in cached:
        return json.loads(cached["data"])
    if isinstance(cached, dict) and "error" in cached:
        raise RuntimeError(cached["error"])
    try:
        raw = fetch(pkg)
        text = raw.decode("utf-8")
        d = json.loads(text)
        c[pkg] = {"data": text}
        save_cache()
        return d
    except Exception as e:
        err = repr(e)
        c[pkg] = {"error": err}
        save_cache()
        raise RuntimeError(err)


