# Build a frozen-ish class E with __init__, __repr__, __eq__ and hash that
# works even when models is a mutable dict (hash will fail via unhashable).
class E:
    def __init__(self, id, models=None):
        object.__setattr__(self, "id", id)
        if models is None:
            object.__setattr__(self, "models", {})
        else:
            object.__setattr__(self, "models", models)
        # mark frozen
        object.__setattr__(self, "_frozen", True)

    def __setattr__(self, name, value):
        if getattr(self, "_frozen", False):
            raise AttributeError("can't set attribute")
        object.__setattr__(self, name, value)

    def __delattr__(self, name):
        if getattr(self, "_frozen", False):
            raise AttributeError("can't delete attribute")
        object.__delattr__(self, name)

    def __eq__(self, other):
        if not isinstance(other, E):
            return NotImplemented
        return self.id == other.id and self.models == other.models

    def __ne__(self, other):
        r = self.__eq__(other)
        if r is NotImplemented:
            return r
        return not r

    def __hash__(self):
        try:
            return hash((self.id, self.models))
        except TypeError:
            # emulate dataclass: hash based on tuple of field values
            return hash((self.id, self.models))

    def __repr__(self):
        return "E(id=%r, models=%r)" % (self.id, self.models)


