def dataclass(_cls, frozen=None):
    def __init__(self, *args, **kwargs):
        f_ = _cls.__fields__
        names = list(f_)
        # assign
        vals = []
        for i in range(len(args)):
            vals.append(args[i])
        for n in names:
            if n in kwargs:
                if len(vals) == len(names):
                    raise TypeError("multiple values for argument '%s'" % n)
