def _decode(data, validate):
    data = bytes(data)
    if len(data) % 4:
        raise binascii.Error('Invalid base64-encoded string: number of data characters ({}), cannot be multiple of 4'.format(len(data)))
    padcount = 0
    while data and data[-1] == 61:
        padcount += 1
        data = data[:-1]
    if len(data) % 4:
        raise binascii.Error('Invalid base64-encoded string: number of data characters ({}), cannot be multiple of 4'.format(len(data)))
    if not validate:
        clean = bytearray()
        for c in data:
            if c < 0 or c > 255:
                continue
            if chr(c) in '\n\r\t':
                continue
            if b64_table.get(chr(c), None) is not None:
                clean.append(c)
        data = bytes(clean)
    try:
        vals = []
        for c in data:
            v = b64_table[chr(c)]
            vals.append(v)
    except Exception:
        raise binascii.Error("Non-base64 digit found")
    out = bytearray()
    i = 0
    n = len(vals)
    while i < n:
        a = vals[i]; b = vals[i+1]; cc = vals[i+2]; d = vals[i+3]
        if i + 4 <= n:
            pass
        out.append((a << 2) | (b >> 4))
        out.append(((b & 0x0F) << 4) | (cc >> 2))
        out.append(((cc & 0x03) << 6) | d)
        i += 4
    if padcount == 2:
        del out[-2:]
    elif padcount == 1:
        del out[-1:]
    return bytes(out)

