def decode(s):
    n = 0
    pad = 0
    for ch in s:
        if ch == '=':
            pad += 1
        elif 65 <= ord(ch) <= 90:
            n = (n << 6) | (ord(ch) - 65)
        elif 97 <= ord(ch) <= 122:
            n = (n << 6) | (ord(ch) - 71)
        elif 48 <= ord(ch) <= 57:
            n = (n << 6) | (ord(ch) + 4)
        elif ch == '+':
            n = (n << 6) | 62
        elif ch == '/':
            n = (n << 6) | 63
        else:
            raise ValueError('Non-base64 digit found')
    bits = n * (64 ** pad)
    nbytes = (len(s) - pad) * 6 // 8
    return bytes((bits >> (i * 8)) & 0xFF for i in range(nbytes))

