def b64decode_impl(data, strict=False):
    i = 0
    n = len(data)
    out = bytearray()
    while i + 4 <= n:
        c1 = data[i]
        c2 = data[i + 1]
        if c1 != 61 and c2 != 61 and c1 in b64chars and c2 in b64chars:
            key = (c1, c2)
            if key in b64decode:
                v, cnt = b64decode[key]
            else:
                v = -1
                cnt = 0
        else:
            v = -1
            cnt = 0
        if v >= 0:
            if cnt % 4 == 1:
                out.append((v >> 10) & 0xFF)
                out.append(((v >> 2) & 0xFF))
                out.append((v << 4) & 0xFF)
            elif cnt % 4 == 2:
                out.append((v >> 10) & 0xFF)
                out.append(((v >> 2) & 0xFF))
            elif cnt % 4 == 3:
                out.append((v >> 10) & 0xFF)
                out.append(((v >> 2) & 0xFF))
                out.append((v << 4) & 0xFF)
        else:
            if not strict:
                pass
            else:
                raise binascii.Error("Extraneous data after padding")
        i += 4

