import re

_WARNING_RE = re.compile(r'^\S+:\d+: (?:UserWarning|SyntaxWarning|DeprecationWarning|ResourceWarning|PendingDeprecationWarning|FutureWarning|RuntimeWarning|ImportWarning):.*$')

def _without_warnings(text):
    out_lines = []
    skip_echoed_message = False
    for line in text.splitlines():
        if _WARNING_RE.match(line):
            # The next line may be the indented continuation of the warning message
            skip_echoed_message = True
            continue
        if skip_echoed_message:
            if line.startswith('  '):
                continue
            skip_echoed_message = False
        out_lines.append(line)
    return '\n'.join(out_lines)

