import re
from ast import parse as _ast_parse, Expression as _Expr

# We cannot use eval directly. But we can parse the string and then evaluate
# a restricted AST manually that only handles what appears in the test cases.
# All test cases are expressions of the form:
#   name(args) or attribute chains with calls.
# The names involved: re.sub, re.split, re.findall, re.match, re.compile,
#                     re.escape, re.purge, lambda, None, literals (strings, ints, floats),
#                     and method calls like .search(), .groups(), .group(), .span()
# Also attribute access like re.I, re.M, re.X
# And tuple unpacking? No, just function calls with positional args.

# Let me build a small evaluator for the specific grammar needed.

def _eval_node(node):
    # Literal
    if node.__class__.__name__ == 'Constant':
        return node.value
    if node.__class__.__name__ == 'Name':
        # Global names: re, lambda not here, None handled by Constant
        return globals()[node.id]
    if node.__class__.__name__ == 'Attribute':
        value = _eval_node(node.value)
        return getattr(value, node.attr)
    if node.__class__.__name__ == 'Call':
        func = _eval_node(node.func)
        args = [_eval_node(a) for a in node.args]
        kwargs = [None]*len(node.keywords)  # not used in tests
        for kw in node.keywords:
            pass
        return func(*args)
    if node.__class__.__name__ == 'Lambda':
        # Build a real lambda from the arguments list (names) and body
        arg_names = [a.arg for a in node.args.args]
        body_node = node.body
        # Create a local dict scope
        def make_lambda(arg_names, body_node):
            code = compile(_Expr(body_node), '<lambda>', 'eval')
