def _eval_in_namespace(tree, local_ns, global_ns):
    # tree is an AST node (the body of the lambda)
    # Evaluate it with local names taking precedence over globals
    class Eval:
        def __init__(self, tree, local_ns, global_ns):
            self.tree = tree
            self.local_ns = local_ns
            self.global_ns = global_ns
        def go(self):
            return self._eval(self.tree)
        def _eval(self, node):
            tn = node.__class__.__name__
            if tn == 'Constant':
                return node.value
            if tn == 'Name':
                if node.id in self.local_ns:
                    return self.local_ns[node.id]
                return self.global_ns[node.id]
            if tn == 'Attribute':
                v = self._eval(node.value)
                return getattr(v, node.attr)
            if tn == 'Call':
                f = self._eval(node.func)
                args = [self._eval(a) for a in node.args]
                return f(*args)
            if tn == 'BinOp':
                l = self._eval(node.left)
                r = self._eval(node.right)
                op = node.op.__class__.__name__
                if op == 'Add': return l + r
                if op == 'Sub': return l - r
                if op == 'Mult': return l * r
                if op == 'Div': return l / r
                if op == 'Mod': return l % r
                if op == 'Pow': return l ** r
                raise ValueError(op)
            raise ValueError(tn)
    return Eval(tree, local_ns, global_ns).go()

