import re


class _FakeMatch:
    def __init__(self, groups, full):
        self._groups = groups
        self._full = full

    def span(self):
        return (0, len(self._full))

    def group(self, *args):
        if not args:
            return self._full
        g = args[0]
        if isinstance(g, bool):
            raise IndexError("group number is out of range")
        if g >= 1 and g <= len(self._groups) and self._groups[g - 1] is not None:
            return self._groups[g - 1]
        raise IndexError("no such group")

    def groups(self):
        return tuple(self._groups)

    def __getitem__(self, i):
        if isinstance(i, bool):
            raise TypeError("match indices must be integers")
        return self.group(i)


def _sub_impl(pattern, repl, string, count=0, flags=0):
    p = re.compile(pattern, flags)
    if callable(repl):
        s = str(string)
        result = []
        pos = 0
        c = 0
        for m in p.finditer(s):
            r = repl(m)
            if r is None:
                r = ""
            else:
                r = str(r)
            result.append(s[pos:m.start()])
            result.append(r)
            pos = m.end()
            c += 1
            if count and c >= count:
                break
        result.append(s[pos:])
        return "".join(result)
    return p.sub(repl, string, count)


def _split_impl(pattern, string, maxsplit=0, flags=0):
    p = re.compile(pattern, flags)
    return p.split(string, maxsplit)


def _findall_impl(pattern, string, flags=0):
    p = re.compile(pattern, flags)
    return p.findall(string)


def _match_impl(pattern, string, flags=0):
    p = re.compile(pattern, flags)
    m = p.match(string)
    if m is None:
        raise Exception("no match")
    return _FakeMatch(list(m.groups()), string[m.start():m.end()])


def _escape_impl(arg):
    s = ""
    for ch in arg:
        if ch.isalnum():
            s += ch
        else:
            s += "\\" + ch
    return s


