import re

def safe_eval(src):
    # A tiny, self-contained evaluator sufficient for the given program.
    # Supports: literals (str, int), names (re and builtins used via direct module calls),
    # call expressions with args/kwargs, attribute access on results.
    # Grammar handled:
    #   expr := call | atom
    #   call := atom ( '(' arglist? ')' )  ; we actually parse postfix after each atom
    # We'll implement a recursive descent parser producing values directly.

    i = 0
    n = len(src)

    def skip_ws():
        nonlocal i
        while i < n and src[i].isspace():
            i += 1

    def parse_string():
        nonlocal i
        quote = src[i]; i += 1
        r = []
        while i < n and src[i] != quote:
            c = src[i]
            if c == '\\' and i + 1 < n:
                nxt = src[i+1]
                if nxt == 'n': r.append('\n'); i += 2; continue
                if nxt == 't': r.append('\t'); i += 2; continue
