class MT19937:
    N = 624
    M = 397
    MATRIX_A = 0x9908b0df
    UPPER_MASK = 0x80000000
    LOWER_MASK = 0x7fffffff

    def __init__(self, seed):
        self.mt = [0] * self.N
        self.index = self.N + 1
        self.init_genrand(seed)

    def init_by_array(self, init_key):
        key_length = len(init_key)
        self.init_genrand(19650218)
        i = 1
        j = 0
        k = max(self.N, key_length)
        while k:
            # LCG from Knuth
            init_key[j] ^= (self.mt[i - 1] ^ (self.mt[i - 1] >> 30)) * 1664525
            init_key[j] &= 0xffffffff
            self.mt[i] = (self.mt[i] ^ init_key[j]) & 0xffffffff
            i += 1
            j += 1
            if i >= self.N:
                self.mt[0] = self.mt[self.N - 1]
                i = 1
            if j >= key_length:
                j = 0
            k -= 1
        k = self.N - 1
        while k:
            self.mt[i] = (self.mt[i] ^ (self.mt[(i + 1) % self.N] ^ (self.mt[(i + 1) % self.N] >> 30))) * 1566083941
            self.mt[i] &= 0xffffffff
            i += 1
            if i >= self.N:
                self.mt[0] = self.mt[self.N - 1]
                i = 1
            k -= 1
        self.mt[0] = 0x80000000

    def init_genrand(self, s):
        self.mt[0] = s & 0xffffffff
        for i in range(1, self.N):
            prev = self.mt[i - 1]
            self.mt[i] = (1812433253 * (prev ^ (prev >> 30)) + i) & 0xffffffff

    def generate_numbers(self):
        if self.index >= self.N:
            for i in range(self.N):
                y = (self.mt[i] & self.UPPER_MASK) | (self.mt[(i + 1) % self.N] & self.LOWER_MASK)
                if y & 1:
                    y ^= self.MATRIX_A
                self.mt[i] = self.mt[(i + self.M) % self.N] ^ y
            self.index = 0

    def genrand_int32(self):
        self.generate_numbers()
        y = self.mt[self.index]
        self.index += 1
        y ^= (y >> 11)
        y ^= (y << 7) & 0x6d2b79f5
        y ^= (y << 15) & 0xefc60000
        y ^= (y >> 18)
        return y & 0xffffffff

    def randint(self, a, b):
        if a > b:
            raise ValueError
        diff = b - a + 1
        r = self.genrand_int32()
        if diff <= (0xffffffff - (diff % (0xffffffff + 1)) + 1):
