import subprocess, collections, re

B = "src/lypning/assets/rust/target/x86_64-unknown-linux-musl/release/lypning"

out = subprocess.run(["nm", "--size-sort", "-S", "--demangle", B], capture_output=True, text=True).stdout

buckets = collections.Counter()
total = 0
for line in out.splitlines():
    parts = line.split(None, 3)
    if len(parts) < 4:
        continue
    try:
        sz = int(parts[1], 16)
    except ValueError:
        continue
    name = parts[3]
    total += sz
    if name.startswith("lypning::"):
        mod = name.split("::")[1]
        buckets["lypning::" + mod] += sz
    elif "core::fmt" in name or "core::fmt" in name:
        buckets["core::fmt (formatting)"] += sz
    elif name.startswith("core::") or name.startswith("<core::"):
        buckets["core:: (rest)"] += sz
    elif name.startswith("alloc::") or name.startswith("<alloc::"):
        buckets["alloc::"] += sz
    elif name.startswith("std::") or name.startswith("<std::"):
        buckets["std::"] += sz
    elif "panic" in name or "unwind" in name or "backtrace" in name:
        buckets["panic/unwind"] += sz
    else:
        buckets["libc/musl + other"] += sz

print("attributed %d bytes of symbols\n" % total)
for k, v in buckets.most_common(14):
    print("  %-30s %8d  (%4.1f%%)" % (k, v, 100 * v / total))

