def make_int_format(orig):
    def fmt(self, spec=''):
        if spec == '' or spec is None:
            return orig(self, '')
        sspec = str(spec)
        # Detect if type specifier is 'n'
        # Parse: find the last letter that could be a type
        # Type chars: b, c, d, o, x, X, e, E, f, F, g, G, n, %, ,
        type_chars = set('bcdoxXeEfFgGn% ,')
        # Walk from end to find type
        j = len(sspec) - 1
        # Skip nothing - the very last character is either type or width digit
        # Format grammar structure means type is always last if present
        typ_char = sspec[j] if sspec else ''

        if typ_char == 'n':
            base = sspec[:-1]
            # Use 'd' for integers
            return orig(self, base + 'd')
        elif typ_char == '%':
            # Percent: multiply by 100 and use 'f'
            base = sspec[:-1]
            try:
                val = self * 100
                return orig(val, base + 'f') + '%'
            except Exception:
                return orig(self, spec)
        else:
            return orig(self, spec)
    return fmt


def make_float_format(orig):
    def fmt(self, spec=''):
        if spec == '' or spec is None:
            return orig(self, '')
        sspec = str(spec)
        typ_char = sspec[-1] if sspec else ''

        if typ_char == 'n':
            base = sspec[:-1]
            # For floats with 'n', use 'f'
            return orig(self, base + 'f')
        elif typ_char == '%':
            base = sspec[:-1]
            try:
                val = self * 100
                return orig(val, base + 'f') + '%'
            except Exception:
                return orig(self, spec)
        else:
            return orig(self, spec)
    return fmt


