def _apply_n_comma(value, align, sign, alt, zero, width, typ):
    # Produce the locale-independent equivalent of format(value, f'{align}{sign}{alt}{zero}{width},').
    if isinstance(value, bool):
        return format(bool(value), f"{align}{sign}{alt}{zero}{width},")
    if isinstance(value, int):
        w = f"{width}," if width else ","
        return format(int(value), f"{align}{sign}{alt}{w}")
    # float / Decimal / NaN / inf
    prec = "6"
    try:
        s0 = f"{value:f}"
        idx = s0.find(".")
        if idx != -1:
            p = len(s0) - idx - 1
            if p > 0:
                prec = str(p)
    except Exception:
        pass
    tmap = {"f": "f", "F": "F", "e": "e", "E": "E", "g": "g", "G": "G", "%": "%"}
    ct = tmap[typ] if typ in tmap else "f"
    if not (prec == "6" and ct == "f"):
        prec_opt = ("." + prec + ct)
    else:
        prec_opt = ""
    return format(float(value), f"{align}{sign}{alt}{zero}{width},{prec_opt}")


def _fmt(value, spec):
    i = 0
    while i < len(spec) and spec[i] in "<>^=+- ":
        i += 1
    pre = spec[:i]
    rest = spec[i:]
    j = 0
    while j < len(rest) and rest[j] in "#0":
        j += 1
    mid = rest[:j]
    tail = rest[j:]
    k = 0
    while k < len(tail) and tail[k].isdigit():
        k += 1
    width_s = tail[:k]
    type_c = tail[k:k+1] if k < len(tail) else ""
    # Parse aligned fields into slots matching _apply_n_comma parameters
    align = ""; sign = ""; alt = ""; zero = ""
    for ch in pre:
        if ch in "<>^=":
            align = ch
        elif ch in "+- ":
            sign = ch
    for ch in mid:
        if ch == "#":
            alt = "#"
        elif ch == "0":
            zero = "0"
    if type_c == "n":
        return _apply_n_comma(value, align, sign, alt, zero, width_s, "")
    return format(value, spec)


