import re


def locale_n(v):
    if isinstance(v, float):
        v = int(v)
    elif not isinstance(v, (int,)):
        v = int(v)
    s = str(v)
    if len(s) <= 3:
        return s
    body = s[:-3] + "," + s[-3:]
    while True:
        m = re.search(r'(\d)(\d{3})', body)
        if not m:
            break
        start = m.start()
        before = body[:start]
        rest = body[start:]
        new_rest = rest[:1] + ',' + rest[1:]
        body = before + new_rest
    return body


def _do_format(v, spec):
    # Replace 'n' with 'd' or 'f' appropriately
    t_match = re.search(r"[dxfXeEgG%cn]", spec)
    if not t_match or t_match.group(0) != "n":
        try:
            return format(v, spec)
        except Exception as e:
            return "ERR:" + type(e).__name__
    # It has 'n'
    if isinstance(v, bool) or isinstance(v, int):
        try:
            result = format(v, spec.replace("n", "d"))
            return locale_n(int(result))
        except Exception as e:
            pass
    try:
        result = format(v, spec.replace("n", "f"))
        return locale_n(float(result))
    except Exception:
        pass
    # Fallback: just try original
    try:
        return format(v, spec)
    except Exception as e:
        return "ERR:" + type(e).__name__


