def main():
    # Replicate git ls-files behavior by scanning all files in the current directory tree
    # that are likely tracked. Since we can't run git, we'll just scan all files.
    files = []

    for root, dirs, filenames in os.walk('.'):
        for fname in filenames:
            fpath = os.path.join(root, fname)
            if not os.path.isfile(fpath):
                continue
            # Skip hidden files and common directories
            # But to match git ls-files, we should include all regular files
            files.append(fpath)

    dec = b'Dale\xcc\x81n'      # decomposed: e + COMBINING ACUTE
    pre = b'Dal\xc3\xa9n'       # precomposed: e-acute
    plain = b'Dalen'
    hits={'decomposed':[], 'precomposed':[], 'plain':[]}

    for f in files:
        # Normalize path to match what git ls-files would output (relative paths without leading ./)
        rel_f = f
        if rel_f.startswith('./'):
            rel_f = rel_f[2:]

        if not rel_f or rel_f.startswith('public/introspect/'):
            continue

        try:
            with open(rel_f,'rb') as fh:
