        import types
        def _parse_json(s):
            i = 0; n = len(s)
            def skip():
                nonlocal i
                while i < n and s[i].isspace(): i += 1
            def value():
                nonlocal i
                skip()
                ch = s[i]
                if ch == '{': return obj()
                if ch == '[': return arr()
                if ch == '"': return string()
                if s.startswith('true', i): i += 4; return True
                if s.startswith('false', i): i += 5; return False
                if s.startswith('null', i): i += 4; return None
                return num()
            def string():
                nonlocal i
                assert s[i] == '"'
                i += 1
                out = []
                while s[i] != '"':
                    if s[i] == '\\':
                        nxt = s[i+1]
                        if nxt == 'n': out.append('\n'); i += 2
                        elif nxt == 't': out.append('\t'); i += 2
                        elif nxt == 'r': out.append('\r'); i += 2
                        elif nxt == 'b': out.append('\b'); i += 2
                        elif nxt == 'f': out.append('\f'); i += 2
                        elif nxt == '/': out.append('/'); i += 2
                        elif nxt == '\\': out.append('\\'); i += 2
                        elif nxt == '"': out.append('"'); i += 2
                        else:
                            # unicode escape
                            hexs = s[i+2:i+6]
                            cp = int(hexs, 16)
                            out.append(chr(cp)); i += 6
                    else:
                        out.append(s[i]); i += 1
                i += 1
                return ''.join(out)
            def num():
                nonlocal i
                j = i
                if s[j] == '-': j += 1
                while j < n and (s[j].isdigit() or s[j] == '.' or s[j] in 'eE+-'):
                    j += 1
                tok_ = s[i:j]; i = j
                if '.' in tok_ or 'e' in tok_ or 'E' in tok_:
                    return float(tok_)
                return int(tok_)
            def obj():
                nonlocal i
                assert s[i] == '{'; i += 1
                d = {}
                skip()
                if s[i] == '}':
                    i += 1
                    return d
                while True:
                    k = string()
                    skip()
                    assert s[i] == ':'
                    i += 1
                    v = value()
                    d[k] = v
                    skip()
                    if s[i] == ',':
                        i += 1; skip(); continue
                    else:
                        break
                assert s[i] == '}'
                i += 1
                return d
            def arr():
                nonlocal i
                assert s[i] == '['; i += 1
                a = []
                skip()
                if s[i] == ']':
                    i += 1
                    return a
                while True:
                    a.append(value())
                    skip()
                    if s[i] == ',':
                        i += 1; skip(); continue
                    else:
                        break
                assert s[i] == ']'
                i += 1
                return a
            return value()
        def _dumps(o, indent=1):
            sp = " " * indent
            def rec(x, cur):
                pad = sp * cur
                pad_in = sp * (cur + 1)
                if isinstance(x, dict):
                    if not x:
                        return "{}"
                    parts = ["{\n"]
                    items = list(x.items())
                    for idx, (k, v) in enumerate(items):
                        parts.append(pad_in + '"' + _esc(k) + '": ')
                        parts.append(rec(v, cur + 1))
                        if idx != len(items) - 1:
                            parts.append(",\n")
                    parts.append(pad + "}")
                    return "".join(parts)
                elif isinstance(x, list):
                    if not x:
                        return "[]"
                    parts = ["[\n"]
                    for idx, v in enumerate(x):
                        parts.append(pad_in)
                        parts.append(rec(v, cur + 1))
                        if idx != len(x) - 1:
                            parts.append(",\n")
                    parts.append(pad + "]")
                    return "".join(parts)
                elif isinstance(x, str):
                    return '"' + _esc(x) + '"'
                elif x is True:
                    return "true"
                elif x is False:
                    return "false"
                elif x is None:
                    return "null"
                elif isinstance(x, float):
                    # emulate python's repr of float as json
                    # For simple cases use repr
                    rr = repr(x)
                    return rr
                elif isinstance(x, int):
                    return str(x)
                else:
                    return str(x)
            def _esc(s):
                out = []
                for ch in s:
                    if ch == '"': out.append('\\"')
                    elif ch == '\\': out.append('\\\\')
                    elif ch == '\n': out.append('\\n')
                    elif ch == '\t': out.append('\\t')
                    elif ch == '\r': out.append('\\r')
                    elif ch == '\b': out.append('\\b')
                    elif ch == '\f': out.append('\\f')
                    else:
                        o_ = ord(ch)
                        if o_ < 0x20:
                            out.append('\\u' + format(o_, '04x'))
                        else:
                            out.append(ch)
                return ''.join(out)
            return rec(o, 0)
