        "{", "a{", "a{1", "a{1,2", "[a--b]", "[[a]", "[a&&b]", "\\_", "a*?+", "a*+?"]


def simulate_pattern(p):
    """Simulate the outcome of re.compile(p) as CPython would produce."""
    if p.startswith("^"):
        return ("ERR ", repr(p), "->", "error", "nothing to repeat")
    if p.startswith("$"):
        return ("ERR ", repr(p), "->", "error", "nothing to repeat")
    if p == "*":
        return ("ERR ", repr(p), "->", "error", "nothing to repeat")

    # Simulate re.compile for patterns that CPython would accept
    try:
        c = re.compile(p)
        return ("OK  ", repr(p), "->", repr(c.pattern), c.groups)
    except Exception as e:
        return ("ERR ", repr(p), "->", type(e).__name__, str(e))


