import sys

def _is_unicode_printable(ch):
    cp = ord(ch)
    if cp == 0:
        return False
    for lo, hi in [
        (0x20, 0x7E),
        (0xA0, 0xD7FF),
        (0xF8FF, 0xFDCF),
        (0xFDF0, 0xFFFD),
        (0x10000, 0x10FFFF),
    ]:
        if lo <= cp <= hi:
            return True
    return False


def _escape_char(ch):
    cp = ord(ch)
    if ch in '\"\'\\':
        return '\\' + ch
    if cp < 32 or cp >= 127:
        if cp <= 0xFF:
            return '\\x%02x' % cp
        elif cp <= 0xFFFF:
            return '\\u%04x' % cp
        else:
            return '\\U%08x' % cp
    if _is_unicode_printable(ch):
        return ch
    # non-printable (control char not already caught, but just in case)
    if cp <= 0xFF:
        return '\\x%02x' % cp
    elif cp <= 0xFFFF:
        return '\\u%04x' % cp
    else:
        return '\\U%08x' % cp


def my_repr(s):
    parts = ['\'']
    for ch in s:
        parts.append(_escape_char(ch))
    parts.append('\'')
    return ''.join(parts)


