import unicodedata

def _is_printable(c):
    # Mimic CPython: printable if cat != 'Cc' and cat != 'Cf'
    return unicodedata.category(c) not in ('Cc', 'Cf')


def safe_repr(s):
    out = []
    for c in s:
        if ord(c) >= 32 and ord(c) != 127 and _is_printable(c):
            out.append(repr(c))
        else:
            if c == '\n':
                out.append('\\n')
            elif c == '\t':
                out.append('\\t')
            elif c == '\r':
                out.append('\\r')
            elif c == '\0':
                out.append('\\x00')
            else:
                code = ord(c)
                if code <= 255:
                    out.append('\\x%02x' % code)
                else:
                    out.append('\\u%04x' % code)
    return ''.join(out)


def bytes_equiv_repr(b):
    out = []
    i = 0
    n = len(b)
    while i < n:
        byte = b[i] if isinstance(b[i], int) else ord(b[i])
        ch = chr(byte)
        if _is_printable(ch) and byte >= 32 and byte != 127:
            out.append(repr(ch))
        else:
            if ch == '\n':
                out.append('\\n')
            elif ch == '\t':
                out.append('\\t')
            elif ch == '\r':
                out.append('\\r')
            elif ch == '\0':
                out.append('\\x00')
            else:
                out.append('\\x%02x' % byte)
        i += 1
    return ''.join(out)


