def _r_repr(s):
    # Mirror CPython's str.__repr__ output, but avoid the built-in repr().
    if len(s) == 0:
        return "''"
    use_double = False
    has_single = False
    for ch in s:
        if ch == "'":
            has_single = True
        if ch == '"':
            use_double = True
    if use_double and not has_single:
        quote = '"'
    else:
        quote = "'"
    out_chars = [quote]
    for ch in s:
        cp = ord(ch)
        escaped = None
        if ch == '\n':
            escaped = '\\n'
        elif ch == '\t':
            escaped = '\\t'
        elif ch == '\r':
            escaped = '\\r'
        elif ch == '\x0b':
            escaped = '\\v'
        elif ch == '\x0c':
            escaped = '\\f'
        elif ch == '\\':
            escaped = '\\\\'
        elif ch == quote:
            if quote == '\'':
                escaped = "\\'"
            else:
                escaped = '\\"'
        elif cp < 0x20 or cp >= 0x7f:
            if cp <= 0xff:
                escaped = '\\x%02x' % cp
            else:
                escaped = '\\u%04x' % cp
        if escaped is not None:
            out_chars.append(escaped)
        else:
            out_chars.append(ch)
    out_chars.append(quote)
    return ''.join(out_chars)

def _fmt(v):
    if isinstance(v, str):
        return _r_repr(v)
    return repr(v)

