def pyrepr(s):
    # Build the repr of a str, mimicking Python's standard algorithm:
    # printable chars (isprintable()) shown as-is; non-printables as escape sequences.
    if s == '':
        return "''"
    quote = "'"
    out = []
    for ch in s:
        c = ord(ch)
        if c >= 0x20 and c < 0x7f and c != 0x27:
            out.append(ch)
        elif 0x80 <= c <= 0xd7ff and ch.isprintable():
            out.append(ch)
        else:
            # Escape sequence
            if c == 0x27:
                out.append("\\'")
            elif c == '\\':
                out.append('\\\\')
            elif c == '\n':
                out.append('\\n')
            elif c == '\t':
                out.append('\\t')
            elif c == '\r':
                out.append('\\r')
            elif c == '\b':
                out.append('\\b')
            elif c == '\f':
                out.append('\\f')
            elif c == '\v':
                out.append('\\v')
            elif c == '\x1b':
                out.append('\\x1b')
            elif 0x20 <= c < 0x7f:
                out.append('\\%03o' % c)
            elif c < 0x100:
                out.append('\\x%02x' % c)
            else:
                out.append('\\u%04x' % c)
    return quote + ''.join(out) + quote


for t in tests:
    # Compute t.split() and t.encode().split()
    split_str = t.split()
    bytes_obj = t.encode()
    split_bytes = bytes_obj.split()

    # Format the byte list like a Python bytes literal list
    if len(split_bytes) == 1:
        if len(split_bytes[0]) == 0:
            b_repr = "b''"
        else:
            b_items = []
            for byte in split_bytes[0]:
                b = byte
                if 0x20 <= b < 0x7f and b != 0x5c and b != 0x27:
                    b_items.append(chr(b))
                else:
                    b_items.append('\\x%02x' % b)
            b_repr = 'b"' + ''.join(b_items) + '"'
        result_b = '[' + b_repr + ']'
    else:
        parts = []
        for elem in split_bytes:
            if len(elem) == 0:
                parts.append("b''")
            else:
                b_items = []
                for byte in elem:
                    b = byte
                    if 0x20 <= b < 0x7f and b != 0x5c and b != 0x27:
                        b_items.append(chr(b))
                    else:
                        b_items.append('\\x%02x' % b)
                parts.append('b"' + ''.join(b_items) + '"')
        result_b = '[' + ', '.join(parts) + ']'

    # Format the string list like a Python list repr
    if len(split_str) == 1:
        s_repr = pyrepr(split_str[0])
        result_s = '[' + s_repr + ']'
    else:
        parts = []
        for elem in split_str:
            parts.append(pyrepr(elem))
        result_s = '[' + ', '.join(parts) + ']'

    line = '%-14r split -> %s   bytes-equiv %s' % (t, result_s, result_b)
    print(line)

