from dataclasses import dataclass
import sys

@dataclass
class CheckResult:
    ok: bool
    note: str = ""


def _size_check(name: str, size: int, target_triple=None) -> CheckResult:
    MAX_SIZE = 10 * 131072 + 4096  # 10 blocks of 128KB plus one extra page (approximate limit)

    if target_triple is not None and 'unknown-linux-musl' in target_triple:
        # Measured target: allow slightly larger due to measurement overhead
        LIMIT = 10 * 131072 + 4096
        if size > LIMIT:
            return CheckResult(False, "Size %d exceeds limit %d for measured target" % (size, LIMIT))
        elif size == 10 * 131072 + 1:
            return CheckResult(True, "")
        elif size <= 9 * 131072:
            return CheckResult(True, "")
        else:
            return CheckResult(True, "")
    else:
        # Unmeasured target: strict limit at exactly 10 blocks
        LIMIT = 10 * 131072
        if size > LIMIT:
            return CheckResult(False, "Size %d exceeds limit %d for unmeasured target" % (size, LIMIT))
        else:
            return CheckResult(True, "")


for label, size, tri in [
    ("10-block core, measured target", 10*131072 + 1, 'x86_64-unknown-linux-musl'),
    ("9-block core,  measured target",  9*131072,     'x86_64-unknown-linux-musl'),
    ("10-block core, UNmeasured target",10*131072 + 1, None)]:
    c = _size_check('lypning', size, tri)
    print("%-34s -> %s" % (label, "FAIL" if not c.ok else "ok"))
    print("      %s" % (c.note or "")[:88])

import sys

def _try_int(s):
    try:
        return int(s)
    except Exception:
        raise ValueError("bad number")

expressions = ["(5).to_bytes(-1,'middle')", "(5).to_bytes(-1,2)", "(5).to_bytes(2,'middle')", "(300).to_bytes(-1,2)"]

for expr in expressions:
    try:
        s = expr
        # strip leading (
        if not s.startswith("("):
            raise ValueError
        s2 = s[1:]
        if not s2.endswith(")"):
            raise ValueError
        # find matching close for the first open
        depth = 0
        idx_close = -1
        in_str = False
        for i, ch in enumerate(s2):
            if in_str:
                if ch == "'":
                    in_str = False
                continue
            if ch == "'":
                in_str = True
            elif ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    idx_close = i
                    break
        if idx_close == -1:
            raise ValueError
        inner_num = s2[:idx_close]
        rest = s2[idx_close + 1:]
        # rest should be ".to_bytes(args)" or similar
        if not rest.startswith(".to_bytes("):
            raise ValueError
        args_str = rest[len(".to_bytes("):]
        if not args_str.endswith(")"):
            raise ValueError
        args_str = args_str[:-1]
        # split by top-level commas
        parts = []
        cur = ""
        depth = 0
        in_str = False
        for ch in args_str:
            if in_str:
                cur += ch
                if ch == "'":
                    in_str = False
                continue
            if ch == "'":
                in_str = True
                cur += ch
            elif ch == ",":
                parts.append(cur.strip())
                cur = ""
            else:
                cur += ch
        if cur.strip():
            parts.append(cur.strip())
        # parse each arg
        parsed = []
        for p in parts:
            if len(p) >= 2 and p.startswith("'") and p.endswith("'"):
                parsed.append(p[1:-1])
            else:
                # integer
                pstrip = p
                neg = False
                if pstrip.startswith("-"):
                    neg = True
                    pstrip = pstrip[1:]
                if not pstrip.isdigit():
                    raise ValueError
                val = int(pstrip)
                if neg:
                    val = -val
                parsed.append(val)
        num_val = _try_int(inner_num)
        result = num_val.to_bytes(*parsed)
        print('  %-32s -> %r' % (expr, result))
