def parse(expr):
    if not (expr.startswith('(') and expr.endswith(')')):
        raise SyntaxError("unsupported expression: %s" % expr)
    inner = expr[1:-1]
    i = 0
    while i < len(inner) and inner[i].isdigit():
        i += 1
    num_str = inner[:i]
    if num_str == "":
        raise SyntaxError("no integer found")
    num = int(num_str)
    rest = inner[i:]
    m = re.match(r"\.to_bytes\((.+)\)$", rest)
    if not m:
        raise SyntaxError("expected .to_bytes(...) call, got: %r" % rest)
    argstr = m.group(1)
    parts = [p.strip() for p in argstr.split(',')]
    args = []
    for p in parts:
        if (p.startswith("'") and p.endswith("'")) or (p.startswith('"') and p.endswith('"')):
            q = p[1:-1]
        else:
            q = int(p)
        args.append(q)
    return num, args


