def eval_node(n):
    if isinstance(n, ast.Expression): return eval_node(n.body)
    if isinstance(n, ast.Constant): return n.value
    if isinstance(n, ast.Num): return n.n
    if isinstance(n, ast.Str): return n.s
    if isinstance(n, ast.NameConstant): return n.value
    if isinstance(n, ast.Call):
        f = eval_node(n.func); args = [eval_node(a) for a in n.args]
        return f(*args)
    if isinstance(n, ast.Attribute):
        base = eval_node(n.value)
        return getattr(base, n.attr)
    raise TypeError('unsupported node: %r' % type(n).__name__)

