import sys

def safe_eval(expr):
    # Parse with ast and evaluate only a small subset
    import ast
    node = ast.parse(expr, mode='eval')

    def eval_node(n):
        if isinstance(n, ast.Expression):
            return eval_node(n.body)
        elif isinstance(n, ast.Call):
            func = eval_node(n.func)
            args = [eval_node(a) for a in n.args]
            kws = [(kw.arg, eval_node(kw.value)) for kw in n.keywords]
            kwargs = dict(kws)
            try:
                return func(*args, **kwargs)
            except TypeError as e:
                # Re-raise similar error
                raise
        elif isinstance(n, ast.Name):
            # Builtins lookup
            if n.id == 'min':
                return min
            elif n.id == 'max':
                return max
            elif n.id == 'str':
                return str
            elif n.id == 'int':
                return int
            else:
                raise NameError(name=n.id)
        elif isinstance(n, ast.List):
            return [eval_node(e) for e in n.elts]
        elif isinstance(n, ast.Constant):
            return n.value
        else:
            raise NotImplementedError(str(type(n)))

    return eval_node(node)

