import os

# Compute the same thing as pathlib.Path("src/lypning/assets").glob("*.jsonl")
# This matches files ending in .jsonl, not starting with '.', and that exist directly
# under the directory. We need to reproduce byte-identical output from the original:
# print(list(p.glob("*.jsonl")))  -> prints a list of PosixPath objects

base = "src/lypning/assets"

def glob_jsonl(base_dir):
    # Mimic pathlib glob "*.jsonl"
    # Pattern *.jsonl: any name ending in .jsonl, but the first char cannot be '.'
    results = []
    try:
        entries = os.listdir(base_dir)
    except OSError:
        return []
    for name in entries:
        if name.startswith('.'):
            continue
        if name.endswith(".jsonl"):
            full = base_dir + "/" + name if base_dir != "." else name
            if os.path.isfile(full) or os.path.isdir(full) or os.path.islink(full):
                # pathlib's glob yields Path objects; let's check what p.glob returns
                # pathlib.Path.glob returns an iterator of Path objects matching
                # We should include only existing paths (is_file or is_dir etc.)
                # Actually pathlib glob includes directories too potentially, but
                # for a file-like pattern it typically filters. To be safe, we
                # replicate: any entry matching pattern that exists.
                results.append(full)
