def match_char_class(pattern, text):
    """Manually implement [a&&b], [a||b], [a~~b], [[a]], [+--], [!--], [a--b], [[:alpha:]], [\w&&\d]"""
    results = []
    for ch in text:
        if pattern == '[a&&b]':
            # intersection of a and b - neither 'a' nor 'b' is both, so empty
            if False:
                results.append(ch)
        elif pattern == '[a||b]':
            # union of a or b
            if ch == 'a' or ch == 'b':
                results.append(ch)
        elif pattern == '[a~~b]':
            # symmetric difference: a or b but not both (since single chars, same as union)
            if ch == 'a' or ch == 'b':
                results.append(ch)
        elif pattern == '[[a]]':
            # literal [a] - matches '['
            if ch == '[':
                results.append(ch)
        elif pattern == '[+--]':
            # This would be + minus minus-minus... likely invalid or complex
            # CPython probably rejects this
            pass
        elif pattern == '[!--]':
            # ! minus minus-minus... likely invalid
            pass
        elif pattern == '[a--b]':
            # a minus (minus to b)... This is the problematic one that CPython rejects
            # We need to handle it differently - CPython says "bad character range"
            # So this should raise an error like CPython would
            raise ValueError("bad character range")
        elif pattern == '[[:alpha:]]':
            # POSIX alpha class
            if ch.isalpha():
                results.append(ch)
        elif pattern == '[\\w&&\\d]':
            # word characters AND digits = just digits
            if ch.isdigit():
                results.append(ch)
        else:
            pass
    return results

