def _parse_char_class(body):
    s = list(body)
    n = len(s)
    i = 0
    # check POSIX classes
    m = re_like_posix(body)
    if m is not None:
        return m
    result = []
    while i < n:
        c = s[i]
        if c == '\\' and i + 1 < n:
            nc = s[i+1]
            if nc == 'w':
                result.extend([ch for ch in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'])
            elif nc == 'd':
                result.extend('0123456789')
            else:
                result.append(nc)
            i += 2
        else:
            if (c == '-' or c == '+') and i + 1 < n and s[i+1] == '-':
                # handle -- range
                start = ord(c)
                end_i = i + 2
                if end_i < n and s[end_i] != ']':
                    end = ord(s[end_i])
                    for k in range(start, end+1):
                        result.append(chr(k))
                    i = end_i + 1
                else:
                    result.append('-')
                    i += 1
            elif i + 1 < n and s[i+1] == '-':
                if i + 2 < n and s[i+2] != ']':
                    start = ord(c)
                    end = ord(s[i+2])
                    if start <= end:
                        for k in range(start, end+1):
                            result.append(chr(k))
                    i += 3
                else:
                    result.append(c)
                    i += 1
            else:
                result.append(c)
                i += 1
    return sorted(set(result))

