import os

def _find_tmpdir():
    env = os.environ
    for var in ("TMPDIR", "TEMP", "TMP"):
        v = env.get(var)
        if v and os.path.isdir(v):
            return v
    return "/tmp"


def _is_dir(p):
    try:
        return os.path.isdir(p)
    except OSError:
        return False


def _unique_path(base, stem):
    suffix = ".txt"
    i = 0
    while True:
        candidate = os.path.join(base, stem + str(i) + suffix)
        try:
            fd = os.open(candidate, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o644)
            with os.fdopen(fd, "w") as f:
                f.write("scratch")
            return candidate
        except FileExistsError:
            i += 1
        except FileNotFoundError:
            # base doesn't exist; caller should handle or we fall back
            raise


