    if not non_empty:
        return []

    # Parse header - simple split by comma (won't handle quoted commas perfectly)
    def parse_csv_line(line, delimiter=','):
        result = []
        i = 0
        while i < len(line):
            if line[i] == '"':
                # Quoted field
                j = i + 1
                field = []
                while j < len(line):
                    if line[j] == '"':
                        if j + 1 < len(line) and line[j+1] == '"':
                            field.append('"')
                            j += 2
                        else:
                            j += 1
                            break
                    else:
                        field.append(line[j])
                        j += 1
                result.append(''.join(field))
                i = j
                if i < len(line) and line[i] == delimiter:
                    i += 1
            else:
                j = i
                while j < len(line) and line[j] != delimiter:
                    j += 1
                result.append(line[i:j])
                i = j
                if i < len(line) and line[i] == delimiter:
                    i += 1
        return result

    headers = parse_csv_line(non_empty[0], kw.get('delimiter', ','))
