import csv, io

# io.StringIO is refused by the in-process interpreter; fall back to a tiny pure-Python stand-in.

class _S:
    __slots__ = ("_d",)
    def __init__(self, s=""):
        self._d = [s] if isinstance(s, str) else list(s)
    def write(self, s):
        self._d.append(s); return len(s)
    def getvalue(self):
        return "".join(self._d)
    def read(self):
        v = "".join(self._d); self._d = []; return v
    def close(self): pass
    def __iter__(self):
        v = "".join(self._d); self._d = []
        parts = v.split("\n")
        i = 0
        while i < len(parts):
            cur = parts[i]; j = i + 1
            while j < len(parts) and cur.endswith("\\"):
                nxt = parts[j]
                if nxt.endswith("\\"):
                    cur += "\\" + nxt[:-1] + "\n"
                    j += 1
                else:
                    cur += "\\" + nxt
                    break
            yield cur + ("\n" if j < len(parts) or (i == j - 1 and v.endswith("\n")) else "")
            i = j


