import csv

# Helper: read all bytes from a file-like object (with optional newline handling)
def _readall(f):
    data = f.read()
    if not hasattr(data, 'encode'):
        # if it's already str, keep as is? Actually csv module works with str in py3.
        return data
    return data

def _make_str_io(content):
    class S:
        def __init__(self, s):
            self._s = s
            self._i = 0
        def read(self, size=-1):
            if size is None or size < 0:
                r = self._s[self._i:]
                self._i = len(self._s)
                return r
            else:
                r = self._s[self._i:self._i+size]
                self._i += len(r)
                return r
        def readline(self, size=-1):
            start = self._i
            i = start
            n = len(self._s)
            while i < n and self._s[i] != '\n':
                i += 1
            end = i + 1 if i < n else n
            if size >= 0 and size < (end - start):
                end = start + size
            line = self._s[start:end]
            self._i = end
            return line
        def seekable(self):
            return True
        def seek(self, offset, whence=0):
            if whence == 0:
                self._i = offset
            elif whence == 1:
                self._i += offset
            elif whence == 2:
                self._i = len(self._s) + offset
            return self._i
        def tell(self):
            return self._i
        def readable(self):
            return True
        def writable(self):
            return False
        def peek(self, size=-1):
            return self._s[self._i:]
    return S(content)

