import csv, sys

def _sio(text):
    # Replace io.StringIO with an in-memory string reader compatible with csv.reader
    class SIO:
        def __init__(self, text):
            self.text = text
            self.pos = 0
        def read(self, size=None):
            if size is None:
                r = self.text[self.pos:]
                self.pos = len(self.text)
                return r
            else:
                r = self.text[self.pos:self.pos + size]
                self.pos += len(r)
                return r
        def readline(self, size=None):
            start = self.pos
            nl = self.text.find('\n', start)
            if nl == -1:
                line = self.text[start:]
                self.pos = len(self.text)
                return line
            else:
                end = nl + 1
                if size is not None and (end - start) > size:
                    end = start + size
                line = self.text[start:end]
                self.pos = end
                return line
    return SIO(text)

def W(row, **kw):
    o = _sio("")
    o._writerow_result = None
    # We need to capture what writerow writes. The csv.writer writes to the file object.
    # We'll use a temporary StringIO-like object that just accumulates.
    class Buf:
        def __init__(self):
            self.buf = []
        def write(self, s):
            self.buf.append(s)
            return len(s)
        def getvalue(self):
            return "".join(self.buf)
    b = Buf()
    w = csv.writer(b, **kw)
    r = w.writerow(row)
    return (b.getvalue(), r)

