    lineterminator = kw.get('lineterminator', '\r\n')
    skipinitialspace = kw.get('skipinitialspace', False)
    doublequote = kw.get('doublequote', True)

    # Handle row=None edge case (csv.writer handles it by returning empty for None values)
    fields = []
    if row is not None:
        for field in row:
            s = str(field)

            needs_quote = False

            if doublequote:
                if quotechar in s:
                    needs_quote = True

            if quoting == csv.QUOTE_NONNUMERIC:
                try:
                    float(s)
                    if s != '':  # empty string should be quoted in QUOTE_NONNUMERIC? Let me check
                        pass
                    else:
                        needs_quote = True
                except ValueError:
                    pass
            elif quoting == csv.QUOTE_ALL:
                needs_quote = True
            elif quoting == csv.QUOTE_NONE:
                if delimiter in s or quotechar in s or any(c in lineterminator for c in s):
                    raise csv.Error('need to escape, but no escapechar set')

            if not needs_quote:
                # Check MINIMAL quoting conditions
                if quoting in (csv.QUOTE_MINIMAL, csv.QUOTE_NONNUMERIC):
                    if delimiter in s:
                        needs_quote = True
                    if quotechar in s:
                        needs_quote = True
                    if '\r' in s:
                        needs_quote = True
                    if '\n' in s:
                        needs_quote = True

            if needs_quote:
                if doublequote:
                    if quotechar in s:
                        s = s.replace(quotechar, quotechar * 2)
                    s = quotechar + s + quotechar
                else:
                    s = quotechar + s + quotechar
            elif skipinitialspace and s.startswith(' '):
                pass  # skipinitialspace only affects reading

            fields.append(s)

    return (delimiter.join(fields) + lineterminator, len(fields))


