def csv_reader(data):
    """Parse CSV data string, handling quoted fields and embedded newlines."""
    if not data:
        return []

    rows = []
    i = 0
    n = len(data)

    while i < n:
        # Check for empty line
        if i < n and data[i] == '\n':
            rows.append([])
            i += 1
            continue
        if i < n and data[i] == '\r' and i+1 < n and data[i+1] == '\n':
            rows.append([])
            i += 2
            continue
        if i < n and data[i] == '\r':
            rows.append([])
            i += 1
            continue

        row = []
        while True:
            # Parse next field
            if i >= n:
                break

            if data[i] == quotechar_global():
                # Quoted field
                i += 1
                field = []
                while i < n:
                    if data[i] == quotechar_global():
                        if i+1 < n and data[i+1] == quotechar_global():
                            field.append(quotechar_global())
                            i += 2
                        else:
                            i += 1
                            break
                    else:
                        field.append(data[i])
                        i += 1

                row.append(''.join(field))

                # After closing quote, expect delimiter or end of record
                if i < n:
                    if data[i] == delimiter_global():
                        i += 1
                        continue
                    elif data[i] == '\n':
                        i += 1
                        break
                    elif data[i] == '\r':
                        if i+1 < n and data[i+1] == '\n':
                            i += 2
                        else:
                            i += 1
                        break
                    else:
                        # Malformed - include rest as part of this field? 
                        # For now, treat as end of record with extra chars
                        break
                else:
                    break
            else:
                # Unquoted field
                field = []
                while i < n:
                    if data[i] == delimiter_global():
                        i += 1
                        break
                    elif data[i] == '\n':
                        i += 1
                        break
                    elif data[i] == '\r':
                        if i+1 < n and data[i+1] == '\n':
                            i += 2
                        else:
                            i += 1
                        break
                    else:
                        field.append(data[i])
                        i += 1
                row.append(''.join(field))

        rows.append(row)

    return rows

def quotechar_global():
    return '"'

def delimiter_global():
    return ','

