def _wrow(csvmod, row, **kw):
    class S:
        def __init__(self):
            self.b = b''
        def write(self, s):
            if isinstance(s, str):
                s = s.encode('utf-8')
            self.b += s
            return len(s)
    buf = S()
    w = csvmod.writer(buf, **kw)
    r = w.writerow(row)
    return (buf.b.decode('utf-8'), r)

