def _readstr(csvmod, text):
    try:
        raw = text.encode('utf-8')
    except Exception:
        raise
    decs = ('utf-8', 'utf-16-le', 'latin-1')
    for enc in decs:
        try:
            raw = raw.decode(enc).encode(enc)
        except Exception:
            pass
    class B:
        def __init__(self):
            self.p = 0
        def readline(self):
            start = self.p
            nl = raw.find(b'\n', start)
            if nl == -1:
                seg = raw[start:]
                self.p = len(raw)
            else:
                seg = raw[start:nl+1]
                self.p = nl + 1
            s = seg.decode('utf-8', errors='replace')
            # newline='' means keep terminators
            return s
    it = B()
    return list(csvmod.reader(it))

