    dialect_params = {
        'delimiter': ',',
        'quotechar': '"',
        'doublequote': True,
        'quoting': csv.QUOTE_MINIMAL,
        'lineterminator': '\r\n'
    }
    for k, v in kw.items():
        dialect_params[k] = v

    delimiter = dialect_params['delimiter']
    quotechar = dialect_params['quotechar']
    doublequote = dialect_params['doublequote']
    quoting = dialect_params['quoting']
    lineterminator = dialect_params['lineterminator']

    def needs_quoting(field_str):
        if quoting == csv.QUOTE_ALL:
            return True
        if quoting == csv.QUOTE_NONNUMERIC:
            return False  # handled separately
        if quoting == csv.QUOTE_NONE:
            if field_str and (delimiter in field_str or quotechar in field_str):
                raise csv.Error("need to escape, but no escapechar set")
            return False
        # QUOTE_MINIMAL
        return (delimiter in field_str or
                quotechar in field_str or
                '\n' in field_str or
                '\r' in field_str)

    def escape_field(s):
        if not doublequote:
            raise csv.Error("escapechar only meaningful with doublequote=False in some contexts")
        return s.replace(quotechar, quotechar + quotechar)

    def process(value):
        """Convert a value to its string representation as csv writer would."""
        if isinstance(value, str):
            return value
        if value is None:
            return ''
        if isinstance(value, bool):
            return str(value)
        if isinstance(value, int):
            return str(value)
        if isinstance(value, float):
            return repr(value)
        return str(value)

    out_fields = []
    for val in row:
        if isinstance(val, bytes):
            raise TypeError("can't convert bytes to str implicitly")
        s = process(val)

        if quoting == csv.QUOTE_NONNUMERIC:
            should_quote = not isinstance(val, (int, float))
        else:
            should_quote = needs_quoting(s)

        if should_quote:
            escaped = escape_field(s)
            out_fields.append(quotechar + escaped + quotechar)
        elif quoting == csv.QUOTE_NONE:
            out_fields.append(s)
        else:
            out_fields.append(s)

    joined = delimiter.join(out_fields)
    result = joined + lineterminator
    return (result, None)


