# For the reader part, we need StringIO-like behavior. 
# The original uses csv.reader(io.StringIO(c, newline='')).
# We can create a simple file-like object manually.
class MyStringIO:
    def __init__(self, text, newline=None):
        self._text = text
        self._pos = 0
    def read(self, size=-1):
        if size == -1 or size is None:
            s = self._text[self._pos:]
            self._pos = len(self._text)
            return s
        end = min(self._pos + size, len(self._text))
        s = self._text[self._pos:end]
        self._pos = end
        return s
    def readline(self, size=-1):
        start = self._pos
        found_newline = -1
        i = start
        while i < len(self._text):
            ch = self._text[i]
            if ch == '\n':
                found_newline = i
                break
            i += 1
        if found_newline != -1:
            end = found_newline + 1
        else:
            end = len(self._text)
        if size != -1 and size is not None:
            if end - start > size:
                end = start + size
        s = self._text[start:end]
        self._pos = end
        return s
    def seekable(self):
        return True
    def seek(self, offset, whence=0):
        if whence == 0:
            new_pos = offset
        elif whence == 1:
            new_pos = self._pos + offset
        elif whence == 2:
            new_pos = len(self._text) + offset
        else:
            raise ValueError("invalid whence")
        if new_pos < 0:
            raise OSError("negative seek position")
        self._pos = min(new_pos, len(self._text))
        return self._pos
    def tell(self):
        return self._pos
    def close(self):
        pass

