class _Reader:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.len = len(text)
    def __iter__(self):
        return self
    def __next__(self):
        if self.pos >= self.len:
            raise StopIteration
        start = self.pos
        idx = self.text.find('\n', self.pos)
        if idx == -1:
            line = self.text[self.pos:]
            self.pos = self.len
        else:
            line = self.text[self.pos:idx+1]
            self.pos = idx + 1
        return line

