import csv, sys

def W(row, **kw):
    buf = []
    for i, field in enumerate(row):
        if i > 0:
            buf.append(',' if 'delimiter' not in kw else kw['delimiter'])
        if isinstance(field, str) and '"' in field:
            buf.append('"' + field.replace('"','""') + '"')
        else:
            fstr = "" if field is None else str(field)
            lineterm = kw.get('lineterminator', '\r\n')
            delim = ',' if 'delimiter' not in kw else kw['delimiter']
            quote = kw.get('quoting', csv.QUOTE_MINIMAL)
            need_quote = False
            if quote == csv.QUOTE_ALL:
                need_quote = True
            elif (isinstance(field, str) or field is None) and (delim in fstr or lineterm in fstr or '"' in fstr):
                need_quote = True
            if need_quote:
                buf.append('"' + fstr.replace('"','""') + '"')
            else:
                buf.append(fstr)
    buf.append(kw.get('lineterminator', '\r\n'))
    return ''.join(buf), 1

