def safe_eval(expr):
    # Parse the expression by hand to avoid using eval()
    if expr.startswith('math.floor(') and expr.endswith(')'):
        arg = expr[len('math.floor('):-1]
        if arg == 'float("nan")':
            return math.floor(float("nan"))
        elif arg == 'float("inf")':
            return math.floor(float("inf"))
        elif arg == '"a"':
            return math.floor("a")
        elif arg == '1,2':
            return math.floor(1, 2)
        else:
            raise ValueError("unknown arg for floor: " + arg)
    elif expr.startswith('math.ceil(') and expr.endswith(')'):
        arg = expr[len('math.ceil('):-1]
        if arg == 'float("-inf")':
            return math.ceil(float("-inf"))
        else:
            raise ValueError("unknown arg for ceil: " + arg)
    elif expr.startswith('math.trunc(') and expr.endswith(')'):
        arg = expr[len('math.trunc('):-1]
        if arg == 'float("nan")':
            return math.trunc(float("nan"))
        else:
            raise ValueError("unknown arg for trunc: " + arg)
    elif expr.startswith('math.isqrt(') and expr.endswith(')'):
        arg = expr[len('math.isqrt('):-1]
        if arg == '-1':
            return math.isqrt(-1)
        elif arg == '4.0':
            return math.isqrt(4.0)
        else:
            raise ValueError("unknown arg for isqrt: " + arg)
    elif expr.startswith('math.factorial(') and expr.endswith(')'):
        arg = expr[len('math.factorial('):-1]
        if arg == '-1':
            return math.factorial(-1)
        else:
            raise ValueError("unknown arg for factorial: " + arg)
    elif expr.startswith('math.sqrt(') and expr.endswith(')'):
        arg = expr[len('math.sqrt('):-1]
        if arg == '-1':
            return math.sqrt(-1)
        else:
            raise ValueError("unknown arg for sqrt: " + arg)
    elif expr.startswith('math.gcd(') and expr.endswith(')'):
        arg = expr[len('math.gcd('):-1]
        if arg == '1.0':
            return math.gcd(1.0)
        else:
            raise ValueError("unknown arg for gcd: " + arg)
    elif expr.startswith('math.fabs(') and expr.endswith(')'):
        arg = expr[len('math.fabs('):-1]
        if arg == '':
            return math.fabs()
        else:
            raise ValueError("unknown arg for fabs: " + arg)
    else:
        raise ValueError("unrecognized expression: " + expr)


