def safe_eval(expr):
    # Parse a simple expression of the form:
    #   <name>.<attr>(arg1, arg2, ...)  or  name.attr
    # We'll parse manually since the expressions are known/simple.
    # General approach: use ast? ast is stdlib and allowed (imports beyond os/sys are allowed per contract).
    import ast
    tree = ast.parse(expr, mode='eval')

    def evaluate(node):
        if isinstance(node, ast.Expression):
            return evaluate(node.body)
        elif isinstance(node, ast.Call):
            func = evaluate(node.func)
            args = [evaluate(a) for a in node.args]
            keywords = {k.arg: evaluate(k.value) for k in node.keywords}
            return func(*args, **keywords)
        elif isinstance(node, ast.Attribute):
            obj = evaluate(node.value)
            attr = node.attr
            if hasattr(obj, attr):
                # Use getattr via direct attribute access isn't allowed? getattr is builtin... 
                # Actually the refusal was for `eval`, not `getattr`. But let's be careful.
                # The worked example showed getattr was refused too. Let me re-read.
                # "The following Python program is correct, but this runtime refuses it" - the reason given is eval only.
                # But the worked example shows getattr is also unsupported.
                # So I should avoid getattr as well.
                # How to access an attribute without getattr or hasattr?
                # I can't do dynamic attribute access easily without getattr.
                # Alternative: pre-resolve all functions at module level.
                raise RuntimeError("attribute access needed dynamically")
            else:
                raise AttributeError(f"'{type(obj)}' has no attribute '{attr}'")
        elif isinstance(node, ast.Name):
            name = node.id
            if name in names:
                return names[name]
            elif name in ('True', 'False', 'None'):
                if name == 'True': return True
                elif name == 'False': return False
                else: return None
            else:
                raise NameError(f"name '{name}' is not defined")
        elif isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.USub):
                return -evaluate(node.operand)
            elif isinstance(node.op, ast.UAdd):
                return +evaluate(node.operand)
            elif isinstance(node.op, ast.Not):
                return not evaluate(node.operand)
            else:
                raise TypeError(f"unsupported unary op {type(node.op).__name__}")
        elif isinstance(node, ast.BinOp):
            left = evaluate(node.left)
            right = evaluate(node.right)
            if isinstance(node.op, ast.Add): return left + right
            elif isinstance(node.op, ast.Sub): return left - right
            elif isinstance(node.op, ast.Mult): return left * right
            elif isinstance(node.op, ast.Div): return left / right
            elif isinstance(node.op, ast.FloorDiv): return left // right
            elif isinstance(node.op, ast.Mod): return left % right
            elif isinstance(node.op, ast.Pow): return left ** right
            else:
                raise TypeError(f"unsupported binary op {type(node.op).__name__}")
        elif isinstance(node, ast.Tuple):
            return tuple(evaluate(e) for e in node.elts)
        elif isinstance(node, ast.List):
            return [evaluate(e) for e in node.elts]
        else:
            raise TypeError(f"unsupported AST node type: {type(node).__name__}")

    return evaluate(tree)

