    if self.prefix_chars and option_string[0] in self.prefix_chars:
        if len(option_string) == 2 and self.allow_abbrev:
            chars = option_string[0] + option_string[1]
            options = self._option_strings_map.get(chars, [])
            for option in options:
                action = self._option_string_actions.get(option)
                if action is not None:
                    result.append((option, action))
