def a2b_base64(s):
    # Emulate binascii.a2b_base64
    if not isinstance(s, (bytes, bytearray)):
        raise TypeError("a bytes-like object is required, not '%s'" % type(s).__name__)
    s = bytes(s)
    n = len(s)
    # Strip whitespace
    cleaned = []
    for c in s:
        if c not in b' \t\n\r\f\v':
            cleaned.append(c)
    # If there is a padding position before the end of input with more than 2 non-padding chars after, error.
    # We need to be precise about what constitutes an error.
    # Let's follow the CPython logic for base64 decoding.
    # The algorithm processes data 4 characters at a time.
    # It keeps track of state: number of bits accumulated in a buffer.
    # Characters must be valid base64 or '=' padding.
    # '=' can only appear as the last 1 or 2 characters of the entire input, and only after all data.

    buf = 0
    nbits = 0
    out = bytearray()
    eq_pos = -1  # index of first '=' in cleaned; -1 if none

    # Check validity constraints:
    # 1. No character after padding.
    # 2. Padding can only be 1 or 2 characters at the end.
    # Actually, let's just iterate and validate.

    i = 0
    L = len(cleaned)
    # Find first '='
    # In base64, once we see '=', everything after must also be '='.
    seen_pad = False
    for j in range(L):
        c = cleaned[j]
        if c == ord('='):
            if not seen_pad:
                seen_pad = True
                # All remaining must be '='
                for k in range(j+1, L):
                    if cleaned[k] != ord('='):
                        raise ValueError("Invalid base64 string")
        else:
            if seen_pad:
                raise ValueError("Invalid base64 string")

    if seen_pad:
        pad_count = L - (i)  # wait, let's find actual count
        # Count trailing '='
        p = L - 1
        while p >= 0 and cleaned[p] == ord('='):
            p -= 1
        pad_count = L - (p + 1)
        data_len = p + 1
        # Valid pad counts are 1 or 2. Also, total length including pads should be multiple of 4? 
        # Not necessarily strict multiple in some implementations, but standard says yes.
        # binascii.a2b_base64 raises "Invalid base64-encoded string" for various malformations.
        if pad_count > 2:
            raise ValueError("Invalid base64 string")
        if pad_count == 2:
            # Must have at least 2 data chars
            if data_len < 2:
                raise ValueError("Invalid base64 string")
        if pad_count == 1:
            if data_len < 3:
                raise ValueError("Invalid base64 string")
    else:
        data_len = L

    # Now decode
    buf = 0
    nbits = 0
    for j in range(data_len):
        c = cleaned[j]
        # Decode char to 6-bit value
        if ord('A') <= c <= ord('Z'):
            v = c - ord('A')
        elif ord('a') <= c <= ord('z'):
            v = c - ord('a') + 26
        elif ord('0') <= c <= ord('9'):
            v = c - ord('0') + 52
        elif c == ord('+'):
            v = 62
        elif c == ord('/'):
            v = 63
        else:
            raise ValueError("Invalid base64 character")
        buf = (buf << 6) | v
        nbits += 6
        if nbits >= 8:
            nbits -= 8
            out.append((buf >> nbits) & 0xFF)
    return bytes(out)

