def base64_decode(s):
    if not isinstance(s, (bytes, bytearray)):
        raise TypeError("a bytes-like object is required")
    # Strip whitespace
    filtered = bytearray()
    for c in s:
        if c == 32 or c == 9 or c == 10 or c == 13:
            continue
        filtered.append(c)
    data = bytes(filtered)
    n = len(data)
    if n % 4 != 0:
        raise binascii.Error("Invalid base64-encoded string: number of data characters ({}?) cannot be 1 more than a multiple of 4".format(n)) if False else Exception("Invalid base64-encoded string: number of data characters ({}) cannot be 1 more than a multiple of 4".format(n))

    # Check padding: only trailing '=' allowed, and at most 2
    non_pad_positions = [i for i, c in enumerate(data) if c != 61]
    last_non_pad = max(non_pad_positions) if non_pad_positions else -1
    padding_count = 0
    for i in range(last_non_pad + 1, n):
        if data[i] == 61:
            padding_count += 1
        else:
            raise Exception("Invalid base64-encoded string: number of data characters ({}) cannot be 1 more than a multiple of 4".format(n))
    if padding_count > 2:
        raise Exception("Invalid base64-encoded string: number of data characters ({}) cannot be 1 more than a multiple of 4".format(n))

    # Validate all non-padding characters are in base64 alphabet
    lookup = {}
    for i, ch in enumerate(B64_ALPHABET):
        lookup[ch] = i

    decoded = []
    bits = 0
    bitcount = 0
    for c in data:
        if c == 61:
            break
        if c not in lookup:
            raise Exception("Non-base64 digit found")
        bits = (bits << 6) | lookup[c]
        bitcount += 6
        if bitcount >= 8:
            bitcount -= 8
            val = (bits >> bitcount) & 0xFF
            decoded.append(val)

    # Determine expected output length based on padding
    # If padding_count == 0, no extra constraint (full bytes)
    # If padding_count == 1, last char had 2 bits padding, so total bits must be multiple of 8 after removing those
    # Actually, let's handle this differently. The standard behavior:
    # 4 chars -> 3 bytes (if no padding), 2 bytes (if 1 pad), 1 byte (if 2 pads)
    # For each group of 4:
    result = []
    i = 0
    while i < n:
        if i + 4 > n:
            break
        block = data[i:i+4]
        vals = []
        for c in block:
            if c == 61:
                vals.append(0)
            else:
                vals.append(lookup[c])

        combined = (vals[0] << 18) | (vals[1] << 12) | (vals[2] << 6) | vals[3]
        b0 = (combined >> 16) & 0xFF
        b1 = (combined >> 8) & 0xFF
        b2 = combined & 0xFF

        pad = 0
        if block[2] == 61:
            pad = 2
            result.append(b0)
        elif block[3] == 61:
            pad = 1
            result.append(b0)
            result.append(b1)
        else:
            result.extend([b0, b1, b2])
        i += 4

    return bytes(result)

