    if tail_eq > 2:
        raise binascii_Error()

    # Ensure all equals are contiguous at the end and there are no other equals.
    body_len = n - tail_eq
    for i in range(body_len):
        if chars[i][1] == '=':
            raise binascii_Error()

    body_chars = [ch for (_, ch) in chars[:body_len]]

    # Body length must be a multiple of 4 after padding? In strict decoding we require
    # the total (with equals) to be a multiple of 4. Since we stripped whitespace only,
    # count original effective length including equals.
    if n % 4 != 0:
        raise binascii_Error()

    # Decode 4-char groups producing 3 bytes each, with padding handling.
    out = bytearray()
    for start in range(0, n, 4):
        group = chars[start:start+4]
        vals = []
        eqs_in_group = 0
        for (_, ch) in group:
            if ch == '=':
                vals.append(-1)
                eqs_in_group += 1
            else:
                vals.append(_b64_val(ch))

        # Equals can only appear at positions 2 or 3 (i.e., last one or two), and only in final group
        # For simplicity, validate: no '=', '==' allowed in first two slots; '===' invalid; also,
        # any group after the first cannot have equals (but since overall equals only at end and
        # total is multiple of 4, this naturally holds if we check below).
        if eqs_in_group > 0:
            # Equals must only appear as the last 1 or 2 chars of this group
            if vals[0] == -1 or vals[1] == -1:
                raise binascii_Error()
            if eqs_in_group == 1 and vals[2] != -1:
                raise binascii_Error()
            if eqs_in_group == 2 and vals[2] == -1:
                # already handled above (vals[1]==-1 triggers error)
                pass

        v0, v1, v2, v3 = vals
        # Build 24-bit value from available values
        val24 = (v0 << 18) | ((v1 if v1 >= 0 else 0) << 12) | \
                ((v2 if v2 >= 0 else 0) << 6)  | (v3 if v3 >= 0 else 0)

        # Decide how many output bytes based on number of real values
        real_vals = sum(1 for v in vals if v >= 0)
        if real_vals == 4:
            out.extend([(val24 >> 16) & 0xFF, (val24 >> 8) & 0xFF, val24 & 0xFF])
        elif real_vals == 3:
            # One padding byte
            out.extend([(val24 >> 16) & 0xFF, (val24 >> 8) & 0xFF])
        elif real_vals == 2:
            # Two padding bytes
            out.extend([(val24 >> 16) & 0xFF])
        else:
            raise binascii_Error()

    return bytes(out)


