import sys

def a2b_base64(s: bytes) -> bytes:
    # Reject any byte outside the canonical alphabet (allow nothing else).
    for ch in s:
        if not (65 <= ch <= 90 or 97 <= ch <= 122 or 48 <= ch <= 57 or ch == 43 or ch == 47):
            raise binascii.Error('Invalid base64-encoded string: number of data characters %d cannot be 1 more than a multiple of 4' % len(s))
    if len(s) % 4 == 1:
        raise binascii.Error('Invalid base64-encoded string: number of data characters %d cannot be 1 more than a multiple of 4' % len(s))
    if len(s) >= 2 and s[len(s)-2] == 61 and s[len(s)-1] != 61:
        raise binascii.Error('Invalid base64-encoded string: number of data characters %d cannot be 1 more than a multiple of 4' % len(s))
    if len(s) == 1:
        raise binascii.Error("Base64-encoded string must have at least 2 characters, but only got %r" % (s,))

    vals = bytearray()
    for i in range(0, len(s), 4):
        chunk = s[i:i+4]
        vals.append(decode_val(chunk[0]))
        if len(chunk) >= 2:
            vals.append(decode_val(chunk[1]))
        if len(chunk) >= 3:
            vals.append(decode_val(chunk[2]))
        if len(chunk) >= 4:
            vals.append(decode_val(chunk[3]))
    # Convert packed quads to triples
    out = bytearray()
    for i in range(0, len(vals), 4):
        v0 = vals[i]; v1 = vals[i+1]; v2 = vals[i+2]; v3 = vals[i+3]
        b0 = (v0 << 2) | (v1 >> 4)
        b1 = ((v1 & 15) << 4) | (v2 >> 2)
        b2 = ((v2 & 3) << 6) | v3
        out.append(b0)
        if s[i+2] != 61:
            out.append(b1)
        if s[i+3] != 61:
            out.append(b2)
    return bytes(out)

