import base64, sys

b64_alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
b64_values = {}
for i, ch in enumerate(b64_alphabet):
    b64_values[ch] = i

def a2b_base64(s):
    if not isinstance(s, (bytes, bytearray)):
        s = s.encode('ascii')
    s = bytes(s)
    # Filter out whitespace and non-b64 characters to check
    cleaned = bytearray()
    for byte in s:
        c = chr(byte)
        if c == '\n' or c == '\r':
            continue
        if c not in b64_values and c != '=':
            raise binascii.Error("Non-base64 digit found")
        cleaned.append(byte)
    if len(cleaned) % 4 != 0:
        raise binascii.Error("Invalid base64 data length")
    # Count padding
    pad_count = 0
    for byte in reversed(cleaned):
        if chr(byte) == '=':
            pad_count += 1
        else:
            break
    if pad_count > 2:
        raise binascii.Error("Excess padding")
    result = bytearray()
    for i in range(0, len(cleaned), 4):
        group = cleaned[i:i+4]
        vals = []
        for byte in group:
            c = chr(byte)
            if c == '=':
                vals.append(0)
            else:
                vals.append(b64_values[c])
        combined = (vals[0] << 18) | (vals[1] << 12) | (vals[2] << 6) | vals[3]
        byte_out = [(combined >> 16) & 0xff, (combined >> 8) & 0xff, combined & 0xff]
        if pad_count == 0:
            result.extend(byte_out)
        elif pad_count == 1:
            result.extend(byte_out[:2])
        elif pad_count == 2:
            result.extend(byte_out[:1])
    return bytes(result)

