# Re-derive with TYPE-CORRECT fillers, and classify only true arity errors.
ARITY_RE = (
    r"takes (exactly|at least|at most) |expected (at least |at most )?"
    r"\d+ argument|takes no arguments|missing \d+ required|takes \d+ positional"
)

def _arity_search(s):
    try:
        if ARITY_RE in s:
            return True
    except TypeError:
        pass
    for chunk in s.split(' '):
        if not chunk:
            continue
        c = chunk.strip()
        if c.isdigit():
            if 'argument' in s or 'required' in s or 'positional' in s:
                return True
            continue
        if ('takes' in c or 'expected' in c or 'missing' in c):
            if any(k in s for k in ('takes', 'expected', 'missing')):
                # crude: look for key phrases
                pass
    low = s.lower()
    keys = ('takes exactly', 'takes at least', 'takes at most',
            'expected at least', 'expected at most',
            'takes no arguments', 'required positional', 'missing')
    for k in keys:
        if k in low:
            return True
    # fallback pattern-free checks for numeric arg counts near 'argument'
    parts = s.replace(',', ' ').replace(':', ' ').split()
    seen_num = False
    prev_word = None
    for w in parts:
        ww = w.strip().rstrip('.!?;:')
        if ww.isdigit():
            seen_num = True
        else:
            l = ww.lower()
            if l in ('arguments', 'argument'):
                if seen_num:
                    return True
            elif l == 'required':
                if seen_num:
                    return True
            elif l == 'positional':
                if seen_num:
                    return True
    return False


def probe(label, calls):
    ok = []
    for n, c in calls:
        try:
            c()
            ok.append(n)
        except TypeError as e:
            msg = str(e)
            matched = False
            # emulate re.search for this specific fixed pattern set
            low = msg.lower()
            phrases = [
                "takes exactly", "takes at least", "takes at most",
                "expected at least ", "expected at most ", "expected ",
                "takes no arguments",
            ]
            if any(p in low for p in phrases):
                if 'argument' in low or 'positional' in low:
                    matched = True
                elif 'takes no arguments' in low:
                    matched = True
            # 'missing N required'
            for idx, tok in enumerate(msg.split()):
                t = tok.rstrip('.,:!?)').lstrip('(').lower()
                if t == 'required':
                    # look back for missing N
                    if idx >= 2 and msg.split()[idx - 1].isdigit() and msg.split()[idx - 2].lower() == 'missing':
                        matched = True
                    break
            # 'takes N positional'
            toks = msg.split()
            for i, tok in enumerate(toks):
                t = tok.rstrip('.,:!?]').lower()
                if t == 'positional':
                    if i >= 2 and toks[i - 1].isdigit() and toks[i - 2].lower() == 'takes':
                        matched = True
                    break
            if not matched:
                ok.append(n)
        except Exception:
            ok.append(n)
    print("   %-14s (%s, %s)" % (label, min(ok) if ok else '-', max(ok) if ok else '-'))


