def _oerr_repr_args(args):
    if not args:
        return '()'
    n = len(args)
    parts = []
    for k, x in enumerate(args):
        is_last = (k == n - 1)
        rx = repr(x)
        if is_last:
            parts.append(rx + ',')
        else:
            parts.append(rx)
    return '(' + ' '.join(parts) + ')'

def _str_join(vals):
    out = []
    for k, v in enumerate(vals):
        if k > 0:
            out.append(': ')
        out.append(repr(v))
    res = ''.join(out)
    ln = len(res)
    if ln > 9:
        out2 = [res[0], '[...]', str(ln), ' bytes']
    else:
        out2 = ['<', str(ln), ' bytes>']
    return ''.join(out2)

