import math

def do_pct(fmt, arg):
    """Simulate '%s' % arg formatting (Python 3.8+ behavior)."""
    if fmt is None:
        fmt = '%s'
    if not isinstance(fmt, str):
        raise TypeError("not all arguments converted during string formatting")
    # Check for format specifiers beyond %s
    i = 0
    while i < len(fmt):
        if fmt[i] == '%':
            j = i + 1
            if j < len(fmt) and fmt[j] == '%':
                i += 2
                continue
            # parse flags, width, precision, conversion
            k = j
            # flags
            while k < len(fmt) and fmt[k] in '0- +#!':
                k += 1
            # width
            w_start = k
            while k < len(fmt) and fmt[k].isdigit():
                k += 1
            width_str = fmt[w_start:k]
            # precision
            prec = ''
            if k < len(fmt) and fmt[k] == '.':
                k += 1
                p_start = k
                while k < len(fmt) and fmt[k].isdigit():
                    k += 1
                prec = '.' + fmt[p_start:k]
            # mapping key
            if k < len(fmt) and fmt[k] in '{}':
                pass
            # conversion type
            if k >= len(fmt):
                raise ValueError("incomplete format")
            conv = fmt[k]
            if conv != 's' and conv != 'r' and conv != 'a':
                raise TypeError("unsupported format character %r" % ord(conv))
            i = k + 1
            continue
        else:
            i += 1
    return fmt % arg


def eval_expr(expr):
    """Evaluate the given expression string without using eval."""
    expr = expr.strip()

    # Try to match specific patterns

    # Pattern: '"%X" % value' or "'%X' % value"
    import re
    m = re.match(r'^["\'](.*)["\']\s*%\s*(.+)$', expr)
    if m:
        fmt = m.group(1)
        val_str = m.group(2).strip()

        # Parse the value
        val = parse_value(val_str)

        # If it's a simple %s or no conversion specifier issues, use normal formatting
        # But we need to handle float->int conversions properly
        try:
            result = do_pct(fmt, val)
            return result
        except Exception as e:
            raise e

    # Pattern: 'format(value, "spec")'
    m = re.match(r'^format\((.+),\s*(["\'].*["\'])\)$', expr)
    if m:
        val_str = m.group(1).strip()
        spec = m.group(2).strip()
        # Remove quotes from spec
        if (spec.startswith('"') and spec.endswith('"')) or (spec.startswith("'") and spec.endswith("'")):
            spec = spec[1:-1]

        val = parse_value(val_str)

        # Use Python's format function - this should work since format is builtin
        return format(val, spec)

    # Pattern: '"{:spec}".format(value)'
    m = re.match(r'^["\']\{:(.*)\}["\']\.format\((.+)\)$', expr)
    if m:
        spec = m.group(1)
        val_str = m.group(2).strip()
        val = parse_value(val_str)
        return '{:' + spec + '}'.format(val)

    # Fallback: this shouldn't happen with our test cases
    raise ValueError("Cannot evaluate: " + expr)


def parse_value(s):
    """Parse a Python value from a string literal (limited set)."""
    s = s.strip()

    # True/False/None
    if s == 'True':
        return True
    if s == 'False':
        return False
    if s == 'None':
        return None

    # Strings
    if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
        inner = s[1:-1]
        # Handle escape sequences minimally
        return inner

    # Lists (simple case like [1])
    if s.startswith('[') and s.endswith(']'):
        inner = s[1:-1].strip()
        if inner == '':
            return []
        # Simple list of single element
        if ',' not in inner:
            return [parse_value(inner)]
        else:
            parts = inner.split(',')
            return [parse_value(p.strip()) for p in parts]

    # Float nan/inf
    if s == 'float("nan")' or s == "float('nan')":
        return float('nan')
    if s == 'float("inf")' or s == "float('inf')":
        return float('inf')
    if s == 'float("-inf")' or s == "float('-inf')":
        return float('-inf')

    # Numeric literals
    try:
        # Try int first
        if re.match(r'^-?\d+$', s):
            return int(s)
        # Try float
        if re.match(r'^-?\d+\.\d*$' , s) or re.match(r'^-?\d*\.\d+$', s) or \
           re.match(r'^-?\d+[eE][-+]?\d+$', s) or re.match(r'^-?\d+\.\d*[eE][-+]?\d+$', s) or \
           re.match(r'^-?\.\d+[eE][-+]?\d+$', s) or re.match(r'^-\.\d+[eE][-+]?\d+$', s):
            return float(s)
        # General float attempt
        return float(s)
    except:
        pass

    # Generic fallback
    return s


