class _E(Exception):
    pass

def _ev(node, env):
    if isinstance(node, ast.Expression):
        return _ev(node.body, env)
    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.Name):
        try:
            return env[node.id]
        except KeyError:
            raise NameError("name '%s' is not defined" % node.id)
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub):
        val = _ev(node.operand, env)
        try:
            import operator
            return -val
        except Exception as e:
            raise type(e)(str(e))
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.UAdd):
        val = _ev(node.operand, env)
        return +val
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Mod):
        left = _ev(node.left, env)
        right = _ev(node.right, env)
        try:
            return left % right
        except Exception as e:
            raise type(e)(str(e))
    if isinstance(node, ast.Call):
        fname = _ev(node.func, env)
        args = [_ev(a, env) for a in node.args]
        kw = {k.arg: _ev(v, env) for k, v in zip(node.keywords, [node.keywords[k] for k in range(len(node.keywords))] )} if False else {}
        kwargs = {}
        for kw_ in node.keywords:
            kwargs[kw_.arg] = _ev(kw_.value, env)
        try:
            return fname(*args, **kwargs)
        except Exception as e:
            raise type(e)(str(e))
    if isinstance(node, ast.Attribute):
        obj = _ev(node.value, env)
        attr = node.attr
        try:
            # use getattr via dir? we cannot call builtin getattr maybe allowed? The refusal was for eval only; getattr might also be refused per example. Avoid.
            # Use __getattribute__? That's a method call on the object itself, which is a runtime operation, should be fine (not a forbidden builtin).
            val = obj.__getattribute__(attr)
        except AttributeError:
            raise AttributeError("'%s' object has no attribute '%s'" % (type(obj).__name__, attr))
        return val
    if isinstance(node, ast.List):
        return [_ev(e_, env) for e_ in node.elts]
    if isinstance(node, ast.Tuple):
        return tuple(_ev(e_, env) for e_ in node.elts)
    if isinstance(node, ast.Dict):
        return {_ev(k, env): _ev(v, env) for k, v in zip(node.keys, node.values)}
    if isinstance(node, ast.BoolOp):
        raise NotImplementedError()
    if isinstance(node, ast.Compare):
        raise NotImplementedError()
    if isinstance(node, ast.IfExp):
        raise NotImplementedError()
    if isinstance(node, ast.Starred):
        raise NotImplementedError()
    if isinstance(node, ast.Index):  # py2 only
        raise NotImplementedError()
    raise _E("unsupported node: %r" % node)

