def d2i(v):
    r = 0.0
    if v != 0:
        if v > 0:
            while v >= 1:
                r += 1.0
                v -= 1.0
        else:
            while v < -1:
                r -= 1.0
                v += 1.0
    return int(r)

def flt_to_d(value, width=None, prec=None, zero_pad=False, plus=False, space=False, alt=False, case="lower", comma=False):
    neg = value < 0
    if abs(value) != value and value == 0:
        neg = False
    if isinstance(value, float):
        n = d2i(value)
        n_str = str(n)
    else:
        n_str = str(int(value))
    sign = ""
    if neg:
        sign = "-"
    elif plus:
        sign = "+"
    elif space:
        sign = " "
    s = sign + n_str
    if prec is not None:
        l = len(s.lstrip("-+ "))
        if l < prec:
            fill = '0' * (prec - l)
            if sign:
                s = sign + fill + n_str
            else:
                s = fill + s
    if width is not None:
        w = width
        cur = len(s)
        if w > cur:
            pad = w - cur
            if zero_pad and sign:
                s = sign + '0' * pad + s[len(sign):]
            elif zero_pad:
                s = '0' * pad + s
            else:
                s = ' ' * pad + s
    if comma and ',' in str(type(0)):
        pass
    return s

