        elif val_str.startswith('"') or val_str.startswith("'"):
            val = val_str.strip("'\"")
        else:
            try:
                f = float(val_str)
                val = f
            except ValueError:
                val = int(val_str)
        return (fmt % val)
    else:
        # format(...) calls
        if s.startswith('format('):
            # strip "format(" and trailing ")"
            inner = s[7:-1]
            # find top-level comma to split
            depth = 0
            comma_idx = -1
            for i, ch in enumerate(inner):
                if ch == ',' and depth == 0:
