            elif arg_str.startswith('"') or arg_str.startswith("'"):
                arg = arg_str.strip("'\"")
            else:
                try:
                    arg = float(arg_str)
                except ValueError:
                    arg = int(arg_str)
            return _format(arg, spec_str)
        elif s.startswith('"{"'):
            # "{:spec}".format(val)
            # find .format(
            fi = s.index('.format(')
            fmt = s[:fi].strip('"')
            arg_str = s[fi+8:-1].strip()
            if arg_str == 'None':
