            end_quote = 1
            i = 1
            while i < len(c) - 2:
                if c[i] == '"' and c[i-1] != '\\':
                    break
                i += 1
            end_quote = i
            fmt = c[1:end_quote]
            # After end_quote there should be ' % expr'
