        elif c.startswith('"{' ) and c.endswith('.format('):
            # "{...}" .format(...)
            dot_idx = c.find('.format(')
            fmt = c[1:dot_idx]  # strip leading ", but keep interior quotes
            # fmt contains e.g. {:d}
            argexpr = c[dot_idx+len('.format('):-1]
            arg = _evalarg(argexpr)
            result = fmt.format(arg)
            return result
        else:
