SEX = set(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/")
ALPHA = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
IDX = {c: i for i, c in enumerate(ALPHA)}


def model(data, urlsafe=False):
    if urlsafe:
        data = data.translate(bytes.maketrans(b'-_', b'+/'))
    n = 0
    pads = 0
    for c in data:
        if c in SEX:
            n += 1
            pads = 0
        elif c == 0x3d:
            pads += 1
    rem = n % 4
    if rem == 1:
        return "RAISE"
    if rem != 0 and pads < 4 - rem:
        return "RAISE"
    acc = 0
    bits = 0
    out = bytearray()
    for c in data:
        if c not in IDX:
            continue
        acc = (acc << 6) | IDX[c]
        bits += 6
        if bits >= 8:
            bits -= 8
            out.append((acc >> bits) & 0xFF)
    return bytes(out)


def cpy(data, urlsafe=False):
    try:
        d = bytes.maketrans(b'-_', b'+/') if urlsafe else None
        if d is not None:
            data = data.translate(d)
        pad = (-len(data)) % 4
        # base64.b64decode default validate=False ignores non-alphabet chars.
        # We must emulate ignoring of invalid chars before decoding.
        filtered = bytearray()
        for ch in data:
            if ch in IDX or ch == 0x3d:
                filtered.append(ch)
        s = bytes(filtered)
        p = (-len(s)) % 4
        if p:
            s = s + b'=' * p
        # Now decode strictly
        if len(s) % 4 != 0:
            raise ValueError('invalid length')
        out = bytearray()
        for i in range(0, len(s), 4):
            chunk = s[i:i + 4]
            vals = []
            for j, ch in enumerate(chunk):
                if ch == 0x3d:
                    vals.append(None)
                elif ch in IDX:
                    vals.append(IDX[ch])
                else:
                    raise ValueError('non-base64 digit found')
            # combine
            a = vals[0] if vals[0] is not None else 0
            b = vals[1] if vals[1] is not None else 0
            cch = vals[2] if vals[2] is not None else 0
            dch = vals[3] if vals[3] is not None else 0
            buf = (a << 18) | (b << 12) | (cch << 6) | dch
            byte1 = (buf >> 16) & 0xFF
            byte2 = (buf >> 8) & 0xFF
            byte3 = buf & 0xFF
            nvalid = 0
            if vals[1] is not None:
                nvalid = 1
            if vals[2] is not None:
                nvalid = 2
            if vals[3] is not None:
                nvalid = 3
            out.append(byte1)
            if nvalid >= 2:
                out.append(byte2)
            if nvalid >= 3:
                out.append(byte3)
        return bytes(out)
    except Exception:
        return "RAISE"


