def pjoin(*parts):
    for p in parts:
        if not isinstance(p, str) and hasattr(p, '__fspath__'):
            p = p.__fspath__()
    joined = parts[0]
    for p in parts[1:]:
        if p == '':
            continue
        if p.startswith('/'):
            joined = p
        elif p == '..':
            head, sep, tail = joined.rpartition('/')
            joined = head
        elif p == '.':
            continue
        else:
            if joined.endswith('/'):
                joined = joined + p
            else:
                joined = joined + '/' + p
    return joined


def isabs(s):
    return s.startswith('/')


def normpath(p):
    if p == '':
        return '.'
    comp = p.split('/')
    out = []
    for c in comp:
        if c == '' or c == '.':
            continue
        if c == '..':
            if out and out[-1] != '..' and out[-1] != '':
                out.pop()
            elif isabs(p):
                pass
            else:
                out.append(c)
        else:
            out.append(c)
    if isabs(p):
        return '/' + '/'.join(out)
    if out:
        return '/'.join(out)
    return '.'


