                parts.append(a.p)
            else:
                parts.append(str(a))
        if len(parts) == 1:
            self.p = parts[0]
        else:
            self.p = pjoin(*parts)

    def __repr__(self):
        return 'PosixPath(%r)' % (self.p,)


