def _make_cm(fn):
    class _CM:
        def __enter__(self):
            self._gen = fn()
            next(self._gen)

        def __exit__(self, exc_type, exc_val, exc_tb):
            try:
                if exc_type is not None:
                    self._gen.throw(exc_type, exc_val, exc_tb)
                else:
                    self._gen.send(None)
            except StopIteration:
                pass
            else:
                raise RuntimeError("generator didn't stop")
            return False
    def _wrapper(*args, **kwargs):
        return _CM()
    return _wrapper


