def _b64decode_nov(s):
    i = 0
    n = len(s)
    out = bytearray()
    while i < n:
        c1 = s[i]; i += 1
        if c1 == 32:
            continue
        if c1 < 43 or c1 > 126 or (c1 > 57 and c1 < 65) or (c1 > 90 and c1 < 97):
            continue
        # c1 valid alphabet char
        if i >= n:
            break
        c2 = s[i]; i += 1
        while c2 == 32:
            if i >= n:
                break
            c2 = s[i]; i += 1
        if c2 in (61, 32):
            continue
        if c2 < 43 or c2 > 126 or (c2 > 57 and c2 < 65) or (c2 > 90 and c2 < 97):
            continue
        val = A2V[c1] << 18 | A2V[c2] << 12
        if i >= n:
            break
        c3 = s[i]; i += 1
        if c3 == 61:
            val >>= 6
            out.append(val >> 16); out.append((val >> 8) & 255)
            continue
        if c3 == 32:
            while c3 == 32 and i < n:
                c3 = s[i]; i += 1
        if c3 < 43 or c3 > 126 or (c3 > 57 and c3 < 65) or (c3 > 90 and c3 < 97):
            if c3 != 61:
                continue
            else:
                val >>= 6
                out.append(val >> 16); out.append((val >> 8) & 255)
                continue
        val |= A2V[c3] << 6
        if i >= n:
            break
        c4 = s[i]; i += 1
        while c4 == 32:
            if i >= n:
                break
            c4 = s[i]; i += 1
        if c4 == 61:
            val &= ~1
            out.append(val >> 16); out.append((val >> 8) & 255); out.append(val & 255)
            continue
        if c4 < 43 or c4 > 126 or (c4 > 57 and c4 < 65) or (c4 > 90 and c4 < 97):
            continue
        val |= A2V[c4]
        out.append(val >> 16); out.append((val >> 8) & 255); out.append(val & 255)
    return bytes(out)

