def b64decode_no_validate(s):
    if not isinstance(s, bytes):
        raise TypeError("argument should be a bytes object")
    pad = 0
    while s.endswith(b'='):
        pad += 1
        s = s[:-1]
        if pad > 2:
            raise binascii.Error("Invalid base64-encoded string")
    if len(s) % 4 == 1 or len(s) % 4 == 3:
        raise binascii.Error("Invalid base64-encoded string")
    groups = []
    for i in range(0, len(s), 4):
        chunk = s[i:i + 4]
        if len(chunk) != 4:
            break
        vals = []
        ok = True
        for c in chunk:
            cc = chr(c)
            if cc in b64_table:
                vals.append(b64_table[cc])
            else:
                if cc == '\n' or cc == '\r':
                    # treat as ignored
                    vals.append(None)
                else:
                    ok = False
                    break
        groups.append((chunk, vals, ok))
    # Now process
    out = bytearray()
    for chunk, vals, ok in groups:
        if not ok:
            # find first bad char
            for c in chunk:
                cc = chr(c)
                if cc in b64_table:
                    continue
                if cc in ('\n', '\r'):
                    continue
                raise binascii.Error("Non-base64 digit found")
        # count valid
        valid = [v for v in vals if v is not None]
        if len(valid) == 4:
            n = (valid[0] << 18) | (valid[1] << 12) | (valid[2] << 6) | valid[3]
            out.append((n >> 16) & 0xFF)
            out.append((n >> 8) & 0xFF)
            out.append(n & 0xFF)
        elif len(valid) == 3:
            n = (valid[0] << 18) | (valid[1] << 12) | (valid[2] << 6)
            out.append((n >> 16) & 0xFF)
            out.append((n >> 8) & 0xFF)
        elif len(valid) == 2:
            n = (valid[0] << 18) | (valid[1] << 12)
            out.append((n >> 16) & 0xFF)
        elif len(valid) == 1:
            n = valid[0] << 18
            out.append((n >> 16) & 0xFF)
        else:
            pass
    return bytes(out)


def strict_check(s, original_len):
    # strict mode rejects any non-base64 char including newlines? 
    # Actually binascii.a2b_base64 with flags=0 rejects anything not in the alphabet
    # Let's implement: iterate, collect values
    vals = []
    for byte in s:
        c = chr(byte)
        if c in b64_table:
            vals.append(b64_table[c])
        else:
            raise binascii.Error("Non-base64 digit found")
    # padding check
    nvals = len(vals)
    if nvals % 4 == 1:
        raise binascii.Error("Invalid base64-encoded string")
    # build output same way
    out = bytearray()
    i = 0
    while i < nvals:
        rem = nvals - i
        if rem == 4:
            n = (vals[i] << 18) | (vals[i+1] << 12) | (vals[i+2] << 6) | vals[i+3]
            out.append((n >> 16) & 0xFF)
            out.append((n >> 8) & 0xFF)
            out.append(n & 0xFF)
            i += 4
        elif rem == 3:
            n = (vals[i] << 18) | (vals[i+1] << 12) | (vals[i+2] << 6)
            out.append((n >> 16) & 0xFF)
            out.append((n >> 8) & 0xFF)
            i += 3
        elif rem == 2:
            n = (vals[i] << 18) | (vals[i+1] << 12)
            out.append((n >> 16) & 0xFF)
            i += 2
        else:
            break
    return bytes(out)


