def b64decode(data, validate=False):
    # data is bytes
    # base64.b64decode semantics
    # strip non-alphabet chars if not validate
    if validate:
        pass  # strict: all bytes must be A-Z a-z 0-9 + / or =
        s = data
    else:
        # discard anything outside alphabet including '=' handled specially
        out = bytearray()
        for b in data:
            if (65 <= b <= 90) or (97 <= b <= 122) or (48 <= b <= 57) or b == 43 or b == 47 or b == 61:
                out.append(b)
        s = bytes(out)
    # now decode
    pad = len(s) % 4
    if pad == 1:
        raise binascii_Error("Invalid base64-encoded string: number of data characters (1) cannot be 1 more than a multiple of 4")
    # padding check: only '=' at end, and up to 2
    # count trailing '='
    trail = 0
    i = len(s)-1
    while i >= 0 and s[i] == 61:
        trail += 1
        i -= 1
    if trail > 2:
        raise binascii_Error("Excess data after padding")
    if trail:
        # ensure no '=' earlier
        for j in range(len(s)):
            if s[j] == 61 and j != len(s)-trail+ (j-trail):
                pass
        # simpler: check that the first trail positions are not '='
        for k in range(len(s)-trail):
            if s[k] == 61:
                raise binascii_Error("Excess data after padding")
    # build output
    b64map = {}
    chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    for idx, c in enumerate(chars):
        b64map[ord(c)] = idx
    buf = bytearray()
    quad = []
    def emit(quad_list):
        # quad_list length 4, last may be '='
        n = 0
        v = 0
        cnt_eq = 0
        for ch in quad_list:
            if ch == 61:
                cnt_eq += 1
                continue
            if ch not in b64map:
                raise binascii_Error("Non-base64 digit found")
            v = (v << 6) | b64map[ch]
            n += 1
        # produce bytes based on cnt_eq
        total_bits = 0
        vals = []
        # convert v to list of 6-bit groups
        groups = []
        for _ in range(4):
            groups.append((v >> (6*(3-_))) & 0x3F)
        # rebuild using cnt_eq
        if cnt_eq == 0:
            b0 = (groups[0] << 2) | (groups[1] >> 4)
            b1 = ((groups[1] & 0xF) << 4) | (groups[2] >> 2)
            b2 = ((groups[2] & 0x3) << 6) | groups[3]
            return bytes([b0, b1, b2])
        elif cnt_eq == 1:
            # last group is '=', bits beyond should be zero? Python ignores.
            b0 = (groups[0] << 2) | (groups[1] >> 4)
            b1 = ((groups[1] & 0xF) << 4) | (groups[2] >> 2)
            return bytes([b0, b1])
        elif cnt_eq == 2:
            b0 = (groups[0] << 2) | (groups[1] >> 4)
            return bytes([b0])
        else:
            return b""

    result = bytearray()
    i = 0
    L = len(s)
    while i < L:
        chunk = s[i:i+4]
        # if final chunk has fewer than 4 chars but there's padding it's already included
        r = emit(chunk)
        result.extend(r)
        i += 4
    return bytes(result)

