import json, os

def iter_matches(pattern):
    parts = pattern.split('/')
    for i, p in enumerate(parts):
        if '*' in p or '?' in p:
            root = '/'.join(parts[:i])
            base_name = parts[i]
            try:
                entries = sorted(os.listdir(root))
            except OSError:
                return []
            out = []
            # Build a regex from the glob pattern (only supports * ? .)
            import re as _re
            rx = ''
            j = 0
            while j < len(base_name):
                ch = base_name[j]
                if ch == '*':
                    k = j
                    star_count = 1
                    while k + 1 < len(base_name) and base_name[k+1] == '*':
                        star_count += 1
                        k += 1
                    if star_count >= 2:
                        rx += '.*'
                    else:
                        rx += '[^/]*'
                    j = k + 1
                    continue
                elif ch == '?':
                    rx += '[^/]'
                else:
                    if ch in '.+()|^${}[]\\':
                        rx += '\\' + ch
                    else:
                        rx += ch
                j += 1
            rx_full = '^' + rx + '$'
            for e in entries:
                if _re.match(rx_full, e):
                    full = '/' + e if root == '' else root + '/' + e
                    rest = parts[i+1:]
                    if not rest:
                        # Must be a file or dir; accept both since we open with json
                        out.append(full)
                    else:
                        sub_pattern = '/'.join(rest)
                        out.extend(iter_matches(full + '/' + sub_pattern))
            return out
        # else plain path part, continue
    return [pattern]

