def fmt(v, spec):
    if 'd' in spec:
        return str(int(v))
    elif 'f' in spec:
        prec = 0
        i = spec.rfind('.') + 1
        j = spec.find('f')
        if j > i - 1 and i >= 1:
            s = spec[i:j]
            if s.isdigit():
                prec = int(s)
        else:
            s2 = spec[:spec.find('.')]
            if '.' in spec:
                s = spec[spec.find('.') + 1:]
                k = min((x for x in [s.find(c) for c in 'fd'] if x >= 0), default=len(s))
                if s[:k].isdigit():
                    prec = int(s[:k])
        if prec == 1:
            return "%.1f" % (v,)
        elif prec == 2:
            return "%.2f" % (v,)
        else:
            return "%.6f" % (v,)
    return str(v)

