    if not text:
        return []

    lines = []
    current_line = ""

    # Split by whitespace, keeping track of word boundaries
    words = []
    i = 0
    n = len(text)

    while i < n:
        # Skip leading spaces/tabs
        while i < n and (text[i] == ' ' or text[i] == '\t'):
            i += 1

        if i >= n:
            break

        # Find end of current word (including hyphens within)
        start = i
        while i < n and text[i] != ' ' and text[i] != '\t':
            i += 1
        words.append(text[start:i])

