    for word in words:
        if not word:
            continue

        if not current_line:
            current_line = word
        else:
            # Check if we can add this word
            needed_len = len(current_line) + 1 + len(word)
            if needed_len <= width:
                current_line = current_line + " " + word
            else:
                lines.append(current_line)
                # Now try to fit the word alone
                if len(word) <= width:
                    current_line = word
                else:
