def wrap(text, width=80, break_long_words=False, break_on_hyphens=False):
    lines = []
    paragraph = text
    while paragraph != '':
        if len(paragraph) <= width:
            lines.append(paragraph)
            break
        i = width
        sl = paragraph[:width]
        j = sl.rfind(' ', 1)
        k = sl.find(' ')
        if k >= 0 and j < 0:
            j = k
        if break_on_hyphens:
            l = sl.rfind('-', 1)
            if l > j:
                j = l
        if j < 0:
            if break_long_words:
                j = width
            else:
                l = width
                m = paragraph.find(' ', width)
                n = paragraph.find('-', width)
                if -1 < m and (-1 > n or m < n):
                    l = m + 1
                elif -1 < n:
                    l = n + 1
                lines.append(paragraph[:l])
                paragraph = paragraph[l:]
        else:
            lines.append(paragraph[:j])
            paragraph = paragraph[j+1:].lstrip()
    return lines


