import os, sys

def wrap_text(t, width=80):
    words = t.split(' ')
    lines = []
    cur = ''

    for word in words:
        # Calculate the length of the word (considering it's a single token from split)
        w_len = len(word)

        if not cur:
            if w_len > width:
                # Word is longer than width; put it on its own line (don't break)
                lines.append(word)
                cur = ''
            else:
                cur = word
        else:
            new_len = len(cur) + 1 + w_len
            if new_len <= width:
                cur = cur + ' ' + word
            else:
                # Current line full; start new line with this word
                lines.append(cur)
                if w_len > width:
                    # Next word too long to fit after others; put alone
                    lines.append(word)
                    cur = ''
                else:
                    cur = word

    if cur:
        lines.append(cur)
    return lines


