import os, sys

def wrap_line(line, width):
    # Replicate textwrap.wrap(line, 80, break_long_words=False, break_on_hyphens=False)
    if not line:
        return []
    # Standard algorithm from CPython source (simplified for single-line input with default whitespace settings)
    words = line.split()  # split on whitespace sequences, discard empties
    if not words:
        return []
    current = ""
    lines = []
    for word in words:
        test = current + " " + word if current else word
        if len(test) <= width:
            current = test
        else:
            if current:
                lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines

