                    in_str = None
                    current += ch
                else:
                    current += ch
                i += 1
                continue
            else:
                if ch in ('"', "'"):
                    in_str = ch
                    current += ch
                    i += 1
                    continue
                elif ch == '(':
                    depth += 1
                    current += ch
                    i += 1
                    continue
