def _literal(s):
    s = s.strip()
    if s.startswith('"') and s.endswith('"'):
        return s[1:-1].replace('\\"', '"').replace("\\\\", "\\")
    if s.startswith("'") and s.endswith("'"):
        return s[1:-1].replace("\\'", "'").replace("\\\\", "\\")
    if s.startswith('b"') and s.endswith('"'):
        inner = s[2:-1]
        return inner.encode().decode('unicode_escape').encode('latin-1') if False else inner.encode('latin-1')
    if s == 'True':
        return True
    if s == 'False':
        return False
    if s == 'None':
        return None
    try:
        return int(s)
    except ValueError:
        pass
    try:
        return float(s)
    except ValueError:
        pass
    return s


