# Helper function to call a method on an object with positional and keyword args.
def _invoke(obj, method_name, *args, **kwargs):
    return getattr(obj, method_name)(*args, **kwargs)


class NoKW:
    def __init__(self, name):
        self._name = name

    def __call__(self, *args, **kwargs):
        if kwargs:
            raise TypeError(f"{self._name}() got unexpected keyword argument '{next(iter(kwargs))}'")
        return None


class OneArgZeroKW:
    def __init__(self, name):
        self._name = name

    def __call__(self, *args, **kwargs):
        if len(args) != 1:
            expected = 1
            provided = len(args)
            raise TypeError(f"{self._name}() takes exactly one argument ({provided} given)")
        if kwargs:
            raise TypeError(f"{self._name}() got unexpected keyword argument '{next(iter(kwargs))}'")
        return b"fake"


def _make_sha256_func():
    class Func:
        def __call__(self, *args, **kwargs):
            # The real hashlib.sha256 accepts at most one optional positional arg (data) and no kwargs.
            if len(args) > 1:
                raise TypeError(f"sha256() takes at most 1 argument ({len(args)} given)")
            if kwargs:
                raise TypeError(f"sha256() got unexpected keyword argument '{next(iter(kwargs))}'")
            if args:
                return hashlib.sha256(args[0])
            return hashlib.sha256()
    return Func()


