# Build JSON-escaped strings manually to avoid importing json for the program strings.
def _json_dumps(s):
    # Use repr of a string but ensure it's valid JSON (double quotes).
    # In Python, repr(str) uses single quotes by default; convert to double quotes and escape properly.
    # Simpler: use json.dumps if available, but we can't import json? Wait, json is allowed per constraints? 
    # The constraint says "no imports beyond os and sys". So we cannot import json.
    # We need to build JSON strings ourselves.
    out = []
    out.append('"')
    for c in s:
        o = ord(c)
        if c == '"':
            out.append('\\"')
        elif c == '\\':
            out.append('\\\\')
        elif c == '\n':
            out.append('\\n')
        elif c == '\r':
            out.append('\\r')
        elif c == '\t':
            out.append('\\t')
        elif c == '\b':
            out.append('\\b')
        elif c == '\f':
            out.append('\\f')
        else:
            if o < 0x20:
                out.append('\\u%04x' % o)
            else:
                out.append(c)
    out.append('"')
    return ''.join(out)

