import json, sys

def json_dumps(obj):
    if obj is None:
        return "null"
    if isinstance(obj, bool):
        return "true" if obj else "false"
    if isinstance(obj, int):
        return str(obj)
    if isinstance(obj, float):
        return repr(obj)
    if isinstance(obj, str):
        s = obj.replace('\\', '\\\\').replace('"', '\\"')
        s = s.replace('\n', '\\n').replace('\r', '\\r').replace('\t', '\\t')
        s = s.replace('\b', '\\b').replace('\f', '\\f')
        out = '"' + s + '"'
        return out
    if isinstance(obj, list):
        parts = [json_dumps(x) for x in obj]
        return '[' + ','.join(parts) + ']'
    if isinstance(obj, dict):
        parts = []
        for k, v in obj.items():
            kk = str(k).replace('\\', '\\\\').replace('"', '\\"')
            kk = kk.replace('\n', '\\n').replace('\r', '\\r').replace('\t', '\\t')
            kk = kk.replace('\b', '\\b').replace('\f', '\\f')
            parts.append('"' + kk + '":' + json_dumps(v))
        return '{' + ','.join(parts) + '}'
    raise ValueError("unsupported")

