def _json_dumps(o):
    out = []
    def emit(obj, indent=0):
        if obj is None:
            out.append('null')
        elif isinstance(obj, bool):
            out.append('true' if obj else 'false')
        elif isinstance(obj, int):
            out.append(str(obj))
        elif isinstance(obj, float):
            out.append(repr(obj))
        elif isinstance(obj, str):
            s = ''
            for c in obj:
                o = ord(c)
                if o == 0x22:
                    s += '\\"'
                elif o == 0x5c:
                    s += '\\\\'
                elif o == 0x08:
                    s += '\\b'
                elif o == 0x0c:
                    s += '\\f'
                elif o == 0x0a:
                    s += '\\n'
                elif o == 0x0d:
                    s += '\\r'
                elif o == 0x09:
                    s += '\\t'
                elif o < 0x20:
                    s += '\\u%04x' % o
                else:
                    s += c
            out.append('"' + s + '"')
        elif isinstance(obj, list):
            out.append('[')
            first = True
            for i, item in enumerate(obj):
                if not first:
                    out.append(',')
                first = False
                emit(item, indent+1)
            out.append(']')
        elif isinstance(obj, dict):
            out.append('{')
            first = True
            for k in obj:
                if not first:
                    out.append(',')
                first = False
                emit(k, indent+1)
                out.append(':')
                emit(obj[k], indent+1)
            out.append('}')
    emit(o)
    return ''.join(out)

