# Parse the URL manually since we can't use urllib.parse directly in this environment


def url_parse(url):
    """Manually parse a URL similar to urlparse."""
    # Split scheme
    if '://' in url:
        scheme, rest = url.split('://', 1)
    else:
        scheme = ''
        rest = url

    # Find netloc (domain part)
    # Netloc ends at first /, ?, or #
    path_start = len(rest)
    for i, c in enumerate(rest):
        if c in '/?#':
            path_start = i
            break
    netloc = rest[:path_start]
    rest = rest[path_start:]

    # Find path, query, fragment
    path = ''
    query = ''
    fragment = ''

    if rest.startswith('/'):
        # Find query and fragment
        hash_pos = rest.find('#')
        qmark_pos = rest.find('?')

        if hash_pos != -1 and (qmark_pos == -1 or hash_pos < qmark_pos):
            # Fragment before query (or no query)
            path_query_part = rest[:hash_pos]
            fragment = rest[hash_pos + 1:]
            if '?' in path_query_part:
                p, q = path_query_part.split('?', 1)
                path = p
                query = q
            else:
                path = path_query_part
                query = ''
        elif qmark_pos != -1:
            # Query present
            if hash_pos != -1:
                path_query_part = rest[:qmark_pos]
                query_fragment = rest[qmark_pos + 1:]
                if '#' in query_fragment:
                    q, f = query_fragment.split('#', 1)
                    query = q
                    fragment = f
                else:
                    query = query_fragment
                    fragment = ''
                path = path_query_part
            else:
                path, query = rest[:qmark_pos], rest[qmark_pos + 1:]
        else:
            path = rest

    return (scheme, netloc, path, query, fragment)


def parse_qs(qs):
    """Parse a query string into a dictionary of lists."""
    result = {}
    if not qs:
        return result

    for pair in qs.split('&'):
        if '=' in pair:
            key, value = pair.split('=', 1)
        else:
            key = pair
            value = ''

        # URL-decode key and value
        key = decode_url_component(key)
        value = decode_url_component(value)

        if key not in result:
            result[key] = []
        result[key].append(value)

    return result


def decode_url_component(s):
    """URL-decode a component."""
    result = []
    i = 0
    while i < len(s):
        if s[i] == '%' and i + 2 < len(s):
            hex_chars = s[i+1:i+3]
            try:
                byte_value = int(hex_chars, 16)
                result.append(chr(byte_value))
                i += 3
            except ValueError:
                result.append(s[i])
                i += 1
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)


