import sys

def parse_qs(q):
    d = {}
    if not q:
        return d
    for part in q.split('&'):
        if '=' in part:
            k, v = part.split('=', 1)
        else:
            k, v = part, ''
        k = _unquote(k)
        v = _unquote(v)
        if k in d:
            d[k].append(v)
        else:
            d[k] = [v]
    return d

def _unquote(s):
    s = s.replace('+', ' ')
    out = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '%' and i + 2 < n:
            hexs = s[i+1:i+3]
            try:
                val = int(hexs, 16)
                out.append(chr(val))
                i += 3
            except ValueError:
                out.append(c)
                i += 1
        else:
            out.append(c)
            i += 1
    return ''.join(out)

def urlparse(url):
    # scheme
    scheme = ''
    rest = url
    idx = url.find(':')
    if idx != -1:
        potential = url[:idx]
        if potential and (potential[0].isalpha() or potential[0] == '_'):
            ok = True
            for ch in potential:
                if not (ch.isalnum() or ch in '+-.'):
                    ok = False
                    break
            if ok:
                scheme = potential
                rest = url[idx+1:]
                if rest.startswith('//'):
                    # authority
                    rest = rest[2:]
                    slash_idx = rest.find('/')
                    if slash_idx != -1:
                        authority = rest[:slash_idx]
                        path_query = rest[slash_idx:]
                        split_idx = path_query.find('?')
                        if split_idx != -1:
                            path = path_query[:split_idx]
                            query = path_query[split_idx+1:]
                        else:
                            path = path_query
                            query = ''
                        return (scheme, authority, path, query)
                    else:
                        split_idx = rest.find('?')
                        if split_idx != -1:
                            authority = rest[:split_idx]
                            query = rest[split_idx+1:]
                            path = ''
                        else:
                            authority = rest
                            path = ''
                            query = ''
                        return (scheme, authority, path, query)
                else:
                    # no authority, rest is path (and maybe query)
                    split_idx = rest.find('?')
                    if split_idx != -1:
                        path = rest[:split_idx]
                        query = rest[split_idx+1:]
                    else:
                        path = rest
                        query = ''
                    return (scheme, '', path, query)
    return ('', '', url, '')

