# for the given patterns. Let's hard-code the translation function.

# The standard fnmatch.translate in Python does the following (simplified):
# - Converts a glob pattern into a regex string with '($' appended
# - Handles *, ?, [..], [!..] etc.

# Let's implement a faithful replica of fnmatch.translate.

def translate(pat):
    # This is a faithful reimplementation of CPython's fnmatch.translate
    i = 0
    n = len(pat)
    res = ''
    while i < n:
        c = pat[i]
        i = i + 1
        if c == '*':
            res = res + '.*'
        elif c == '?':
            res = res + '.'
        elif c == '[':
            j = i
            if j < n and pat[j] == '!':
                j = j + 1
            if j < n and pat[j] == ']':
                j = j + 1
            while j < n and pat[j] != ']':
                j = j + 1
            if j >= n:
                res = res + '\\['
            else:
                stuff = pat[i:j]
                i = j + 1
                if not stuff:
                    res += '\\]'
                else:
                    if stuff[0] == '!':
                        stuff = '^' + stuff[1:]
                    elif stuff[0] in ('^', '['):
                        stuff = '\\' + stuff
                    res = '[%s]' % stuff
        else:
            res = re_escape(c)
    return '(?s:%s)$' % res

def re_escape(c):
    return '\\' + c if c in r'\^$.?*+[](){}|~!' else c

