import base64

ALPHA = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"


def b64decode_compat(s: bytes) -> bytes:
    # First, replicate the CPython 3.13 (and later) behaviour using the stdlib.
    try:
        return base64.b64decode(s)
    except Exception as e:
        exc_name = type(e).__name__
        msg = str(e)
        if not ("Invalid base64-encoded string" in msg or "Invalid padding" in msg):
            raise
        # Now emulate the pre-3.13 (3.11/3.12) semantics manually.
        pad_idx = None
        for i, c in enumerate(s):
            ch = chr(c)
            if ch == '=':
                pad_idx = i
                break
            elif ch in ALPHA or ch in '\n\r\t ':
                continue
            else:
                raise Exception("binascii.Error: Invalid base64-encoded string: number of data characters (0) cannot be 1 more than a multiple of 4")
        if pad_idx is None:
            # No padding but invalid trailing count? Replicate with plain call; handled above already.
            pass
        data_part = s[:pad_idx]
        tail = s[pad_idx:]
        # Remove whitespace from data and padding
        def strip_ws(bs):
            out = bytearray()
            for c in bs:
                ch = chr(c)
                if ch not in '\n\r\t ':
                    out.append(c)
            return bytes(out)
        data_clean = strip_ws(data_part)
        tail_clean = strip_ws(tail)
        pads_after = tail_clean.count(b'=')
        alphas_after = len(tail_clean) - pads_after
        # Pre-3.13 rule: after the first '=', only spaces allowed (no alphabet chars).
        if alphas_after > 0:
            raise Exception(
                "binascii.Error: Invalid base64-encoded string: number of data characters ({} ) cannot be 1 more than a multiple of 4".format(len(data_clean))
            )
        # Check quad structure of data_clean
        n = len(data_clean)
        if n % 4 == 0:
            # expect zero pads
            expected_pads = 0
        elif n % 4 == 2:
            expected_pads = 2
        elif n % 4 == 3:
            expected_pads = 1
        else:  # n % 4 == 1
            raise Exception("binascii.Error: Incorrect padding")
        if pads_after != expected_pads:
            raise Exception("binascii.Error: Incorrect padding")
        full = data_clean + b'=' * expected_pads
        return _b64_decode_strict(full)


