def _b64_decode_strict(buf: bytes) -> bytes:
    # buf contains only alphabet chars and '='; no whitespace.
    n = len(buf)
    if n == 0:
        return b''
    if n % 4 != 0:
        raise Exception("binascii.Error: Incorrect padding")
    out = bytearray()
    for q in range(0, n, 4):
        quad = buf[q:q + 4]
        v = [0, 0, 0, 0]
        for k in range(4):
            b1 = quad[k:k + 1]
            if b1 == b'=':
                continue
            if b1 not in _VALS:
                raise Exception("binascii.Error: Non-base64 digit found")
            v[k] = _VALS[b1]
        bits = (v[0] << 18) | (v[1] << 12) | (v[2] << 6) | v[3]
        byte0 = (bits >> 16) & 0xFF
        byte1 = (bits >> 8) & 0xFF
        byte2 = bits & 0xFF
        if quad[3] == b'=':
            if quad[2] == b'=':
                out.append(byte0)
            else:
                out.append(byte0)
                out.append(byte1)
        else:
            out.append(byte0)
            out.append(byte1)
            out.append(byte2)
    return bytes(out)


