def b64decode_strict(s):
    if not isinstance(s, bytes):
        s = s.encode('ascii')
    # validate charset and padding position per strict rules
    alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    idx = {}
    for i, c in enumerate(alphabet):
        idx[c] = i
    pad_count = 0
    n = len(s)
    found_pad = False
    valid = []
    for i, ch in enumerate(s):
        o = ch
        if ch == 0x3d:  # '='
            if found_pad:
                raise ValueError("Invalid base64-encoded string: number of data characters ({}), is a multiple of 4 but padded incorrectly".format(i))
            # allow up to two pads; pads only at end
            valid.append(o)
            found_pad = True
            continue
        else:
            if found_pad:
                raise ValueError("Incorrect padding")
            if o in idx:
                valid.append(o)
            else:
                # mimic binascii Error for bad character
                raise Exception("binascii.Error: Invalid base64-encoded string: the input contains non-alphabet characters")
    # check trailing length
    data_len = n - s.count(b'=')
    total = n
    # CPython raises: 'Invalid base64-encoded string: number of data characters (X), cannot be 1 more than a multiple of 4'
    if data_len % 4 == 1:
        raise Exception("binascii.Error: Invalid base64-encoded string: number of data characters (%d), cannot be 1 more than a multiple of 4" % data_len)
    # decode
    bits = []
    for ch in valid:
        if ch == 0x3d:
            break
        v = idx[ch]
        for j in range(5, -1, -1):
            bits.append((v >> j) & 1)
    # consume bits by 8
    out = bytearray()
    k = 0
    while k + 8 <= len(bits):
        byte = 0
        for j in range(8):
            byte = (byte << 1) | bits[k + j]
        out.append(byte)
        k += 8
    # leftover bits must be zero
    rem = len(bits) - k
    for j in range(rem):
        if bits[k + j] != 0:
            raise Exception("binascii.Error: Non-zero pad bits")
    return bytes(out)


