                    idx = B64_CHARS[c]
                    v = (v << 6) | idx
                # Number of output bytes: 4 input chars -> 3 bytes, but minus padding
                # For X=YY? No. For standard:
                # 4 valid chars -> 3 bytes
                # 3 valid + 1 pad -> 2 bytes
                # 2 valid + 2 pads -> 1 byte
                # 0 valid + 4 pads -> 0 bytes
                num_bytes = max(0, ((count * 6) - (eq_count * 6)) // 8)
                # Actually simpler: each char gives 6 bits. Total bits = count*6. Output bytes = floor(total_bits/8)
                total_bits = count * 6
                num_out = total_bits // 8
                val = v
                for k in range(num_out):
                    bit_pos = (num_out - 1 - k) * 8
                    byte_val = (val >> bit_pos) & 0xFF
                    decoded.append(byte_val)
            i += 4
    except Exception as e:
        # Let the original exception propagate naturally
        raise

    return bytes(decoded)


