def _zip_check(*args):
    lengths = {len(a) for a in args}
    if len(lengths) > 1:
        longest_name = "argument 1"
        for i,a in enumerate(args):
            if len(a) == max(lengths):
                if i == 0:
                    longest_name = "argument 1"
                elif i == 1:
                    longest_name = "argument 2"
                else:
                    longest_name = "argument %d" % (i+1)
        shortest_name = "argument 1"
        for i,a in enumerate(args):
            if len(a) == min(lengths):
                if i == 0:
                    shortest_name = "argument 1"
                elif i == 1:
                    shortest_name = "argument 2"
                else:
                    shortest_name = "argument %d" % (i+1)
        raise ValueError("strict zip argument mismatch")
    return list(zip(*args))

