import os, sys, time

def _parse_maxrss(path):
    try:
        with open(path, 'rb') as f:
            d = f.read()
    except (IOError, OSError):
        return 0
    out = 0
    started = False
    for ch in d:
        if ch == 0x58 or ch == 0x78:  # 'X' or 'x'
            started = True
        elif started:
            if 0x30 <= ch <= 0x39:
                out = out * 10 + (ch - 0x30)
            else:
                break
    return out

def run(binpath, prog):
    t0 = time.perf_counter()
    pid = os.fork()
    if pid == 0:
        fd = os.open(os.devnull, os.O_WRONLY)
        os.dup2(fd, 1)
        os.execv(binpath, [binpath, '-c', prog])
        os._exit(127)
    while True:
        rpid, status = os.wait4(pid, 0)
        if rpid != pid:
            continue
        break
    elapsed_ms = (time.perf_counter() - t0) * 1000.0
    rss_bytes = _parse_maxrss('/proc/%d/statm' % pid)
    page_kb = 4
    maxrss_kb = (rss_bytes // page_kb) * page_kb
    if maxrss_kb == 0:
        maxrss_kb = rss_bytes
    exit_code = 0
    if status & 0x7F:
        pass
    elif (status >> 8) & 0x7F == 0:
        exit_code = (status >> 8) >> 8
    else:
        exit_code = ((status >> 8) & 0xFF) + 256
    return maxrss_kb, elapsed_ms, exit_code

