    "dict-build":  "d={}\nfor i in range(200000):\n    d[str(i)]=i\nprint(len(d))",
    "churn-list":  "n=0\nfor i in range(200000):\n    a=[1,2,3,4]\n    n+=len(a)\nprint(n)",
    "big-concat":  "s=''\nfor i in range(20000):\n    s+='x'\nprint(len(s))",
}

