def only_set_order_differs(s1, s2):
    """Check if two strings represent the same set/dict with only order differing."""
    s1_stripped = s1.strip()
    s2_stripped = s2.strip()

    # Determine if it's a set or dict based on content
    is_dict = ':' in s1_stripped or ':' in s2_stripped

    if is_dict:
        # Parse as dict
        try:
            d1 = eval(s1_stripped)
            d2 = eval(s2_stripped)
        except:
            return False

        if not isinstance(d1, dict) or not isinstance(d2, dict):
            return False

        # Check if same keys and values but different order
        if list(d1.keys()) == list(d2.keys()):
            # Same order
            for k in d1:
                if d1[k] != d2[k]:
                    return False
            return False  # Same order means no difference at all

        if set(d1.keys()) == set(d2.keys()):
            for k in d1:
                if d1[k] != d2[k]:
                    return False
            return True

        return False
    else:
        # Parse as set
        try:
            set1 = eval(s1_stripped)
            set2 = eval(s2_stripped)
        except:
            return False

        if not isinstance(set1, set) or not isinstance(set2, set):
            return False

        # Check if same elements but different order
        if list(set1) == list(set2):
            return False  # Same order

        if set1 == set2:
            return True

        return False


