import sys

class conformance:
    @staticmethod
    def only_set_order_differs(s1, s2):
        import ast

        def parse_string(s):
            s = s.strip()
            if not s:
                return None
            try:
                # Try parsing as a set or dict literal
                result = ast.literal_eval(s)
                return result
            except (ValueError, SyntaxError):
                pass

            # Try converting to set by removing quotes around numbers
            if s.startswith('{') and s.endswith('}'):
                inner = s[1:-1]
                parts = [p.strip().strip("'\"") for p in inner.split(',')]
                try:
                    return set(int(p) for p in parts if p)
                except ValueError:
                    try:
                        return set(parts)
                    except Exception:
                        pass

            # Try as a tuple of key-value pairs for dict
            if s.startswith("{") and s.endswith("}") and ':' in s:
                inner = s[1:-1]
                parts = [p.strip() for p in inner.split(',') if p.strip()]
                d = {}
                try:
                    for p in parts:
                        if ':' in p:
                            k, v = p.split(':', 1)
                            k = k.strip().strip("'\"")
                            v = v.strip().strip("'\"")
                            d[k] = v
                    return d
                except Exception:
                    pass

            return None

        obj1 = parse_string(s1)
        obj2 = parse_string(s2)

        # Check if they are the same as sets (for dict case, check keys/values)
        if isinstance(obj1, dict) and isinstance(obj2, dict):
            if obj1 == obj2:
                return True
            # Check if just order differs
            items1 = list(obj1.items())
            items2 = list(obj2.items())
            return sorted(items1) == sorted(items2)

        if isinstance(obj1, set) and isinstance(obj2, set):
            if obj1 == obj2:
                return True
            return False

        # Fallback: compare string representations ignoring whitespace
        norm1 = ''.join(ch for ch in s1 if not ch.isspace())
        norm2 = ''.join(ch for ch in s2 if not ch.isspace())
        return norm1 == norm2

