def only_set_order_differs(s1, s2):
    """Check if two strings differ only in the order of elements within a set/dict-like structure."""
    # Parse both strings as Python literals
    try:
        obj1 = eval(s1)
        obj2 = eval(s2)
    except Exception:
        return False

    # Check if they have the same elements (same set)
    if isinstance(obj1, dict) and isinstance(obj2, dict):
        if set(obj1.keys()) != set(obj2.keys()):
            return False
        if len(obj1) != len(obj2):
            return False
        for k in obj1:
            if k not in obj2 or obj1[k] != obj2[k]:
                return False
        return True
    elif isinstance(obj1, set) and isinstance(obj2, set):
        return obj1 == obj2
    elif isinstance(obj1, list) and isinstance(obj2, list):
        if set(map(str, obj1)) != set(map(str, obj2)):
            return False
        return True
    else:
        # Try to see if they're collections
        try:
            if set(list(obj1)) == set(list(obj2)):
                return True
            return False
        except Exception:
            return False


