def only_set_order_differs(s1, s2):
    import ast

    try:
        val1 = ast.literal_eval(s1)
        val2 = ast.literal_eval(s2)
    except Exception:
        return False

    if isinstance(val1, (set, frozenset)) and isinstance(val2, (set, frozenset)):
        return val1 == val2 and list(s1.strip()) != list(s2.strip())
    elif isinstance(val1, dict) and isinstance(val2, dict):
        if set(val1.keys()) != set(val2.keys()):
            return False
        for k in val1:
            if val1[k] != val2.get(k):
                return False
        # Check that order differs
        keys1 = list(val1.keys())
        keys2 = list(val2.keys())
        return keys1 != keys2
    else:
        return False

