import re

def only_set_order_differs(s1, s2):
    """Check if two strings represent the same set or dict (only order differs)."""
    s1 = s1.strip()
    s2 = s2.strip()

    # Check if it's a set literal: {elem, elem, ...} without colons indicating key-value pairs
    # Or dict literal: {'key': value, ...}

    # Remove surrounding braces
    inner1 = s1[1:-1].strip() if s1.startswith('{') and s1.endswith('}') else s1
    inner2 = s2[1:-1].strip() if s2.startswith('{') and s2.endswith('}') else s2

    if not inner1 or not inner2:
        return s1 == s2

    # Try to parse as dict: check for colon-separated key-value pairs
    # A dict has entries like 'key': value
    # We need to be careful with nested structures, but for simplicity, let's try to split by commas at top level

    def split_top_level(s):
        """Split string by commas, respecting quotes and brackets."""
        parts = []
        current = []
        in_string = False
        string_char = None
        depth = 0

        for c in s:
            if in_string:
                current.append(c)
                if c == string_char and (not current[-2:-1] or current[-2] != '\\'):
                    in_string = False
            else:
                if c in ('"', "'"):
                    in_string = True
                    string_char = c
                    current.append(c)
                elif c in '{[':
                    depth += 1
                    current.append(c)
                elif c in '}]':
                    depth -= 1
                    current.append(c)
                elif c == ',' and depth == 0:
                    parts.append(''.join(current))
                    current = []
                else:
                    current.append(c)

        if current:
            parts.append(''.join(current))

        return [p.strip() for p in parts if p.strip()]

    items1 = split_top_level(inner1)
    items2 = split_top_level(inner2)

    if len(items1) != len(items2):
        return False

    # Check if these look like dict entries (have a colon separating key and value)
    # For each item, check if it contains a colon that separates key from value
    is_dict = any(
        ':' in item and (item.find(':') > 0) 
        for item in items1
    )

    if is_dict:
        # Parse as dict: extract keys
        keys1 = []
        keys2 = []
        for item in items1:
            idx = item.find(':')
            if idx != -1:
                keys1.append(item[:idx].strip())
            else:
                keys1.append(item)
        for item in items2:
            idx = item.find(':')
            if idx != -1:
                keys2.append(item[:idx].strip())
            else:
                keys2.append(item)

        # Compare sorted keys
        return sorted(keys1) == sorted(keys2)
    else:
        # Compare as sets: sort the elements
        return sorted(items1) == sorted(items2)


