def view_equal(v1, v2):
    if v1 is v2:
        return True
    try:
        a = list(v1)
    except TypeError:
        # Not comparable by identity (dict-views); CPython returns NotImplemented -> False
        return False
    if len(a) != len(v2):
        return False
    for x in a:
        if x not in v2:
            return False
    return True

