import os, sys

def _to_val(s):
    s = s.strip()
    if s == 'true': return True
    if s == 'false': return False
    if s == 'null': return None
    if len(s) >= 2 and s[0] == '"' and s[-1] == '"':
        body = s[1:-1]
        out = []
        i = 0
        while i < len(body):
            c = body[i]
            if c == '\\':
                if i + 1 < len(body):
                    nxt = body[i + 1]
                    m = {'"': '"', '\\': '\\', '/': '/', 'b': '\b', 'f': '\f', 'n': '\n', 'r': '\r', 't': '\t'}
                    if nxt in m:
                        out.append(m[nxt]); i += 2; continue
                    if nxt == 'u' and i + 5 < len(body):
                        try:
                            out.append(chr(int(body[i+2:i+6], 16)))
                            i += 6; continue
                        except Exception:
                            pass
                i += 1; continue
            out.append(c); i += 1
        return ''.join(out)
    try:
        return int(s)
    except Exception:
        pass
    try:
        return float(s)
    except Exception:
        pass
    return s

def parse_value(text, i):
    while i < len(text) and text[i] in ' \t\r\n':
        i += 1
    if i >= len(text):
        return None, i
    c = text[i]
    if c == '{':
        obj = {}
        i += 1
        while i < len(text) and text[i] in ' \t\r\n':
            i += 1
        if i < len(text) and text[i] == '}':
            return obj, i + 1
        while i < len(text):
            while i < len(text) and text[i] in ' \t\r\n':
                i += 1
            if i >= len(text): break
            k, i = parse_value(text, i)
            while i < len(text) and text[i] in ' \t\r\n':
                i += 1
            if i < len(text) and text[i] == ':':
                i += 1
            v, i = parse_value(text, i)
            obj[k] = v
            while i < len(text) and text[i] in ' \t\r\n':
                i += 1
            if i < len(text) and text[i] == ',':
                i += 1
            elif i < len(text) and text[i] == '}':
                i += 1
                break
            else:
                break
        return obj, i
    if c == '[':
        arr = []
        i += 1
        while i < len(text) and text[i] in ' \t\r\n':
            i += 1
        if i < len(text) and text[i] == ']':
            return arr, i + 1
        while i < len(text):
            v, i = parse_value(text, i)
            arr.append(v)
            while i < len(text) and text[i] in ' \t\r\n':
                i += 1
            if i < len(text) and text[i] == ',':
                i += 1
            elif i < len(text) and text[i] == ']':
                i += 1
                break
            else:
                break
        return arr, i
    if c == '"':
        j = i + 1
        buf = []
        while j < len(text):
            cc = text[j]
            if cc == '\\' and j + 1 < len(text):
                buf.append(cc); buf.append(text[j + 1])
                j += 2; continue
            if cc == '"':
                s = '"' + ''.join(buf) + '"'
                return _to_val(s), j + 1
            buf.append(cc); j += 1
        return None, j
    j = i
    while j < len(text) and text[j] not in ' \t\r\n,}]':
        j += 1
    token = text[i:j]
    return _to_val(token), j

def get(obj, key):
    if isinstance(obj, dict) and key in obj:
        return obj[key]
    return None

