def _compute(label):
    if label == 'universal':
        nl = None
    elif label == 'raw':
        nl = ''
    else:
        nl = '\n'
    content = b'a\rb\r\nc\n'
    result = []
    i = 0
    n = len(content)
    while True:
        start = i
        line_end = -1
        if nl is None:
            for k in range(i, n):
                c = content[k]
                if c == 0x0D or c == 0x0A:
                    line_end = k + 1
                    break
            if line_end == -1:
                if i >= n:
                    break
                out_b = bytearray(content[i:])
                if out_b[-1] == 0x0D and i + 2 <= n and content[i + 1] == 0x0A:
                    out_b.append(0x0A)
                ln_bytes = bytes(out_b)
                i = n
            else:
                chunk = content[i:line_end]
                if chunk[0] == 0x0D and len(chunk) == 1:
                    ln_bytes = chunk + b'\n'
                    i = line_end
                else:
                    ln_bytes = chunk
                    i = line_end
        elif nl == '':
            if i >= n:
                break
            line_end = n
            ln_bytes = content[i:]
            i = n
        else:
            for k in range(i, n):
                if content[k] == 0x0A:
                    line_end = k + 1
                    break
            if line_end == -1:
                if i >= n:
                    break
                ln_bytes = content[i:]
                i = n
            else:
                ln_bytes = content[i:line_end]
                i = line_end
        repr_str = repr(ln_bytes.decode('latin-1'))
        result.append((repr_str, i))
    return (label, result)


