def tell_before_read(f, line_len, last_byte):
    if not line_len:
        return None
    if line_len > 1 and last_byte != '\r':
        return f.tell()
    try:
        c = f.peek(line_len + 8)
    except Exception:
        return None
    if line_len == 1:
        return f.tell()
    more = c[1:]
    if not more:
        return None
    ch = more[0]
    if ch == '\n' or ch == '':
        return f.tell() - 1
    if ch == '\r':
        idx = more.find('\n', 1)
        if idx == -1:
            return None
        return f.tell() + (line_len + 1)
    return f.tell()

