import base64

def b64decode_compat(s):
    # Reproduce the behaviour of CPython 3.12 (and 3.11) for b64decode on bytes input:
    # stop at the first padding '=' character and ignore everything after it.
    s = s.replace(b'\r', b'').replace(b'\n', b'')
    # Strip whitespace like base64 does; also drop any other whitespace
    import re
    s = re.sub(rb'\s+', b'', s)
    pad_index = s.find(b'=')
    if pad_index != -1:
        trimmed = s[:pad_index]
    else:
        trimmed = s
    return base64.b64decode(trimmed)

