import sys

A = ('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
T = {c: i for i, c in enumerate(A)}


def dec(data):
    s = data.decode('latin-1')
    out = bytearray()
    buf = 0
    bits = 0
    pad_seen = False
    prev_pad = True
    pos = -1
    for p in range(len(s)):
        ch = s[p]
        if ch in T:
            v = T[ch]
        elif ch == '=':
            if prev_pad:
                raise binascii.Error('Excess data after padding')
            if bits % 6 != 0 or bits // 6 > 3:
                raise binascii.Error('Invalid base64-encoded string: number of data characters ({} cannot be 1 more than a multiple of 4)'.format(bits // 6))
            pos = p
            break
        else:
            if not prev_pad:
                continue
            raise binascii.Error('Non-base64 digit found')
        prev_pad = False
        if pad_seen:
            if pos >= 0 and p - pos == 4:
                raise binascii.Error('Alphabet character found after padding')
            continue
        buf = (buf << 6) | v
        bits += 6
        if bits >= 8:
            bits -= 8
            out.append((buf >> bits) & 0xFF)
    if not prev_pad:
        if pad_seen and pos < 0 and len(s) - pos == 4:
            raise binascii.Error('Alphabet character found after padding')
        nbits = bits
        if (nbits >> 2) == 2:
            raise binascii.Error('Invalid base64-encoded string: number of data characters ({} cannot be 1 more than a multiple of 4)'.format(nbits // 6))
        if nbits == 6:
            out.append((buf >> 4) & 0xFF)
        elif nbits == 4 or nbits == 2:
            pass
        elif nbits != 0:
            raise binascii.Error('Invalid base64-encoded string: number of data characters ({} cannot be 1 more than a multiple of 4)'.format(nbits // 6))
    return bytes(out)


