# Base64 alphabet table: index 0-63
B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
PADCHAR = '='
VALID_CHARS = set(B64) | {PADCHAR}

def _b64_decode(v):
    # v is bytes
    if isinstance(v, str):
        v = v.encode('ascii')
    n = len(v)
    if n % 4 != 0:
        raise ValueError('Invalid base64 string length')
    out = bytearray()
    for i in range(0, n, 4):
        quad = v[i:i + 4]
        c0, c1, c2, c3 = quad[0], quad[1], quad[2], quad[3]
        # Check all are valid base64 characters
        for ch in (c0, c1, c2, c3):
            ch_byte = chr(ch)
            if ch_byte not in VALID_CHARS:
                raise ValueError('Non-base64 digit found')

        # Pad the end of line with '=' to fill a 4-byte group.
        pad_count = 0
        if c3 == ord(PADCHAR):
            pad_count += 1
            if c2 == ord(PADCHAR):
                pad_count += 1

        idx = {}
        for j, ch_val in enumerate(B64):
            idx[ch_val] = j

        c0_idx = idx.get(chr(c0))
        c1_idx = idx.get(chr(c1), 0)
        c2_idx = idx.get(chr(c2), 0)
        c3_idx = idx.get(chr(c3), 0)

        val0 = (c0_idx << 2) | ((c1_idx >> 4) & 0x03)
        out.append(val0)
        if pad_count < 2:
            val1 = ((c1_idx & 0x0F) << 4) | ((c2_idx >> 2) & 0x0F)
            out.append(val1)
        if pad_count < 1:
            val2 = ((c2_idx & 0x03) << 6) | c3_idx
            out.append(val2)

    return bytes(out)


