import base64

def decode_b64(data, validate=False):
    if validate:
        raise ValueError("not supported")
    pad = len(data) % 4
    if pad == 1:
        raise ValueError("Invalid base64 data (padding)")
    # emulate the "stop at padding" behavior that CPython 3.11/3.12 have
    # so that a character after the '=' closing a quad is not read
    # find where the first '=' occurs; truncate the input up to and including
    # that padding character if it falls on a multiple of 4 boundary? 
    # Actually the rule in older versions: b64decode processes quads and stops
    # once padding is encountered; characters after padding are ignored.
    s = bytes(data)
    idx = s.find(b'=')
    if idx != -1:
        s = s[:idx + 1]
    return base64.b64decode(s)

