def compile_pattern(pattern):
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '[':
            j = i + 1
            negate = False
            if j < n and pattern[j] in '!^':
                negate = True
                j += 1
            if j < n and pattern[j] == ']':
                j += 1
            while j < n and pattern[j] != ']':
                j += 1
            if j >= n:
                i += 1
                continue
            content = pattern[i+1:j]
            classes = []
            k = 0
            cl = len(content)
            while k < cl:
                cc = content[k]
                if k + 2 < cl and content[k+1] == '-' and not (content[k+2] == ']' and k+3 >= cl):
                    start = cc
                    end = content[k+2]
                    classes.append((ord(start), ord(end)))
                    k += 3
                else:
                    if cc in r'\[]^-!':
                        classes.append((ord(cc), ord(cc)))
                    else:
                        classes.append((ord(cc), ord(cc)))
                    k += 1
            i = j + 1
            yield ('class', negate, classes)
        elif c == '*':
            # collapse consecutive stars
            while i + 1 < n and pattern[i+1] == '*':
                i += 1
            i += 1
            yield ('star', None, None)
        elif c == '?':
            i += 1
            yield ('any', None, None)
        else:
            i += 1
            yield ('lit', c, None)


