def match(name, pat):
    n = len(name); m = len(pat)
    # dp[i][j] = whether name[i:] matches pat[j:]
    dp = [[False]*(m+1) for _ in range(n+1)]
    dp[n][m] = True
    # Fill backwards
    for i in range(n-1, -1, -1):
        for j in range(m-1, -1, -1):
            c = pat[j]
            if c == '*':
                # name[i:] matches pat[j+1:] OR (name[i:] nonempty-ish: star eats char) -> dp[i+1][j]
                dp[i][j] = dp[i][j+1] or dp[i+1][j]
            elif c == '?':
                dp[i][j] = dp[i+1][j+1]
            elif c == '[':
                # find matching ]
                k = j + 1
                negate = False
                if k < m and pat[k] == '!':
                    negate = True; k += 1
                # scan until closing ]
                end = -1
                kk = k
                while kk < m:
                    if pat[kk] == ']':
                        end = kk; break
                    kk += 1
                if end == -1:
                    # unclosed bracket, treat as literal? In fnmatch it's literal? Actually Python fnmatch treats unclosed as error/none. But our patterns are well-formed. Fallback: treat '[' literally.
                    dp[i][j] = dp[i+1][j+1] if i < n and name[i] == '[' else False
                else:
                    seq = list(pat[k:end])
                    # interpret ranges
                    matched = False
                    ch = name[i]
                    idx = 0
                    while idx < len(seq):
                        if idx+2 < len(seq) and seq[idx+1] == '-':
                            lo, hi = seq[idx], seq[idx+2]
                            if lo <= ch <= hi:
                                matched = True; break
                            idx += 3
                        else:
                            if seq[idx] == ch:
                                matched = True; break
                            idx += 1
                    if negate:
                        matched = not matched
                    dp[i][j] = matched and dp[i+1][j+1] if i < n else False
            else:
                dp[i][j] = dp[i+1][j+1] if i < n and name[i] == c else False
    return dp[0][0]


