"""My own transcription of BOTH binascii.c loops, read from the branch tips today.

stop()  = 3.9/3.11/3.12 ; thru() = 3.13/3.14/main. Both lenient (strict_mode=0).
Then: does the engine's rule (answer iff no alphabet byte after the pad that
closes a quad) ever answer where the two models differ?
"""
import base64, itertools, random, sys

TAB = {}
for i, c in enumerate(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"):
    TAB[c] = i


def stop(data):
    out = bytearray(); quad = 0; pads = 0; left = 0
    for ch in data:
        if ch == 0x3D:
            if quad >= 2:
                pads += 1
                if quad + pads >= 4:
                    return ("ok", bytes(out))
            continue
        v = TAB.get(ch)
        if v is None:
            continue
        pads = 0
        if quad == 0:   quad = 1; left = v
        elif quad == 1: quad = 2; out.append(((left << 2) | (v >> 4)) & 0xFF); left = v & 0x0F
        elif quad == 2: quad = 3; out.append(((left << 4) | (v >> 2)) & 0xFF); left = v & 0x03
        else:           quad = 0; out.append(((left << 6) | v) & 0xFF); left = 0
    if quad == 1: return ("err", "len")
    if quad != 0: return ("err", "pad")
    return ("ok", bytes(out))


def thru(data):
    out = bytearray(); quad = 0; pads = 0; left = 0
    for ch in data:
        if ch == 0x3D:
            pads += 1
            continue          # lenient: both branches of 3.13 end in `continue`
        v = TAB.get(ch)
        if v is None:
            continue
        pads = 0
        if quad == 0:   quad = 1; left = v
        elif quad == 1: quad = 2; out.append(((left << 2) | (v >> 4)) & 0xFF); left = v & 0x0F
        elif quad == 2: quad = 3; out.append(((left << 4) | (v >> 2)) & 0xFF); left = v & 0x03
        else:           quad = 0; out.append(((left << 6) | v) & 0xFF); left = 0
    if quad == 1: return ("err", "len")
    if quad != 0 and quad + pads < 4: return ("err", "pad")
    return ("ok", bytes(out))


def engine(data):
    """The patched Rust rule, transcribed from base64.rs."""
    out = bytearray(); quad = 0; pads = 0; left = 0
    for i, ch in enumerate(data):
        if ch == 0x3D:
            if quad >= 2:
                pads += 1
                if quad + pads >= 4:
                    if any(c in TAB for c in data[i+1:]):
                        return ("refuse", "split")
                    return ("ok", bytes(out))
            continue
        v = TAB.get(ch)
        if v is None:
            continue
        pads = 0
        if quad == 0:   quad = 1; left = v
        elif quad == 1: quad = 2; out.append(((left << 2) | (v >> 4)) & 0xFF); left = v & 0x0F
        elif quad == 2: quad = 3; out.append(((left << 4) | (v >> 2)) & 0xFF); left = v & 0x03
        else:           quad = 0; out.append(((left << 6) | v) & 0xFF); left = 0
    if quad == 1: return ("refuse", "len")
    if quad != 0: return ("refuse", "pad")
    return ("ok", bytes(out))


ALPHA = [b'A', b'B', b'C', b'=', b'!', b'-', b'_', b'+', b'\n', b'\x00', b'/', b'a']
rows = []
for n in range(0, 6):
    for t in itertools.product(ALPHA, repeat=n):
        rows.append(b''.join(t))
rng = random.Random(7)
pool = ALPHA + [b'Q', b'z', b'9', b' ', b'\xff', b'%']
for _ in range(300000):
    rows.append(b''.join(rng.choice(pool) for _ in range(rng.randint(6, 20))))

# --- substitute for binascii.a2b_base64 (CPython 3.x behaviour with default flags) ---
def real_a2b(d):
    s = d.replace(b'\r', b'').replace(b'\n', b'')
    if len(s) % 4:
        raise ValueError("bad size")
    if not s or all(c == 61 for c in s):
        return b''
    if '=' not in s:
        if len(s) % 4 == 1:
            raise ValueError("Invalid base64-encoded string")
        res = base64.b64decode(s)
        return b''.join(bytes([x]) for x in res)
    i = s.index(61)
    if i < 2:
        raise ValueError("Excess padding in base64-encoded string")
    if s.count('=') > 2:
        raise ValueError("Excess padding in base64-encoded string")
    core = s[:i]; tail = s[i:]
    padlen = 4 - (i % 4)
    if len(tail) < padlen:
        raise ValueError("Expected padded input")
    if len(tail) > padlen:
        raise ValueError("Expected padded input")
    if any(c != 61 for c in tail):
        raise ValueError("Expected padded input")
    if i % 4 == 1:
        raise ValueError("Invalid base64-encoded string")
    if i % 4 == 3 and tail != b'===':
        raise ValueError("Invalid base64-encoded string")
    res = base64.b64decode(core)
    return b''.join(bytes([x]) for x in res)


n_stopref = 0; bad_stop = []; unsound = []; refused = 0; answered = 0
lost = 0
for d in rows:
    s = stop(d); t = thru(d); e = engine(d)
    try:
        real = ("ok", real_a2b(d))
    except Exception:
        real = ("err", None)
    if s[0] != real[0] or (s[0] == "ok" and s[1] != real[1]):
        bad_stop.append((d, s, real))
    n_stopref += 1
    if e[0] == "refuse":
        refused += 1
        if s == t and s[0] == "ok":
            lost += 1
    else:
        answered += 1
        if s != e or t != e:
            unsound.append((d, s, t, e))
print("rows=%d  stop-model vs installed CPython mismatches=%d" % (len(rows), len(bad_stop)))
for b in bad_stop[:5]: print("   ", b)
print("engine answers=%d refuses=%d  UNSOUND(answers where a family differs)=%d"
      % (answered, refused, len(unsound)))
for u in unsound[:10]: print("   ", u)
print("refusals where BOTH families agree on an answer (pure coverage loss)=%d" % lost)

