def product(iterables):
    """Generate Cartesian product of iterables, like itertools.product."""
    pools = [list(pool) for pool in iterables]
    result = [[]]
    for pool in pools:
        new_result = []
        for prefix in result:
            for x in pool:
                new_result.append(prefix + [x])
        result = new_result
    return result

def product_repeat(items, n):
    """Generate product of items repeated n times."""
    if n == 0:
        yield ()
        return
    for first in items:
        for rest in product_repeat(items, n - 1):
            yield (first,) + rest

