def _b64_decode(s):
    s = bytes(s)
    if b'=' in s:
        eq_pos = s.find(b'=')
        if any(ch != ord('=') for ch in s[eq_pos:]):
            raise ValueError('Invalid base64-encoded string: number of data characters (2) cannot be 1 more than a multiple of 4')
        if not s.endswith(b'=='):
            pad_count = len(s) - len(s.rstrip(b'='))
            if pad_count > 2:
                raise binascii.Error('Invalid base64-encoded string: number of data characters %d cannot be 1 more than a multiple of 4' % len(s.rstrip(b'=')))
    for i, ch in enumerate(s):
        c = chr(ch)
        if c == '\n' or c == '\r':
            continue
        if c not in 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=':
            raise binascii.Error('Non-base64 digit found')
    # Now use base64 module for actual decoding
    return base64.b64decode(s, validate=True)

