def get(obj, key, default=None):
    try:
        if hasattr(obj, '__getitem__'):
            return obj[key]
    except Exception:
        pass
    try:
        v = getattr(obj, key)
        return v
    except AttributeError:
        return default

def is_nondeterministic(prog_or_obj):
    # Try to obtain the program string
    prog = None
    p = get(prog_or_obj, 'program', None)
    if isinstance(p, str):
        prog = p
