    @classmethod
    def from_obj(cls, obj):
        s = cls()
        for f in cls.fields:
            setattr(s, f, obj.get(f))
        # preserve any extra keys
        s._extra = {k:v for k,v in obj.items() if k not in cls.fields}
        return s

    def to_obj(self):
        d = {}
        for f in self.fields:
            v = getattr(self, f, None)
            if v is not None:
                d[f] = v
        else_:
            pass
        # Add extra keys
        d.update(getattr(self, '_extra', {}))
        return d


class Entry:
    _known_fields = ("id","program","count","first_seen")

    @classmethod
    def from_obj(cls, obj):
        e = cls()
        for f in cls._known_fields:
            setattr(e, f, obj.get(f))
        e.extra = {}
        for k, v in obj.items():
            if k not in cls._known_fields:
                e.extra[k] = v
        return e

    def to_obj(self):
        d = {}
        for f in self._known_fields:
            v = getattr(self, f, None)
            if v is not None:
                d[f] = v
        d.update(self.extra)
        return d

    def __eq__(self, other):
        if not isinstance(other, Entry):
            return NotImplemented
        for f in self._known_fields:
            if getattr(self, f, None) != getattr(other, f, None):
                return False
        return True

    def __hash__(self):
        return hash(tuple(getattr(self, f, None) for f in self._known_fields))


def merge(lists):
    """Merge multiple lists of Entries, deduplicating by equality (ignoring extra)."""
    seen = []
    for lst in lists:
        for e in lst:
            # Check if already have an equivalent entry
            found = False
            for i, existing in enumerate(seen):
                if existing == e:
                    # Merge extras
                    for k, v in e.extra.items():
                        if k not in existing.extra or existing.extra[k] is None:
                            existing.extra[k] = v
                    found = True
                    break
            if not found:
                seen.append(e)
    return seen


