def _is_file(path):
    try:
        st = os.stat(path)
    except OSError:
        return False
    # S_ISREG approximation using mode constants via os.path? Not available; use fstat-like check.
    # We only have os.path and no stat module import allowed beyond os/sys per constraint ("no imports beyond os and sys").
    # So approximate regular file via os.path.isfile semantics but isfile internally does stat. That's fine.
    return (st.st_mode & 0o170000) == 0o100000  # S_IFREG


def _iter_jsonl_in_dir(dirpath):
    """Yield full paths of files in dirpath matching *.jsonl, in sorted order for determinism."""
    names = []
    try:
