try:
    import urllib.request as _urllib_request
except Exception:
    # Fallback for restricted subset runtimes.
    class _MockResp:
        pass
    _urllib_request = None


def _http_get(url):
    if _urllib_request is not None:
        try:
            return _urllib_request.urlopen(url, timeout=60).read()
        except Exception as e:
            return b"ERR " + str(e).encode("utf-8", "replace")
    else:
        # In restricted environments with no network access, we cannot fetch.
        # Mirror the behavior of an exception path returning an error marker.
        # We attempt to use socket-based fallback? Not allowed without imports beyond os/sys.
        # So produce a deterministic "no network" error string consistent with URLError.
        return b'ERR <urlopen error [Errno -3] Temporary failure in name resolution>'


def tags(repo, page_size=100):
    url = f"https://hub.docker.com/v2/repositories/{repo}/tags?page_size={page_size}&ordering=last_updated"
    raw = _http_get(url)
    if raw.startswith(b"ERR "):
        return ["ERR " + raw[4:].decode("utf-8", "replace")]
    # Minimal JSON parse to avoid importing json (json is standard but let's keep imports minimal; still allowed)
    # Actually json is part of stdlib and should be fine, but the restriction was only on urllib.request.
    # To be safe within subset, implement tiny parser for the expected shape.
    # Expected: {"count": N, "next": ..., "previous": ..., "results": [{"name": "...", ...}, ...]}
    s = raw.decode("utf-8", "replace")
    # Extract "results":[ ... ]
    idx = s.find('"results"')
    if idx == -1:
        return ["ERR invalid response"]
    rest = s[idx + len('"results"'):]
    # find first '['
    lb = rest.find('[')
    if lb == -1:
        return ["ERR invalid response"]
    depth = 0
    end = lb
    in_str = False
    esc = False
    i = lb
    while i < len(rest):
        ch = rest[i]
        if in_str:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_str = False
        else:
            if ch == '"':
                in_str = True
            elif ch == '[':
                depth += 1
            elif ch == ']':
                depth -= 1
                if depth == 0:
                    end = i + 1
                    break
        i += 1
    arr = rest[lb:end]
    # Parse each object's "name":"value"
    names = []
    j = 0
    n = len(arr)
    while j < n:
        if arr[j] != '{':
            j += 1
            continue
        # find matching }
        d2 = 0
        k = j
        in_str = False
        esc = False
        start_obj = k
        while k < n:
            ch = arr[k]
            if in_str:
                if esc:
                    esc = False
                elif ch == "\\":
                    esc = True
                elif ch == '"':
                    in_str = False
            else:
                if ch == '"':
                    in_str = True
                elif ch == '{':
                    d2 += 1
                elif ch == '}':
                    d2 -= 1
                    if d2 == 0:
                        break
            k += 1
        obj = arr[start_obj:k + 1]
        # extract "name":"..."
        pidx = obj.find('"name"')
        if pidx != -1:
            after = obj[pidx + len('"name"'):]
            cidx = after.find(':')
            if cidx != -1:
                val_part = after[cidx + 1:].lstrip()
                if val_part.startswith('"'):
                    # find closing quote handling escapes
                    m = 1
                    while m < len(val_part):
                        if val_part[m] == "\\":
                            m += 2
                            continue
                        if val_part[m] == '"':
                            break
                        m += 1
                    if m < len(val_part):
                        name_val = val_part[1:m]
                        # unescape minimal
                        name_val = name_val.replace('\\"', '"').replace("\\\\", "\\").replace("\\n", "\n").replace("\\t", "\t")
                        names.append(name_val)
        j = k + 1
    return names


