def simulate_eval(prog):
    """Return (result, None) if success, (None, (exc_type_name, str)) on exception."""
    # "min()" -> TypeError: 'type' object is not subscriptable? No, min() requires at least one argument or an iterable.
    # In Python 3, min() with no args raises TypeError: min expected at least 1 argument, got 0
    # max() similarly.
    # min(default=1) -> returns 1? No, default only applies when sequence is empty but you still need a sequence.
    # Actually in Python 3.4+, you can do min(iterable, key=None, *[, default]) - but you need the first arg.
    # So min(default=1) raises TypeError: min expected at least 1 positional argument, got 0
    # max(key=len) similar issue.
    # min(*[]) -> min() with no args -> TypeError

    # Let me check actual behavior:
    # min() -> TypeError: min expected at least 1 argument, got 0
    # max() -> TypeError: max expected at least 1 argument, got 0  
    # min(default=1) -> TypeError: min expected at least 1 positional argument, got 0
    # max(key=len) -> TypeError: max expected at least 1 positional argument, got 0
    # min(*[]) -> TypeError: min expected at least 1 argument, got 0

    if prog == "min()":
        return None, ("TypeError", "min expected at least 1 argument, got 0")
    elif prog == "max()":
        return None, ("TypeError", "max expected at least 1 argument, got 0")
    elif prog == "min(default=1)":
