    elif prog == "max(key=len)":
        return None, ("TypeError", "max expected at least 1 positional argument, got 0")
    elif prog == "min(*[])":
        return None, ("TypeError", "min expected at least 1 argument, got 0")
    else:
        raise ValueError("unknown program: " + repr(prog))

