import ast

def parse_and_evaluate(src):
    # We need to handle specific cases without eval
    # Parse the source with ast to understand what's being called
    tree = ast.parse(src, mode='eval')

    class Evaluator(ast.NodeVisitor):
        def visit_Expression(self, node):
            return self.visit(node.body)

        def visit_Call(self, node):
            if not isinstance(node.func, ast.Name):
                raise ValueError("Unsupported call")

            func_name = node.func.id

            if func_name == 'min':
                args = [self.evaluate_arg(arg) for arg in node.args]
                kwargs = {kw.arg: self.evaluate_arg(kw.value) for kw in node.keywords}

                if 'default' in kwargs and not args:
                    return kwargs['default']
                elif args:
                    if len(args) > 1:
                        # min(*args) - unpacking
                        if len(args) == 0:
                            if 'default' in kwargs:
                                return kwargs['default']
                            raise TypeError("min expected at least 1 argument, got 0")
                        else:
                            return builtins_min(*args)
                    else:
                        return builtins_min(args[0])
                else:
                    if 'default' in kwargs:
                        return kwargs['default']
                    raise TypeError("min expected at least 1 argument, got 0")

            elif func_name == 'max':
                args = [self.evaluate_arg(arg) for arg in node.args]
                kwargs = {kw.arg: self.evaluate_arg(kw.value) for kw in node.keywords}

                if 'default' in kwargs and not args:
                    return kwargs['default']
                elif args:
                    if len(args) > 1:
                        if len(args) == 0:
                            if 'default' in kwargs:
                                return kwargs['default']
                            raise TypeError("max expected at least 1 argument, got 0")
                        else:
                            return builtins_max(*args)
                    else:
                        key = kwargs.get('key')
                        if key is None:
                            return builtins_max(args[0])
                        else:
                            return builtins_max(args[0], key=key)
                else:
                    if 'default' in kwargs:
                        return kwargs['default']
                    raise TypeError("max expected at least 1 argument, got 0")
            else:
                raise ValueError("Unknown function: " + func_name)

        def evaluate_arg(self, node):
            # Handle simple arguments
            if isinstance(node, ast.Constant):
                return node.value
            elif isinstance(node, ast.List):
                return [self.evaluate_arg(el) for el in node.elts]
            elif isinstance(node, ast.Starred):
                # For min(*[]) - this would be a starred empty list
                if isinstance(node.value, ast.List):
                    return ('starred', [self.evaluate_arg(el) for el in node.value.elts])
                else:
                    raise ValueError("Unsupported starred expression")
            elif isinstance(node, ast.Call):
                # This could be a key=lambda... or similar, but for our test cases, we don't have that
                raise ValueError("Nested calls not supported in this simple evaluator")
            else:
                raise ValueError("Unsupported argument type")

        def generic_visit(self, node):
            raise ValueError("Unsupported node type")

    try:
        ev = Evaluator()
        result = ev.visit(tree)
        # Check if result is a starred marker
        if isinstance(result, tuple) and len(result) == 2 and result[0] == 'starred':
            return result[1]
        return result
    except Exception as e:
        raise e

