def _sort_tracks(tracks):
    # Sort by duration_ms ascending; None treated as +inf (stable sort preserves original order).
    def key_func(track):
        d = track.get('duration_ms')
        return float(d) if d is not None else float('inf')
    return sorted(tracks, key=key_func)


def reference_minor(path):
    # Read JSON file from the given path.
    try:
        with open(path, 'r') as f:
            data = json.load(f)
    except Exception:
        print(f"Invalid Lypning config file: {path}")
        return

    tracks = data.get('tracks', [])
    if not tracks:
        print("No tracks found")
        return

    tracks = _sort_tracks(tracks)

    ref_key = None
    ref_id = None
    ref_duration = None
    for track in tracks:
        key_val = track.get('key')
        is_major = track.get('is_major_key', 1)
        duration = track.get('duration_ms')
        if key_val is None or is_major == 1:
            continue
        if ref_key is None:
            ref_key = key_val
            ref_id = track.get('id')
            ref_duration = duration
        elif duration < ref_duration:
            ref_key = key_val
            ref_id = track.get('id')
            ref_duration = duration

    if ref_key is not None:
        print(f"key: {ref_key} | ref track: {ref_id}")
    else:
        print("No minor keys found")


