import json, collections, os

# Build the file list without relying on glob ordering: walk like glob does,
# but sort every directory entry so the iteration order is fully deterministic.
def list_files(pattern):
    root, pattern = os.path.splitdrive(pattern)
    if not root and os.sep in pattern[1:]:
        ix = max(pattern.rfind('/'), pattern.rfind(os.sep))
        root = pattern[:ix]
        pattern = pattern[ix+1:]
    else:
        root = ''
    if not pattern:
        return [root.rstrip('/') or (os.curdir)]
    items = [pattern]
    while True:
        if '*' in items[-1] or '?' in items[-1] or '[' in items[-1]:
            break
        if root == '':
            root, name = os.path.split(os.path.join(os.getcwd(), items.pop()))
        else:
            root, name = os.path.split(items.pop())
        if not name:
            if root == '':
                return ['']
            break
        items.append(name)
        items.append(root)
    # Now we have a stack of path components, with patterns possibly at each level.
    # We'll reconstruct: build up full directories for non-pattern parts and use
    # fnmatch to filter directory contents at pattern levels.
    # Simpler robust approach: just do our own recursive matcher over the filesystem.
    parts = _split_pattern(pattern)  # list of (is_pattern, text)
    if root:
        base_dirs = [root]
    else:
        base_dirs = ['.']
    results = []
    def rec(directories, part_idx, current_path):
        if part_idx >= len(parts):
            try:
                if os.path.isfile(current_path):
                    results.append(current_path)
            except OSError:
                pass
            return
        is_pat, text = parts[part_idx]
        if is_pat:
            if os.path.isdir(current_path):
                try:
                    entries = sorted(os.listdir(current_path))
                except OSError:
                    return
            else:
                entries = []
            for e in entries:
                cp = os.path.join(current_path, e)
                if part_idx + 1 == len(parts):
                    try:
                        if os.path.isfile(cp) and _fnmatch(e, text):
                            results.append(cp)
                    except OSError:
                        pass
                else:
                    try:
                        if os.path.isdir(cp) and _fnmatch(e, text):
                            rec([cp], part_idx + 1, cp)
                    except OSError:
                        pass
        else:
            cp = os.path.join(current_path, text)
            if part_idx + 1 == len(parts):
                try:
                    if os.path.isfile(cp):
                        results.append(cp)
                except OSError:
                    pass
            else:
                try:
                    if os.path.isdir(cp):
                        rec([cp], part_idx + 1, cp)
                except OSError:
                    pass
    for d in base_dirs:
        rec([d], 0, d)
    return sorted(results)

def _split_pattern(pattern):
    parts = pattern.replace('\\', '/').split('/')
    out = []
    for p in parts:
        if p in ('', '.'):
            continue
        has = any(ch in p for ch in '*?[')
        out.append((has, p))
    return out

def _fnmatch(name, pat):
    import re as _re
    rx = _translate(pat)
    return _re.match(rx, name) is not None

def _translate(pat):
    i, n = 0, len(pat)
    res = ''
    while i < n:
        c = pat[i]
        i += 1
        if c == '*':
            res += '.*'
        elif c == '?':
            res += '.'
        elif c == '[':
            j = i
            if j < n and pat[j] in '!^':
                j += 1
            if j < n and pat[j] == ']':
                j += 1
            while j < n and pat[j] != ']':
                j += 1
            if j >= n:
                res += '\\['
            else:
                stuff = pat[i:j].replace('\\', '\\\\')
                i = j + 1
                if stuff[0] in '!^':
                    stuff = '^' + stuff[1:]
                elif stuff[0] == '^':
                    stuff = '\\' + stuff
                res += '[%s]' % stuff
        else:
            res += '\\' + c
    return '(?:' + res + ')' + '$'

