def load_line(line):
    line = line.strip()
    if not line:
        return None
    s = ''
    i = 0
    n = len(line)
    while i < n and (line[i] == ' ' or line[i] == '\t'):
        i += 1
    if i >= n or line[i] != '{':
        return None
    stack = ['{']
    depth = 1
    in_string = False
    esc = False
    key_pending = True
    buf_key = []
    buf_val = []
    val_kind = None
    cur_type = None
    cur_model = None
    cur_sidechain = None
    # simplified state machine that only extracts type, isSidechain, message.model
    # We need to detect the top-level "type" value, "isSidechain" value, and
    # inside "message" object the "model" field value (string).
    # Let's implement a small parser.
    j = i + 1
    def parse_value():
        nonlocal j
        while j < n and (line[j]==' ' or line[j]=='\t'):
            j+=1
        if j>=n:
            return None,None
        c=line[j]
        if c=='{':
            return parse_obj()
        if c=='[':
            return parse_arr()
        if c=='"':
            return parse_str(), None
        if line.startswith('true',j):
            j+=4; return True,'bool'
        if line.startswith('false',j):
            j+=5; return False,'bool'
        if line.startswith('null',j):
            j+=4; return None,'null'
        k=j
        while k<n and line[k]!='}':
            if line[k]==',': break
            if line[k]==']:': break
            k+=1
        tok=line[j:k].strip()
        if tok=='':
            return None,None
        try:
            fv=float(tok); return fv,'num'
        except Exception:
            return tok,'raw'
    def parse_str():
        nonlocal j
        assert line[j]=='"'
        j+=1
        out=[]
        while j<n:
            c=line[j]
            if c=='\\':
                j+=1
                if j<n:
                    d=line[j]
                    if d=='n': out.append('\n')
                    elif d=='t': out.append('\t')
                    elif d=='r': out.append('\r')
                    elif d=='b': out.append('\b')
                    elif d=='f': out.append('\f')
                    elif d=='"': out.append('"')
                    elif d=='/': out.append('/')
                    elif d=='\\': out.append('\\')
                    elif d=='u':
                        j+=1
                        code=line[j:j+4]
                        j+=3
                        try:
                            out.append(chr(int(code,16)))
                        except Exception:
                            out.append('?')
                    else:
                        out.append(d)
                j+=1
            elif c=='"':
                j+=1
                break
            else:
                out.append(c)
                j+=1
        return ''.join(out)
    def parse_arr():
        nonlocal j
        assert line[j]=='['
        j+=1
        items=[]
        while j<n:
            while j<n and (line[j]==' ' or line[j]=='\t'):
                j+=1
            if j<n and line[j]==']':
                j+=1
                return items
            v,k=parse_value()
            items.append(v)
            while j<n and (line[j]==' ' or line[j]=='\t'):
                j+=1
            if j<n and line[j]==',':
                j+=1
                continue
            if j<n and line[j]==']':
                j+=1
                return items
        return items
    def parse_obj():
        nonlocal j
        assert line[j]=='{'
        j+=1
        obj={}
        while j<n:
            while j<n and (line[j]==' ' or line[j]=='\t'):
                j+=1
            if j<n and line[j]=='}':
                j+=1
                return obj
            if j<n and line[j]=='"':
                key=parse_str()
            else:
                # bail
                key=None
            while j<n and (line[j]==' ' or line[j]=='\t'):
                j+=1
            if j<n and line[j]==':':
                j+=1
            else:
                break
            v,kk=parse_value()
            obj[key]=v
            while j<n and (line[j]==' ' or line[j]=='\t'):
                j+=1
            if j<n and line[j]==',':
                j+=1
                continue
            if j<n and line[j]=='}':
                j+=1
                return obj
        return obj
    try:
        val,kind = parse_value()
    except Exception:
        return None
    if not isinstance(val, dict):
        return None
    return val

