def json_dumps_simple(o):
    if o is None:
        return "null"
    if o is True:
        return "true"
    if o is False:
        return "false"
    if isinstance(o, int):
        return str(o)
    if isinstance(o, float):
        s = repr(o)
        if '.' not in s and 'e' not in s and 'E' not in s and 'inf' not in s and 'nan' not in s:
            s += '.0'
        return s
    if isinstance(o, str):
        out = ['"']
        for ch in o:
            cp = ord(ch)
            if ch == '\\':
                out.append('\\\\')
            elif ch == '"':
                out.append('\\"')
            elif ch == '\n':
                out.append('\\n')
            elif ch == '\r':
                out.append('\\r')
            elif ch == '\t':
                out.append('\\t')
            elif ch == '\b':
                out.append('\\b')
            elif ch == '\f':
                out.append('\\f')
            elif cp < 0x20:
                out.append('\\u%04x' % cp)
            else:
                out.append(ch)
        out.append('"')
        return ''.join(out)
    if isinstance(o, list):
        return '[' + ','.join(json_dumps_simple(x) for x in o) + ']'
    if isinstance(o, dict):
        parts = []
        for k in o:
            parts.append(json_dumps_simple(k) + ':' + json_dumps_simple(o[k]))
        return '{' + ','.join(parts) + '}'
    raise ValueError('unserializable: ' + repr(o))


class _Obj(object):
    __slots__ = ('_d',)

    def __init__(self, d):
        object.__setattr__(self, '_d', d)

    @property
    def _dict(self):
        return object.__getattribute__(self, '_d')

    def get(self, k, default=None):
        return self._dict.get(k, default)


def _parse_value(s, i):
    n = len(s)
    while i < n and (s[i] in ' \t\r\n'):
        i += 1
    if i >= n:
        raise ValueError('unexpected end')
    c = s[i]
    if c == '{':
        i += 1
        obj = {}
        while True:
            while i < n and (s[i] in ' \t\r\n'):
                i += 1
            if s[i] == '}':
                i += 1
                break
            ks, i = _parse_value(s, i)
            while i < n and (s[i] in ' \t\r\n'):
                i += 1
            if s[i] != ':':
                raise ValueError('expected :')
            i += 1
            vs, i = _parse_value(s, i)
            obj[ks] = vs
            while i < n and (s[i] in ' \t\r\n'):
                i += 1
            if s[i] == ',':
                i += 1
                continue
            elif s[i] == '}':
                i += 1
                break
            else:
                raise ValueError('expected , or }')
        return obj, i
    if c == '[':
        i += 1
        arr = []
        while True:
            v, i = _parse_value(s, i)
            arr.append(v)
            while i < n and (s[i] in ' \t\r\n'):
                i += 1
            if s[i] == ',':
                i += 1
                continue
            elif s[i] == ']':
                i += 1
                break
            else:
                raise ValueError('expected , or ]')
        return arr, i
    if c == '"':
        i += 1
        out = []
        while True:
            ch = s[i]
            if ch == '\\':
                i += 1
                ec = s[i]
                if ec == '"':
                    out.append('"')
                    i += 1
                elif ec == '\\':
                    out.append('\\')
                    i += 1
                elif ec == '/':
                    out.append('/')
                    i += 1
                elif ec == 'n':
                    out.append('\n')
                    i += 1
                elif ec == 't':
                    out.append('\t')
                    i += 1
                elif ec == 'r':
                    out.append('\r')
                    i += 1
                elif ec == 'b':
                    out.append('\b')
                    i += 1
                elif ec == 'f':
                    out.append('\f')
                    i += 1
                elif ec == 'u':
                    h = s[i + 1:i + 5]
                    out.append(chr(int(h, 16)))
                    i += 5
                else:
                    raise ValueError('bad escape')
                continue
            if ch == '"':
                i += 1
                break
            out.append(ch)
            i += 1
        return ''.join(out), i
    if s.startswith('null', i):
        return None, i + 4
    if s.startswith('true', i):
        return True, i + 4
    if s.startswith('false', i):
        return False, i + 5
    j = i
    while j < n and s[j] not in ' \t\r\n,}]':
        j += 1
    tok = s[i:j]
    try:
        v = int(tok)
    except Exception:
        try:
            v = float(tok)
        except Exception:
            raise ValueError('bad number ' + repr(tok))
    return v, j


