# Manual minimal JSON decoder (standard library is restricted here).
WHITESPACE = " \t\r\n"

class Decoder:
    def __init__(self, s):
        self.s = s
        self.i = 0
        self.n = len(s)

    def peek(self):
        return self.s[self.i] if self.i < self.n else None

    def next(self):
        c = self.s[self.i]; self.i += 1; return c

    def ws(self):
        while self.i < self.n and self.s[self.i] in WHITESPACE:
            self.i += 1

    def error(self):
        raise ValueError("bad json")

    def value(self):
        self.ws()
        c = self.peek()
        if c == "{": return self.obj()
        if c == "[": return self.arr()
        if c == '"': return self.string()
        if c == "t": return self.lit("true");
        if c == "f": return self.lit("false");
        if c == "n": return self.lit("null");
        if c == "-" or (c is not None and "0" <= c <= "9"): return self.num()
        raise ValueError("bad json")

    def lit(self, w):
        end = self.i + len(w)
        if self.s[self.i:end] != w:
            raise ValueError("bad json")
        self.i = end
        return True if w == "true" else (False if w == "false" else None)

    def num(self):
        start = self.i
        while self.i < self.n:
            c = self.s[self.i]
            if c in "-+.0123456789eE":
                self.i += 1
            else:
                break
        tok = self.s[start:self.i]
        try:
            if ("." in tok) or ("e" in tok) or ("E" in tok):
                return float(tok)
            return int(tok)
        except ValueError:
            raise ValueError("bad number")

    def string(self):
        assert self.next() == '"'
        out = []
        while self.i < self.n:
            c = self.next()
            if c == '"':
                return "".join(out)
            if c == "\\":
                e = self.next()
                if e == '"': out.append('"')
                elif e == "\\": out.append("\\")
                elif e == "/": out.append("/")
                elif e == "b": out.append("\b")
                elif e == "f": out.append("\f")
                elif e == "n": out.append("\n")
                elif e == "r": out.append("\r")
                elif e == "t": out.append("\t")
                elif e == "u":
                    h = self.s[self.i:self.i+4]; self.i += 4
                    try:
                        code = int(h, 16)
                    except Exception:
                        raise ValueError("bad unicode")
                    if 0xD800 <= code <= 0xDBFF:
                        if self.s[self.i:self.i+2] == "\\u":
                            self.i += 2
                            h2 = self.s[self.i:self.i+4]; self.i += 4
                            lo = int(h2, 16)
                            if 0xDC00 <= lo <= 0xDFFF:
                                code = 0x10000 + ((code - 0xD800) << 10) + (lo - 0xDC00)
                                out.append(chr(code)); continue
                    out.append(chr(code))
                else:
                    raise ValueError("bad escape")
            else:
                out.append(c)
        raise ValueError("unterminated string")

    def arr(self):
        assert self.next() == "["
        lst = []
        self.ws()
        if self.peek() == "]":
            self.next(); return lst
        while True:
            lst.append(self.value())
            self.ws()
            c = self.next()
            if c == "]":
                return lst
            if c != ",":
                raise ValueError("bad array")
            self.ws()

    def obj(self):
        assert self.next() == "{"
        d = {}
        self.ws()
        if self.peek() == "}":
            self.next(); return d
        while True:
            self.ws()
            if self.peek() != '"':
                raise ValueError("bad key")
            k = self.string()
            self.ws()
            if self.next() != ":":
                raise ValueError("bad colon")
            d[k] = self.value()
            self.ws()
            c = self.next()
            if c == "}":
                return d
            if c != ",":
                raise ValueError("bad object")
            self.ws()


