def list_jsonl_files():
    """Emulate glob('~/.claude/projects/*/*.jsonl') in sorted order using os.path only."""
    base = os.path.expanduser('~')
    root = os.path.join(base, '.claude', 'projects')
    out = []
    try:
        top = os.listdir(root)
    except OSError:
        return out
    for t in top:
        tp = os.path.join(root, t)
        if not os.path.isdir(tp):
            continue
        try:
            inner = os.listdir(tp)
        except OSError:
            continue
        for n in inner:
            if n.endswith('.jsonl'):
                fp = os.path.join(tp, n)
                if os.path.isfile(fp):
                    out.append(fp)
    return sorted(out)


