def read_jsonl_lines(path):
    # Read the file and yield lines, using errors='replace' semantics approximated by decoding.
    try:
        with open(path, 'rb') as fh:
            data = fh.read()
    except Exception:
        return
    # Decode with utf-8 replace to emulate errors='replace'
    text = data.decode('utf-8', errors='replace')
    for ln in text.split('\n'):
        yield ln


