# Minimal JSON parser (stdlib-only-ish, self-contained)
class _JSONParser(object):
    def __init__(self, s):
        self.s = s
        self.i = 0
        self.n = len(s)

    def parse(self):
        self.skip_ws()
        v = self.parse_value()
        self.skip_ws()
        if self.i != self.n:
            raise ValueError("trailing data")
        return v

    def skip_ws(self):
        while self.i < self.n:
            ch = self.s[self.i]
            if ch in ' \t\n\r':
                self.i += 1
            else:
                break

    def parse_value(self):
        self.skip_ws()
        if self.i >= self.n:
            raise ValueError("unexpected end")
        ch = self.s[self.i]
        if ch == '{':
            return self.parse_object()
        if ch == '[':
            return self.parse_array()
        if ch == '"':
            return self.parse_string()
        if ch == 't':
            return self.parse_literal('true')
        if ch == 'f':
            return self.parse_literal('false')
        if ch == 'n':
            return self.parse_literal('null')
        return self.parse_number()

    def parse_literal(self, lit):
        if self.s.startswith(lit, self.i):
            self.i += len(lit)
            if lit == 'true':
                return True
            if lit == 'false':
                return False
            return None
        raise ValueError("bad literal at %d" % self.i)

    def parse_object(self):
        assert self.s[self.i] == '{'
        self.i += 1
        obj = {}
        self.skip_ws()
        if self.i < self.n and self.s[self.i] == '}':
            self.i += 1
            return obj
        while True:
            self.skip_ws()
            if self.i >= self.n or self.s[self.i] != '"':
                raise ValueError("expected key string")
            key = self.parse_string()
            self.skip_ws()
            if self.i >= self.n or self.s[self.i] != ':':
                raise ValueError("expected colon")
            self.i += 1
            val = self.parse_value()
            obj[key] = val
            self.skip_ws()
            if self.i >= self.n:
                raise ValueError("unterminated object")
            ch = self.s[self.i]
            if ch == ',':
                self.i += 1
                continue
            elif ch == '}':
                self.i += 1
                return obj
            else:
                raise ValueError("bad object delimiter")

    def parse_array(self):
        assert self.s[self.i] == '['
        self.i += 1
        arr = []
        self.skip_ws()
        if self.i < self.n and self.s[self.i] == ']':
            self.i += 1
            return arr
        while True:
            v = self.parse_value()
            arr.append(v)
            self.skip_ws()
            if self.i >= self.n:
                raise ValueError("unterminated array")
            ch = self.s[self.i]
            if ch == ',':
                self.i += 1
                continue
            elif ch == ']':
                self.i += 1
                return arr
            else:
                raise ValueError("bad array delimiter")

    def parse_string(self):
        assert self.s[self.i] == '"'
        self.i += 1
        out = []
        while True:
            if self.i >= self.n:
                raise ValueError("unterminated string")
            ch = self.s[self.i]
            if ch == '"':
                self.i += 1
                return ''.join(out)
            if ch == '\\':
                self.i += 1
                if self.i >= self.n:
                    raise ValueError("bad escape")
                esc = self.s[self.i]
                self.i += 1
                if esc == '"':
                    out.append('"')
                elif esc == '\\':
                    out.append('\\')
                elif esc == '/':
                    out.append('/')
                elif esc == 'b':
                    out.append('\b')
                elif esc == 'f':
                    out.append('\f')
                elif esc == 'n':
                    out.append('\n')
                elif esc == 'r':
                    out.append('\r')
                elif esc == 't':
                    out.append('\t')
                elif esc == 'u':
                    if self.i + 4 > self.n:
                        raise ValueError("bad unicode escape")
                    hexs = self.s[self.i:self.i + 4]
                    try:
                        code = int(hexs, 16)
                    except Exception:
                        raise ValueError("bad unicode value")
                    self.i += 4
                    out.append(chr(code))
                else:
                    raise ValueError("unknown escape")
            else:
                out.append(ch)
                self.i += 1

    def parse_number(self):
        start = self.i
        if self.i < self.n and self.s[self.i] in '-+':
            self.i += 1
        is_float = False
        while self.i < self.n and self.s[self.i].isdigit():
