import sys
import os

def _digits_for_base(value, base):
    """Return digits of value in given base as a list of characters."""
    digits = "0123456789abcdef"
    if base == 16:
        table = "0123456789abcdef"
    elif base == 8:
        table = "0123456787"
    else:
        table = digits[:base]
    result = []
    n = value
    while True:
        result.append(table[n % base])
        n //= base
        if n == 0:
            break
    return result[::-1]

def int_format(value, spec):
    """Replicate int.__format__(value, spec) for positive ints like 1234."""
    # Parse: [[fill]align][sign] [#] [z] [width] [,|_] [type]
    i = 0
    n = len(spec)

    # Determine fill and align
    fill = ''
    align = ''
    width = ''
    sign = ''
    alt = False
    zfill = False
    grouping = ''
    type_code = ''

    if n >= 1 and spec[0] not in ('+', '-', ' ', '#', '0', '=', '<', '>', '^'):
        fill = spec[0]
        i = 1
        if i < n and spec[i] in ('=', '<', '>', '^'):
            align = spec[i]
            i += 1
    else:
        if n >= 1 and spec[0] in ('=', '<', '>', '^'):
            align = spec[0]
            i = 1

    # sign
    if i < n and spec[i] in ('+', '-', ' '):
        sign = spec[i]
        i += 1

    # alternative form
    if i < n and spec[i] == '#':
        alt = True
        i += 1

    # zero pad flag
    if i < n and spec[i] == '0':
        zfill = True
        i += 1

    # width - digits
    while i < n and spec[i].isdigit():
        width += spec[i]
        i += 1
    width_val = int(width) if width else 0

    # comma or underscore grouping
    if i < n and spec[i] in (',', '_'):
        grouping = spec[i]
        i += 1

    # type code - everything remaining should be at most one char
    if i < n:
        if n - i != 1:
            raise ValueError("Invalid format specifier")
        type_code = spec[i]
        i += 1

    # Now determine the base / output from type_code
    if type_code == '':
        type_code = 'd'

    valid_types = set('bdxoXeEfFgG%crnsN')
    if type_code not in valid_types:
        raise ValueError("Unknown format code '%s' for object of type 'int'" % type_code)

    # Determine base and digit representation
    if type_code in ('d', 'n', 'N', 'c', 'r', 's'):
        base = 10
        body_digits = str(abs(value))
        is_zero = False
    elif type_code == 'b':
        base = 2
        body_digits = ''.join(_digits_for_base(abs(value), base))
        is_zero = (value == 0)
    elif type_code == 'o':
        base = 8
        body_digits = ''.join(_digits_for_base(abs(value), base))
        is_zero = (value == 0)
    elif type_code in ('x', 'X'):
        base = 16
        body_digits = ''.join(_digits_for_base(abs(value), base))
        if type_code == 'X':
            body_digits = body_digits.upper()
        is_zero = (value == 0)
    else:
        # f, e, g, E, G, % - float types on int
        float_str = str(float(value))
        # For simplicity, handle basic cases
        if type_code == 'f':
            body_digits = float_str
        elif type_code == 'e':
            body_digits = '%se%d' % (*float_str.split('e'),) if 'e' in float_str else float_str + 'e+00'
            # This gets complicated; but for our specific input we won't hit this path
            raise ValueError("unsupported")
        elif type_code == 'E':
            raise ValueError("unsupported")
        elif type_code == 'g':
            body_digits = float_str
        elif type_code == 'G':
            body_digits = float_str.upper()
        elif type_code == '%':
            body_digits = float_str + '%'
        else:
            raise ValueError("unsupported")
        is_zero = False

    # Sign prefix
    neg = (value < 0)
    sign_prefix = ''
    if sign == '+':
        sign_prefix = '+'
    elif sign == '-':
        sign_prefix = '-' if neg else ''
    elif sign == ' ':
        sign_prefix = ' ' if not neg else '-'
    else:
        sign_prefix = '-' if neg else ''

    # Alt form prefixes per CPython
    if alt:
        if type_code == 'b':
            alt_prefix = '0b'
        elif type_code == 'o':
            alt_prefix = '0o'
        elif type_code in ('x', 'X'):
            if type_code == 'x':
                alt_prefix = '0x'
            else:
                alt_prefix = '0X'
        else:
            # '#' with d, c, r, s, f, e, g, %, n is invalid in CPython
            if type_code in ('f', 'e', 'g', 'E', 'G', '%'):
                # CPython actually allows # for some? No - it raises
                raise ValueError("Invalid conversion flag '#'")
            elif type_code in ('d', 'c', 'r', 's', 'n', 'N'):
                raise ValueError("Invalid conversion flag '#'")
            else:
                raise ValueError("Invalid conversion flag '#'")
    else:
        alt_prefix = ''

    # Combine content
    content = sign_prefix + alt_prefix + body_digits

