def format_value(fmt, val):
    if not fmt.startswith('%'):
        return None
    spec = fmt[1:]
    i = 0
    flags = set()
    while i < len(spec) and spec[i] in '+-# ' :
        flags.add(spec[i])
        i += 1
    width = ''
    while i < len(spec) and spec[i].isdigit():
        width += spec[i]
        i += 1
    prec = ''
    if i < len(spec) and spec[i] == '.':
        i += 1
        while i < len(spec) and spec[i].isdigit():
            prec += spec[i]
            i += 1
    conv = spec[i:]

    if conv == 'd':
        n = int(val)
        s = str(n)
        neg = False
        if n < 0:
            neg = True
            s = str(-n)
        elif '+' in flags:
            s = '+' + s
        elif ' ' in flags:
            s = ' ' + s
        if '#' in flags:
            pass
        if neg:
            s = '-' + s
        # padding
        total_w = int(width) if width else 0
        if '0' in flags and total_w > len(s):
            pad = total_w - len(s)
            s = '0'*pad + s
        else:
            if total_w > len(s):
                if '-' in flags:
                    s = s + ' '*(total_w-len(s))
                else:
                    s = ' '*(total_w-len(s)) + s
        return s
    elif conv == 'f':
        x = float(val)
        negative = x < 0
        ax = abs(x)
        if ax >= 1e16 or (ax != 0 and ax < 1e-4):
            s = 'inf' if ax==float('inf') else repr(float(ax))
            if negative:
                s = '-'+s
            if '+' in flags and not negative:
                s = '+'+s
            elif ' ' in flags and not negative:
                s = ' '+s
            w = int(width) if width else 0
            if w > len(s):
                if '-' in flags:
                    s = s+' '*(w-len(s))
                else:
                    s = ' '*(w-len(s))+s
            return s
        p = int(prec) if prec else 6
        # round to p decimal places
        mult = 10.0 ** p
        r = int(ax*mult + 0.5)
        ipart = r // mult
        fpart = r % mult
        s = str(ipart) + '.' + ('%0*d'%(p,fpart) if p>0 else '')
        if p == 0:
            s = str(ipart)
        if negative:
            s = '-'+s
        elif '+' in flags:
            s = '+'+s
        elif ' ' in flags:
            s = ' '+s
        w = int(width) if width else 0
        if '0' in flags and w > len(s):
            s = '0'*(w-len(s)) + s
        else:
            if w > len(s):
                if '-' in flags:
                    s = s+' '*(w-len(s))
                else:
                    s = ' '*(w-len(s))+s
        return s
    elif conv == 'c':
        cval = int(val)
        if 0 <= cval < 256:
            s = chr(cval)
        else:
            raise ValueError('chr() arg not in range(256)')
        w = int(width) if width else 0
        if '0' in flags:
            s = '0'*(w-len(s)) + s
        elif w > len(s):
            if '-' in flags:
                s = s+' '*(w-len(s))
            else:
                s = ' '*(w-len(s))+s
        return s
    else:
        raise ValueError('bad format character')

