def emulate_percent_format(fmt, value):
    # Parse fmt
    if not fmt.startswith('%'):
        return fmt % value # Not expected in this list

    body = fmt[1:]
    i = 0
    flags = []
    while i < len(body):
        c = body[i]
        if c == '-':
            flags.append('-')
        elif c == '+':
            flags.append('+')
        elif c == '#':
            flags.append('#')
        elif c == ' ':
            flags.append(' ')
        elif c == '0':
            flags.append('0')
        elif c == ',':
            flags.append(',')
        elif c == '_':
            flags.append('_')
        elif c == 'z':
            flags.append('z')
        else:
            break
        i += 1

    width_str = ""
    while i < len(body) and body[i].isdigit():
        width_str += body[i]
        i += 1

    prec_str = ""
    if i < len(body) and body[i] == '.':
        i += 1
        while i < len(body) and body[i].isdigit():
            prec_str += body[i]
            i += 1

    conv = ''
    if i < len(body):
        conv = body[i]

    # Logic for errors
    # Conversion types check
    if conv == 'd':
        if not isinstance(value, (int, float)):
             raise TypeError("not all arguments converted during string formatting")
        if ',' in flags or '_' in flags:
             raise ValueError("unsupported format character '%s' (0x%s) at index %d" % (conv, hex(ord(conv))[2:], fmt.find(conv)+1))
        # Standard int formatting
        s = str(int(value))
        if '+' in flags:
            if value > 0: s = '+' + s
        if ' ' in flags:
            if value > 0: s = ' ' + s
        if '-' in flags:
            if width_str:
                w = int(width_str)
                if len(s) < w: s = s.ljust(w)
        else:
            if width_str:
                w = int(width_str)
                fill = '0' if '0' in flags else ' '
                # Handle sign for padding
                if '+' in flags or ' ' in flags:
                    sign = '+' if ('+' in flags and value>0) else (' ' if ' ' in flags and value>0 else '')
                    num_part = str(abs(int(value)))
                    if len(sign)+len(num_part) < w:
                        pad = w - len(sign) - len(num_part)
                        s = sign + fill.zfill(pad) + num_part
                    else:
                        s = sign + num_part
                else:
                    if len(s) < w:
                        s = fill.zfill(w-len(s)) + s
        return s

    elif conv == 'f':
        if not isinstance(value, (int, float)):
             raise TypeError("not all arguments converted during string formatting")
        if ',' in flags or '_' in flags or 'z' in flags:
             raise ValueError("unsupported format character 'f' (0x66) at index %d" % (fmt.find('f')+1))
        val = float(value)
        prec = int(prec_str) if prec_str else 6
        s = "%.{}f".format(prec).replace('.{}f'.format(prec), str(val)) # Simplified
        # Actually easier:
        s = ("%.{}f" % prec).format(val) if False else ("%." + str(prec) + "f") % val
        # Let's just use str logic or basic formatting
        # For 1.5, %.6f -> 1.500000
        # With + flag
        if '+' in flags:
             if val > 0: s = '+' + s
        # Width handling... omitted for brevity as not needed for 1.5 in this list except potentially complex
        return s

    elif conv == 'c':
        if not isinstance(value, int):
             raise TypeError("an integer is required")
        if '#' in flags:
             raise ValueError("unknown format code 'c' for object of type 'int'")
        if ' ' in flags:
             raise ValueError("unknown format code 'c' for object of type 'int'")
        if '+' in flags:
             raise TypeError("'+' flag with 'c' is unsupported")
        if 'z' in flags or ',' in flags or '_' in flags:
             raise ValueError("unsupported format character 'c' (0x63) at index %d" % (fmt.find('c')+1))

        ch = chr(value)
        if prec_str:
             # Precision for char is 1
             pass 
        if width_str:
            w = int(width_str)
            if '-' in flags:
                 return ch.ljust(w)
            else:
                 # Zero padding doesn't work for chars in python3, it uses spaces
                 return ch.rjust(w)
        return ch
    else:
        raise ValueError("unsupported format character '%s'" % conv)

