def custom_fmt(fmt, val):
    idx = 1
    out = []
    n = len(fmt)
    while idx < n:
        ch = fmt[idx]
        if ch != '%':
            out.append(ch)
            idx += 1
            continue
        # percent at idx
        if idx + 1 >= n:
            raise ValueError("incomplete format")
        nxt = fmt[idx+1]
        if nxt == 'r':
            out.append(repr(val))
            idx += 2
            continue
        if nxt == 's':
            out.append(str(val))
            idx += 2
            continue
        # parse flags, width, precision, conversion
        pos = idx + 1
        flags_set = set()
        while pos < n and fmt[pos] in '+-#0 ':
            flags_set.add(fmt[pos])
            pos += 1
        width = ''
        while pos < n and fmt[pos].isdigit():
            width += fmt[pos]
            pos += 1
        prec = ''
        if pos < n and fmt[pos] == '.':
            pos += 1
            while pos < n and fmt[pos].isdigit():
                prec += fmt[pos]
                pos += 1
        if pos >= n:
            raise ValueError("incomplete format")
        conv = fmt[pos]
        pos += 1

        if conv in ('d', 'i'):
            iv = int(val)
            s = str(abs(iv))
            neg = iv < 0
            if '+' in flags_set:
                prefix = '+'
            elif '#' in flags_set:
                prefix = '-' if neg else '+'
            else:
                prefix = '-' if neg else ''
            if '0' in flags_set and not '-' in flags_set and width:
                w = int(width)
                total_prefix = len(prefix)
                need = w - (total_prefix + len(s))
                if need > 0:
                    s = '0' * need + s
                result = prefix + s
            else:
                padchar = ' ' if ' ' in flags_set else ' '
                # Actually, flag ' ' adds space for positive; default is no pad char difference
                # Standard: left-align if '-', else right-align with spaces
                w = int(width) if width else 0
                result = prefix + s
                if w > len(result):
                    if '-' in flags_set:
                        result = result + ' ' * (w - len(result))
                    else:
                        result = ' ' * (w - len(result)) + result
            out.append(result)
            idx = pos
            continue
        if conv == 'c':
            cv = int(val)
            c = chr(cv)
            # For %c, width applies to the character. Flags like #, + don't make sense.
            w = int(width) if width else 0
            if '-' in flags_set:
                result = c.ljust(w)
            elif '0' in flags_set:
                result = c.rjust(w, '0')
            else:
                result = c.rjust(w)
            out.append(result)
            idx = pos
            continue
        if conv == 'f':
            fv = float(val)
            if prec:
                p = int(prec)
            else:
                p = 6
            s = format(fv, '.' + str(p) + 'f')
            w = int(width) if width else 0
            if '-' in flags_set:
                result = s.ljust(w)
            elif '0' in flags_set:
                result = s.rjust(w, '0')
            else:
                result = s.rjust(w)
            out.append(result)
            idx = pos
            continue
        raise ValueError("unsupported conversion: " + repr(conv))
    return ''.join(out)


