def percent_format(fmt, val):
    # fmt is a string starting with '%' and ending with the conversion char
    # Extract: flags, width, precision, conversion
    m = re.match(r'^%([-+# ]*)(\d*)\.?(\d*)([diouxXeEfFgGcrsab])$', fmt)
    if not m:
        raise ValueError("unsupported format")
    flags, width_s, prec_s, conv = m.group(1), m.group(2), m.group(3), m.group(4)
    width = int(width_s) if width_s else None
    precision = int(prec_s) if prec_s != '' else None

    result = ""
    try:
        if conv == 'd':
            # integer format
            n = int(val)
            s = str(n) if n >= 0 else "-" + str(-n)
            sign = "+" if ('+' in flags and n > 0) else (" " if (' ' in flags and n > 0) else "")
            result = sign + s
            if precision is not None:
                pad = precision - len(s)
                if pad > 0:
                    result = sign + '0' * pad + s
            elif width is not None:
                total_w = width - len(sign)
                fill = ' ' if '-' in flags else '0' if '0' in flags else ' '
                if '-' in flags:
                    result = result.ljust(total_w, ' ')
                else:
                    result = sign + result[len(sign):].rjust(total_w, '0') if '0' in flags else result.rjust(total_w, ' ')
        elif conv == 'c':
            ch = chr(val)
            result = ch
            if width is not None:
                if '-' in flags:
                    result = result.ljust(width, ' ')
                else:
                    result = result.rjust(width, ' ')
        elif conv == 'f':
            # float format
            x = float(val)
            neg = x < 0
            ax = abs(x)
            # For %f default precision is 6
            if precision is None:
                p = 6
            else:
                p = precision
            ipart = int(ax)
            fracpart = ax - ipart
            # Convert fractional to decimal string
            if p > 0:
                fval = fracpart * (10 ** p)
                fip = int(fval)
                fs = ''.join(str((fip // (10 ** i)) % 10) for i in range(p - 1, -1, -1))
                result_str = str(ipart) + "." + fs
            else:
                result_str = str(ipart)
            sign = ""
            if neg:
                sign = "-"
            elif '+' in flags:
                sign = "+"
            elif ' ' in flags:
                sign = " "
            result = sign + result_str
            if width is not None:
                if '-' in flags:
                    result = result.ljust(width, ' ')
                else:
                    fill_c = '0' if '0' in flags else ' '
                    if '0' in flags:
                        result = sign + result_str.rjust(width - len(sign), '0')
                    else:
                        result = result.rjust(width, ' ')
        else:
            raise ValueError("unsupported conversion: " + conv)
    except Exception as e:
        raise e
    return result


