def _fmt_f(v, p):
    if p == 0:
        s = "%d" % round(v)
        s = "%d" % int(round(v))
        return s
    neg = v < 0
    av = abs(v)
    whole = int(av)
    frac_part = av - whole
    frac_str = "".join(str(d) for d in _frac_digits(frac_part, p))
    s = str(whole) + "." + frac_str if p > 0 else str(whole)
    if neg:
        s = "-" + s
    return s

def _frac_digits(fract, count):
    digits = []
    x = fract
    for _ in range(count):
        x *= 10
        d = int(x)
        x -= d
        digits.append(d)
    return digits

def _pad_float_zero(s, w, sign_prefix):
    if "." in s:
        ipart, fpart = s.split(".", 1)
        total_len = len(s)
        pad = w - total_len
        if pad <= 0:
            return s
        if sign_prefix:
            ipart = sign_prefix + ipart
        new_ipart = ipart.zfill(len(ipart) + pad)
        return new_ipart + "." + fpart
    else:
        return s.rjust(w)

