def my_percent(f, v):
    i = 0
    n = len(f)
    out = []
    while i < n:
        c = f[i]
        if c != '%':
            out.append(c)
            i += 1
            continue
        if i + 1 >= n:
            out.append('%')
            i += 1
            continue
        j = i + 1
        flags = ''
        width = ''
        prec = ''
        length = ''
        conv = ''
        # parse flags
        while j < n and f[j] in '+- #0':
            flags += f[j]
            j += 1
        # width (digits or *)
        while j < n and f[j].isdigit():
            width += f[j]
            j += 1
        # precision
        if j < n and f[j] == '.':
            prec = '.'
            j += 1
            while j < n and f[j].isdigit():
                prec += f[j]
                j += 1
        # length modifier
        if j < n and f[j] in 'lhLqz':
            length = f[j]
            j += 1
        if j < n and f[j] in "diouxXeEfFgGcrsa%":
            conv = f[j]
            j += 1
        else:
            # unknown conversion - treat as literal? In CPython this is an error. Let's mimic that.
            raise ValueError("unsupported format character '%s' (index %d)" % (f[j] if j<n else '?', i))

        w = int(width) if width else None
        p_str = prec[1:] if prec.startswith('.') else None
        p = int(p_str) if p_str is not None else None

        try:
            if conv == '%':
                res = '%'
            elif conv == 'c':
                if isinstance(v, str) and len(v) == 1:
                    ch = v
                else:
                    if not isinstance(v, (int, float)):
                        raise TypeError("format requires a number")
                    if isinstance(v, float):
                        ch = chr(int(v))
                    else:
                        ch = chr(v)
                # c ignores width/precision mostly but we can pad
                s = ch
                if width:
                    s = s.rjust(w, ' ') if '-' not in flags else s.ljust(w, ' ')
                res = s
            elif conv in 'dif':
                # integer/floating point
                num = v
                if length == 'z':
                    pass
                if conv == 'd':
                    s = str(int(num))
                elif conv == 'i':
                    s = str(int(num))
                elif conv == 'f':
                    if p is not None:
                        s = ('.%df' % p) % num
                    else:
                        s = ('%f' ) % num
                # apply flags and width
                if '+' in flags and s[0] != '-':
                    s = '+' + s
                sign = ' ' if ' ' in flags and s[0] not in ('-','+') else ''
                zero_pad = '0' in flags and sign == '' and w is not None
                neg_zero = ('-' in flags)
                if '-' in flags:
                    # left align
                    if zero_pad:
                        zero_pad = False
                    s = s.ljust(w or 0, ' ')
                else:
                    fill = '0' if zero_pad else ' '
                    if w:
                        s = s.rjust(w, fill)
                    if sign:
                        s = sign + s
                res = s
            else:
                # not implemented; use real percent for fallback safety
                return f % v
            out.append(res)
        except Exception as e:
            raise e
        i = j
    return ''.join(out)

