def _percent(fmt, v):
    i = 0
    n = len(fmt)
    out = []
    while i < n:
        c = fmt[i]
        if c != '%':
            out.append(c)
            i += 1
            continue
        if i + 1 >= n:
            raise ValueError("incomplete format")
        nxt = fmt[i+1]
        if nxt == '%':
            out.append('%')
            i += 2
            continue
        j = i + 1
        fill_char = ''
        flagset = set()
        alt = False
        width = None
        precision = None
        zflag = False
        while j < n and fmt[j] in '-+ #0z':
            fc = fmt[j]
            if fc == '#':
                alt = True
            elif fc == 'z':
                zflag = True
            elif fc == '0' and width is None and j == i+1:
                fill_char = '0'
            else:
                pass
            if fc not in ('-','+',' ','#','0','z'):
                break
            flagset.add(fc)
            j += 1
        while j < n and fmt[j].isdigit():
            width = fmt[j]
            j += 1
        if j < n and fmt[j] == '.':
            j += 1
            prec_str = ''
            while j < n and fmt[j].isdigit():
                prec_str += fmt[j]
                j += 1
            if prec_str:
                precision = int(prec_str)
        if j >= n or fmt[j] not in 'diouxXeEfFgGcrsa%':
            raise ValueError("unsupported format character")
        conv = fmt[j]
        j += 1
        if j != n:
            raise ValueError("extra data after format")

        val = v
        result = ''
        if conv == 'c':
            cp = int(val)
            ch = chr(cp)
            if precision is not None:
                pass
            s = ch
            pad_width = width
            if pad_width is not None:
                w = int(pad_width)
                if len(s) < w:
                    if '-' in flagset:
                        s = s.ljust(w)
                    elif fill_char == '0':
                        s = s.rjust(w, '0')
                    else:
                        s = s.rjust(w)
            result = s
        elif conv == 'd':
            iv = int(val)
            sgn = ''
            av = iv
            if av < 0:
                sgn = '-'
                av = -av
            else:
                if '+' in flagset:
                    sgn = '+'
                elif ' ' in flagset:
                    sgn = ' '
            digits = str(av)
            if precision is not None:
                p = precision
                if len(digits) < p:
                    digits = digits.zfill(p)
            body = sgn + digits
            if width is not None:
                w = int(width)
                if len(body) < w:
                    if '-' in flagset:
                        body = body.ljust(w)
                    elif fill_char == '0':
                        body = sgn + digits.rjust(w - len(sgn), '0')
                        if sgn == '':
                            body = digits.rjust(w, '0')
                    else:
                        body = body.rjust(w)
            result = body
        elif conv == 'f':
            fv = float(val)
            negative = fv < 0
            afv = abs(fv)
            if precision is not None:
                rounded = round(afv, precision)
                p = precision
            else:
                rounded = round(afv, 6)
                p = 6
            ipart = int(rounded)
            fp = rounded - ipart
            fstr = str(fp).split('.')[1]
            if len(fstr) > p:
                fstr = fstr[:p]
            elif len(fstr) < p:
                fstr = fstr.ljust(p, '0')
            sgn = '-' if negative else ('+' if '+' in flagset else (' ' if ' ' in flagset else ''))
            body = sgn + str(ipart) + '.' + fstr
            if width is not None:
                w = int(width)
                if len(body) < w:
                    if '-' in flagset:
                        body = body.ljust(w)
                    elif fill_char == '0':
                        sign_part = sgn
                        main_part = body[len(sgn):]
                        body = sign_part + main_part.rjust(w - len(sign_part), '0')
                    else:
                        body = body.rjust(w)
            result = body
        elif conv == 'e':
            fv = float(val)
            negative = fv < 0
            afv = abs(fv)
            if precision is not None:
                p = precision
            else:
                p = 6
            if afv == 0:
                mantissa = '0.' + '0' * p
                exp = 0
            else:
                e = int(afv)
                import math as _m
                exp = 0
                if afv >= 1.0:
                    exp = int(_m.floor(_m.log10(afv)))
                    mval = afv / (10 ** exp)
                else:
                    exp = int(_m.floor(_m.log10(afv)))
                    mval = afv / (10 ** exp)
                scaled = mval * (10 ** p)
                scaled_int = int(scaled)
                digit_count = p + 1
                ds = str(scaled_int)
                if len(ds) < digit_count:
                    ds = ds.ljust(digit_count, '0')
                ds = ds[:digit_count]
                mantissa = ds[0] + '.' + ds[1:]
                if exp == 0:
                    e_str = '+00'
                elif exp >= 0:
                    e_str = '+' + str(exp).zfill(2)
                else:
                    e_str = '-' + str(-exp).zfill(2)
            sgn = '-' if negative else ('+' if '+' in flagset else (' ' if ' ' in flagset else ''))
            body = sgn + mantissa + 'e' + e_str
            if width is not None:
                w = int(width)
                if len(body) < w:
                    if '-' in flagset:
                        body = body.ljust(w)
                    elif fill_char == '0':
                        sign_part = sgn
                        main_part = body[len(sgn):]
                        body = sign_part + main_part.rjust(w - len(sign_part), '0')
                    else:
                        body = body.rjust(w)
            result = body
        else:
            raise ValueError("unsupported conversion " + repr(conv))
        out.append(result)
    return ''.join(out)


