            j += 1
        if j >= len(s) or s[j] != ':':
            idx = end_idx
            continue
        # Now parse the value starting at j+1
        j += 1
        while j < len(s) and s[j] in ' \t\n\r':
            j += 1
        if j < len(s) and s[j] == '"':
            # String value
            j += 1
            result = []
            while j < len(s):
                ch = s[j]
