def _fmt(x, spec):
    if 'n' in spec:
        sign = ''
        rest = spec
        if spec[0] == '+':
            sign = '+'
            rest = spec[1:]
        elif spec[0] == '-':
            sign = '-'
            rest = spec[1:]
        elif spec[0] == '#':
            pass
        sep = ''
        if ',' in spec:
            sep = ','
        elif '_' in spec:
            sep = '_'
        neg = False
        if x < 0:
            neg = True
            x = -x
        s = str(x)
        if sep and len(s) > 3:
            groups = []
            while len(s) > 3:
                groups.insert(0, s[-3:])
                s = s[:-3]
            groups.insert(0, s)
            out = sep.join(groups)
        else:
            out = s
        if neg:
            out = '-' + out
        return sign + out
    else:
        return format(x, spec)


