    prec = None
    if '.' in body:
        idx = body.index('.')
        prec_str = body[idx+1:]
        body = body[:idx]
        if prec_str and prec_str[0].isdigit():
            prec = int(prec_str)

    spec = body[-1] if body else ''

    def _digits(val):
        if val < 0:
            return str(-val)
        return str(val)

