def parse_flags_width(s):
    fl = ''
    i = 0
    while i < len(s) and s[i] in '+# _,':
        fl += s[i]; i += 1
    w = ''
    while i < len(s) and s[i].isdigit():
        w += s[i]; i += 1
    wid = int(w) if w else 0
    return fl, wid

def apply_body(body, fl, wid, fill, align, is_numeric):
    cur = body
    if is_numeric and '+' in fl and not cur.startswith('-'):
        cur = '+' + cur
    pad_amount = wid - len(cur)
    if pad_amount <= 0:
        return cur
    if fill == '_':
        pad = '_' * pad_amount
    else:
        pad = fill * pad_amount
    if align == '<':
        return cur + pad
    elif align == '^':
        return pad[:pad_amount//2] + cur + pad[pad_amount//2:]
    else:
        return pad + cur

def add_commas(s, is_negative):
    neg = s.startswith('-')
    plus = s.startswith('+')
    core = s.lstrip('-+')
    parts = []
    L = list(core[::-1])
    groups = []
    chunk = []
    for idx, ch in enumerate(L):
        chunk.append(ch)
        if (idx + 1) % 3 == 0:
            groups.append(chunk[::-1])
            chunk = []
    if chunk:
        groups.append(chunk[::-1])
    result = ','.join(groups)
    if neg:
        result = '-' + result
    elif plus:
        result = '+' + result
    return result

def add_commas_plain(s):
    return add_commas(s, is_negative=s.startswith('-'))

def add_underscores(s):
    if '_' not in s:
        return s
    neg = s.startswith('-')
    core = s.lstrip('-+')
    L = list(core[::-1])
    parts = []
    chunk = []
    for idx, ch in enumerate(L):
        chunk.append(ch)
        if (idx + 1) % 3 == 0:
            parts.append(chunk[::-1])
            chunk = []
    if chunk:
        parts.append(chunk[::-1])
    res = '_'.join(parts)
    if neg:
        res = '-' + res
    return res

