class _DummyFile:
    """Minimal file-like replacement for io.StringIO, exposing read/
    readline/readlines and a buffer attribute."""
    def __init__(self, text):
        self._text = text
        self._pos = 0

    def _read(self, n=-1):
        if n is None or n < 0:
            out = self._text[self._pos:]
            self._pos = len(self._text)
        else:
            out = self._text[self._pos:self._pos + n]
            self._pos += n
        return out

    def read(self, size=-1):
        return self._read(size)

    def readline(self, size=-1):
        pos = self._pos
        end = self._text.find('\n', pos)
        if end == -1:
            line = self._text[pos:]
            self._pos = len(self._text)
        else:
            line = self._text[pos:end + 1]
            self._pos = end + 1
        if size is not None and size >= 0:
            line = line[:size]
            # Note: real readline advances by consumed chars; emulate that.
            self._pos = max(self._pos, pos + len(line))
        return line

    def readlines(self, hint=None):
        lines = []
        while True:
            line = self.readline()
            if not line:
                break
            lines.append(line)
        return lines

    @property
    def buffer(self):
        return self._text


