    return repr(msg) if isinstance(msg, str) else str(msg)


def _compile_check(source):
    """Mimic compile() for this specific set of sources.
    Returns (ok: bool, exc_type_name: str, msg_repr: str, lineno: int)."""
    lines = source.split("\n")
    # Determine effective logical blocks by their content/indentation
    prev_effective_indent = None  # None means no block yet started at top level
    # We simulate CPython's INDENT/DEDENT logic roughly
    cur_indent_stack = [0]
    in_block = False
    last_line_was_blank_or_comment = True
    line_no = 1
    # First non-blank/non-comment line defines the expected indent or 0
    expected_top_indent = 0
    determined = False

    for raw_line in lines:
        line_no += 1 if raw_line != "" or line_no > len(lines) else 0
        # Actually let's use enumerate properly
        pass

    line_no = 0
    for raw_line in lines:
        line_no += 1
        stripped = raw_line.strip()
        is_blank = (stripped == "")
        is_comment_only = (stripped.startswith("#"))
        if is_blank or is_comment_only:
            continue

        # This is an actual code line
        current_indent = len(raw_line) - len(raw_line.lstrip(" \t"))
        # Mix tabs/spaces simplified: just count leading whitespace chars
        if not determined:
            expected_top_indent = current_indent
            determined = True

        if current_indent < expected_top_indent and in_block:
            return (False, "SyntaxError", "unindent does not match any outer indentation level", line_no)

        if not in_block:
            if current_indent != 0:
                # First code line has unexpected indentation
                return (False, "SyntaxError", "unexpected indent", line_no)
            in_block = True
        else:
            if current_indent > expected_top_indent:
                # Unexpected deeper indent than expected from previous logical line
                # If the immediately preceding logical line was blank/comment, that's fine
                # But since we skip those, this case shouldn't trigger unexpectedly
                pass
            elif current_indent < expected_top_indent:
                return (False, "SyntaxError", "unindent does not match any outer indentation level", line_no)

    # All lines processed successfully
    return (True, "", "", 0)


