def permutations(iterable):
    pool = list(iterable)
    n = len(pool)
    if n == 0:
        yield []
        return
    for i in range(n):
        rest = [pool[j] for j in range(n) if j != i]
        head = pool[i]
        for tail in permutations(rest):
            yield [head] + tail

