def _permutations(seq):
    seq = list(seq)
    n = len(seq)

    def _rec(start, current):
        if start == n:
            yield tuple(current)
        else:
            for i in range(start, n):
                # swap
                tmp = current[start]
                current[start] = current[i]
                current[i] = tmp
                for p in _rec(start + 1, current):
                    yield p
                # undo swap
                tmp = current[start]
                current[start] = current[i]
                current[i] = tmp

    return _rec(0, seq[:])


