import os, sys

def esc_char(ch):
    o = ord(ch)
    if ch == '\\':
        return '\\'
    if ch == '\n':
        return 'n'
    if ch == '\t':
        return 't'
    if ch == '\r':
        return 'r'
    if 32 <= o < 127:
        return ch
    # C0/C1 and DEL: escape as octal
    return '%o' % o

def repr_string(s):
    parts = []
    for ch in s:
        parts.append('\\' + esc_char(ch))
    inner = ''.join(parts)
    has_single = "'" in inner
    has_double = '"' in inner
    if not has_single:
        return "'" + inner + "'"
    elif not has_double:
        return '"' + inner + '"'
    else:
        return "'" + inner.replace("'", "\\'") + "'"

def repr_bytes(b):
    parts = []
    for byte in b:
        if 32 <= byte < 127 and byte != 39 and byte != 40 and byte != 92:
            parts.append(chr(byte))
        elif byte == 92:
            parts.append('\\\\')
        elif byte == 10:
            parts.append('\\n')
        elif byte == 9:
            parts.append('\\t')
        elif byte == 13:
            parts.append('\\r')
        elif byte == 8:
            parts.append('\\b')
        elif byte == 11:
            parts.append('\\v')
        elif byte == 12:
            parts.append('\\f')
        else:
            parts.append('\\x%02x' % byte)
    return "b'" + ''.join(parts) + "'"

def float_repr(x):
    if x != x:
        return 'nan'
    if x == float('inf'):
        return 'inf'
    if x == float('-inf'):
        return '-inf'
    if x == 0.0:
        return '-0.0' if 1.0/x < 0 else '0.0'
    neg = x < 0
    a = abs(x)
    # Use %r formatting to get the correct shortest representation
    s = '%r' % a
    if neg:
        s = '-' + s
    return s

def str_float(x):
    if x != x:
        return 'nan'
    if x == float('inf'):
        return 'inf'
    if x == float('-inf'):
        return '-inf'
    if x == 0.0:
        return '-0.0' if 1.0/x < 0 else '0.0'
    neg = x < 0
    a = abs(x)
    s = '%s' % a
    if neg:
        s = '-' + s
    return s

def repr_value(v):
    if isinstance(v, str):
        return repr_string(v)
    if isinstance(v, bytes):
        return repr_bytes(v)
    if isinstance(v, float):
        return float_repr(v)
    if isinstance(v, bool):
        return 'True' if v else 'False'
    if isinstance(v, int):
        return str(v)
    if v is None:
        return 'None'
    if isinstance(v, list):
        items = [repr_value(x) for x in v]
        return '[' + ', '.join(items) + ']'
    if isinstance(v, tuple):
        if len(v) == 0:
            return '()'
        if len(v) == 1:
            return '(' + repr_value(v[0]) + ','
        items = [repr_value(x) for x in v]
        return '(' + ', '.join(items) + ')'
    if isinstance(v, dict):
        if len(v) == 0:
            return '{}'
        pairs = ['%s: %s' % (repr_value(k), repr_value(val)) for k, val in v.items()]
        return '{' + ', '.join(pairs) + '}'
    return repr(v)

