def is_seeded_stream(e):
    """Check if the program sets a random seed."""
    import ast
    try:
        tree = ast.parse(e.program)
    except:
        return False

    # Look for random.seed calls or assignments to random.seed that are then called
    has_seed_call = False

    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            func = node.func
            # Check if it's random.seed(...)
            if isinstance(func, ast.Attribute):
                if func.attr == 'seed' and isinstance(func.value, ast.Name) and func.value.id == 'random':
                    has_seed_call = True
            # Check if it's s(...) where s was assigned from random.seed
            elif isinstance(func, ast.Name):
                # We'll check later if this name was assigned random.seed
                pass

    if not has_seed_call:
        # Check for assignments like s = random.seed followed by s(...)
        seed_alias_names = set()
        call_names = set()

        for node in ast.walk(tree):
            if isinstance(node, ast.Assign):
                # Check if RHS is random.seed
                if isinstance(node.value, ast.Attribute):
                    if node.value.attr == 'seed' and isinstance(node.value.value, ast.Name) and node.value.value.id == 'random':
                        for target in node.targets:
                            if isinstance(target, ast.Name):
                                seed_alias_names.add(target.id)

            if isinstance(node, ast.Call):
                if isinstance(node.func, ast.Name):
                    call_names.add(node.func.id)

        if seed_alias_names & call_names:
            has_seed_call = True

    return has_seed_call

def is_run_specific(e):
    """A program is run-specific if its output depends on execution order or specific runtime state.
    Seeded random streams are run-specific because the sequence of random numbers is fixed by the seed."""
    import ast
    try:
        tree = ast.parse(e.program)
    except:
        return False

    # If the program uses random without setting a seed, it might be nondeterministic
    # But if it sets a seed, it's deterministic/run-specific
    # Let's check if it uses random module
    uses_random = False
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name.startswith('random'):
                    uses_random = True
        if isinstance(node, ast.ImportFrom):
            if node.module and node.module.startswith('random'):
                uses_random = True
        if isinstance(node, ast.Attribute):
            if isinstance(node.value, ast.Name) and node.value.id == 'random':
                uses_random = True

    if not uses_random:
        return False

    # If seeded, it's run-specific (deterministic given seed)
    return is_seeded_stream(e)

def is_nondeterministic(e):
    """A program is nondeterministic if its output can vary between runs with the same inputs.
    Unseeded random usage makes it nondeterministic. Seeded random does not."""
    import ast
    try:
        tree = ast.parse(e.program)
    except:
        return False

    uses_random = False
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name.startswith('random'):
                    uses_random = True
        if isinstance(node, ast.ImportFrom):
            if node.module and node.module.startswith('random'):
                uses_random = True
        if isinstance(node, ast.Attribute):
            if isinstance(node.value, ast.Name) and node.value.id == 'random':
                uses_random = True

    if not uses_random:
        return False

    # If seeded, it's deterministic (not nondeterministic)
    if is_seeded_stream(e):
        return False

    # If not seeded and uses random, it's nondeterministic
    return True

