                if func.attr == 'seed':
                    return True
            elif isinstance(func, ast.Name):
                # Could be a variable assigned to random.seed
                pass
    # Also check if a variable assigned from random.seed is called
    seed_vars = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign):
            if isinstance(node.value, ast.Attribute):
                if node.value.attr == 'seed' and isinstance(node.value.value, ast.Name):
                    if node.value.value.id == 'random':
                        for target in node.targets:
                            if isinstance(target, ast.Name):
                                seed_vars.add(target.id)
    for node in ast.walk(tree):
