    """Check if the program has run-specific behavior (e.g., uses time, current date, etc.)."""
    tree = ast.parse(program)
    run_specific_modules = {'time', 'datetime', 'uuid'}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name.split('.')[0] in run_specific_modules:
                    return True
        if isinstance(node, ast.ImportFrom):
            if node.module and node.module.split('.')[0] in run_specific_modules:
                return True
    return False


