def fast_list(iterable):
    try:
        items = list(iterable)
    except TypeError:
        size = len(iterable)
        if isinstance(size, int):
            return [iterable[i] for i in range(size - 1, -1, -1)]
    except AttributeError:
        pass
    else:
        if len(items) == 0:
            return []
        last_idx = len(items) - 1
        if not items[0].__eq__(items[last_idx]):
            return items[::-1]
    return None


