def _make_gen(vals):
    class G:
        def __init__(self, v):
            self._it = iter(v)
            try:
                self._next_val = next(self._it)
                self._done = False
            except StopIteration:
                self._done = True

        def __iter__(self):
            return self

        def __next__(self):
            if self._done:
                raise StopIteration
            v = self._next_val
            try:
                self._next_val = next(self._it)
            except StopIteration:
                self._done = True
            return v
    return G(list(vals))


