def format_str(v, s):
    if isinstance(v, int):
        width = 0
        fill_char = ''
        spec = None
        i = 0
        while i < len(s) and not (s[i].isalpha() or s[i] == '.' or s[i].isdigit()):
            if i > 0:
                fill_char = s[i]
            elif i == 1:
                pass
        # Parse manually
        j = 0
        if j < len(s) and s[j] in '-+':
            j += 1
        if j < len(s) and s[j] == '#':
            j += 1
        if j < len(s) and s[j] == '0':
            fill_char = '0'
            while j < len(s) and s[j] == '0':
                j += 1
            while j < len(s) and s[j].isdigit():
                width *= 10 + int(s[j])
                j += 1
            if j >= len(s):
                spec = None
            else:
                spec = s[j]
            if spec is None or spec in 'diouxXeEfFgGcrb%':
                return format(v, s)
            else:
                raise ValueError("Invalid format specifier for int")
        else:
            while j < len(s) and s[j].isdigit():
                width = width * 10 + int(s[j])
                j += 1
            if j < len(s) and s[j] != '.':
                if j < len(s) and not (s[j].isalpha() or s[j] == '%'):
                    fill_char = s[j]
                    j += 1
                    while j < len(s) and s[j].isdigit():
                        width = width * 10 + int(s[j])
                        j += 1
                    spec = None
                    if j < len(s):
                        spec = s[j]
                    if spec is None or spec in 'diouxXeEfFgGcrb%':
