def safe_format(v, s):
    # Emulate format(v, s) where v can be int/float/str/bool
    m = re.match(r'([-+ #0]?\d*\.\d*[bcdeEfFgGn%])', s)
    if not m:
        raise ValueError('unsupported format code %r for object of type %s' % (s[0], type(v).__name__))
    spec = m.group(1)
    if spec == '%':
        return '%'
    if not isinstance(v, (int, float)) or isinstance(v, bool):
        # For str, only some formats work; emulate by trying str.format on a dummy? Actually original used builtin format(v,s) which works on str too.
        # We'll just fall back to using __format__ via format() but that's what we're avoiding. Instead handle explicitly.
        # Since this is fallback, just use format().
        return format(v, s)
    return format(v, s)

