    except TypeError:
        pass
    spec = s if isinstance(s, str) else ''
    if not spec:
        raise ValueError('empty format string')
    fill = align = None
    idx = 0
    n = len(spec)
    if n >= 2 and spec[1] in '<>=^':
        fill = spec[0]; align = spec[1]; idx = 2
    elif n == 1 and spec[0] in '<>=^':
