        width_s += spec[idx]; idx += 1
    type_char = spec[idx:] if idx < n else ''
    t = type_char[0] if type_char else ''
    if t in ('i', 'd', 'o', 'x', 'X', 'b', 'B', 'n'):
        if isinstance(v, int) and not isinstance(v, bool):
            return format(v, type_char)
        elif isinstance(v, float):
            return format(int(v), type_char)
        else:
            raise ValueError('format code %r applied to object of type %s' % (type_char, type(v).__name__))
    elif t in ('f', 'F', 'e', 'E', 'g', 'G', '%'):
        if isinstance(v, float):
            return format(v, type_char)
        elif isinstance(v, int) and not isinstance(v, bool):
            return format(float(v), type_char)
        else:
            raise ValueError('format code %r applied to object of type %s' % (type_char, type(v).__name__))
    elif t in ('c',):
        if isinstance(v, int) and not isinstance(v, bool) and 0 <= v <= 0x10FFFF:
            return chr(v)
        elif isinstance(v, str) and len(v) == 1 and ord(v[0]) <= 0x10FFFF:
            return v
        else:
            raise ValueError('format code %r applied to object of type %s' % (type_char, type(v).__name__))
    else:
        # generic string conversion (including unknown/empty type)
        return format(str(v), '')

