def product(iterable, repeat=1):
    pools = [list(iterable) for _ in range(repeat)]
    indices = [0] * len(pools)
    result = tuple(pool[0] for pool in pools)
    yield result
    while True:
        for i in range(len(pools) - 1, -1, -1):
            idx = indices[i] + 1
            if idx < len(pools[i]):
                indices[i] = idx
                break
            else:
