import base64, random, json
ALPHA = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
IDX = {c: i for i, c in enumerate(ALPHA)}
def model(data, urlsafe=False):
    if urlsafe: data = data.translate(bytes.maketrans(b'-_', b'+/'))
    n = 0; pads = 0
    for c in data:
        if c in IDX: n += 1; pads = 0
        elif c == 0x3d: pads += 1
    rem = n % 4
    if rem == 1 or (rem != 0 and pads < 4 - rem): return "RAISE"
    acc = 0; bits = 0; out = bytearray()
    for c in data:
        if c not in IDX: continue
        acc = (acc << 6) | IDX[c]; bits += 6
        if bits >= 8: bits -= 8; out.append((acc >> bits) & 0xFF)
    return bytes(out)
def cpy(d, u):
    try: return base64.urlsafe_b64decode(d) if u else base64.b64decode(d)
    except Exception: return "RAISE"
bad = []; tot = 0
