# Manual product replacement
def _product(iterable, r):
    pool = list(iterable)
    if not pool:
        yield ()
        return
    index = [0] * r
    while True:
        yield tuple(pool[i] for i in index)
        # find next position to increment
        for pos in range(r - 1, -1, -1):
            if index[pos] < len(pool) - 1:
                break
        else:
            return
        index[pos] += 1
        for j in range(pos + 1, r):
            index[j] = 0

